function initHeroUspMaskHandoff(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.heroUspMaskHandoffCleanup) {
    window.UNCOMMON.heroUspMaskHandoffCleanup();
    window.UNCOMMON.heroUspMaskHandoffCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;
  if (window.innerWidth < 992) return;

  const page = getPageContainer(scope);
  const hero = page?.querySelector("[data-hero]");
  const usp = page?.querySelector("[data-usp]");

  if (!hero || !usp) return;

  const heroCanvas = hero.querySelector("[data-hero-canvas]");
  const transition = usp.querySelector("[data-usp-transition]");
  const card = transition?.querySelector("[data-usp-transition-card]");
  const img = transition?.querySelector("[data-usp-transition-img]");
  const mediaSticky = usp.querySelector(".usp__media-sticky");

  if (!heroCanvas || !transition || !card || !img || !mediaSticky) return;

  const handoffSrc =
    heroCanvas.getAttribute("data-handoff-src") ||
    heroCanvas.getAttribute("data-static-src") ||
    "";

  if (!handoffSrc) {
    console.warn("[Hero/Usp Handoff] Geen data-handoff-src of data-static-src gevonden.");
    return;
  }

  const cleanups = [];
  const ease = gsap.parseEase("uncommon");

  const startSetting =
    usp.getAttribute("data-usp-handoff-start") || "top bottom";

  const endSetting =
    usp.getAttribute("data-usp-handoff-end") || "top 15%";

  const scrubRaw = usp.getAttribute("data-usp-handoff-scrub");
  const scrubSetting =
    scrubRaw == null || scrubRaw === "" ?
    true :
    scrubRaw === "true" ?
    true :
    scrubRaw === "false" ?
    false :
    parseFloat(scrubRaw);

  const hideStartRaw = parseFloat(
    usp.getAttribute("data-usp-handoff-hide-start")
  );

  const hideStart = Number.isFinite(hideStartRaw) ?
    gsap.utils.clamp(0.1, 0.98, hideStartRaw) :
    0.86;

  const canvasFadeEndRaw = parseFloat(
    usp.getAttribute("data-usp-handoff-canvas-fade-end")
  );

  const canvasFadeEnd = Number.isFinite(canvasFadeEndRaw) ?
    gsap.utils.clamp(0.02, 0.3, canvasFadeEndRaw) :
    0.08;

  let hasEnteredHandoff = false;

  function getTargetEl() {
    return usp.querySelector(".usp__media.is-active") || mediaSticky;
  }

  function getStartRect() {
    return {
      x: 0,
      y: 0,
      width: window.innerWidth,
      height: window.innerHeight,
      radius: 0
    };
  }

  function getEndRect() {
    const target = getTargetEl();
    if (!target) return getStartRect();

    const rect = target.getBoundingClientRect();
    const styles = window.getComputedStyle(target);

    const radius =
      parseFloat(styles.borderTopLeftRadius) ||
      parseFloat(styles.borderRadius) ||
      16;

    return {
      x: rect.left,
      y: rect.top,
      width: rect.width,
      height: rect.height,
      radius
    };
  }

  function setInactive({ restoreCanvas = false } = {}) {
    transition.classList.remove("is-active");
    gsap.set(transition, { autoAlpha: 0 });

    if (restoreCanvas) {
      gsap.set(heroCanvas, { autoAlpha: 1 });
    }
  }

  function setActive() {
    transition.classList.add("is-active");
    gsap.set(transition, { autoAlpha: 1 });
  }

  function applyState(progress) {
    const p = gsap.utils.clamp(0, 1, progress);

    if (!img.complete || !img.naturalWidth) {
      setInactive({ restoreCanvas: false });
      return;
    }

    if (p <= 0.001) {
      setInactive({ restoreCanvas: hasEnteredHandoff });
      return;
    }

    if (p >= 0.999) {
      setInactive({ restoreCanvas: false });
      gsap.set(heroCanvas, { autoAlpha: 0 });
      return;
    }

    hasEnteredHandoff = true;

    const ep = ease(p);
    const from = getStartRect();
    const to = getEndRect();

    const x = gsap.utils.interpolate(from.x, to.x, ep);
    const y = gsap.utils.interpolate(from.y, to.y, ep);
    const width = gsap.utils.interpolate(from.width, to.width, ep);
    const height = gsap.utils.interpolate(from.height, to.height, ep);
    const radius = gsap.utils.interpolate(from.radius, to.radius, ep);

    let opacity = 1;
    if (p >= hideStart) {
      const fadeP = (p - hideStart) / (1 - hideStart);
      opacity = 1 - gsap.utils.clamp(0, 1, fadeP);
    }

    const canvasOpacity =
      p <= 0 ?
      1 :
      p >= canvasFadeEnd ?
      0 :
      1 - (p / canvasFadeEnd);

    setActive();

    gsap.set(heroCanvas, {
      autoAlpha: canvasOpacity
    });

    gsap.set(card, {
      x,
      y,
      width,
      height,
      borderRadius: radius,
      clipPath: `inset(0% 0% 0% 0% round ${radius}px)`,
      autoAlpha: opacity,
      force3D: true
    });
  }

  function handleImageReady() {
    ScrollTrigger.refresh();
  }

  if (img.getAttribute("src") !== handoffSrc) {
    img.setAttribute("src", handoffSrc);
  }

  if (img.complete && img.naturalWidth) {
    handleImageReady();
  } else {
    img.addEventListener("load", handleImageReady);
    cleanups.push(() => img.removeEventListener("load", handleImageReady));
  }

  gsap.set(card, {
    x: 0,
    y: 0,
    width: window.innerWidth,
    height: window.innerHeight,
    borderRadius: 0,
    clipPath: "inset(0% 0% 0% 0% round 0px)"
  });

  setInactive({ restoreCanvas: false });

  const st = ScrollTrigger.create({
    __heroUspMaskHandoff: true,
    trigger: usp,
    start: startSetting,
    end: endSetting,
    scrub: Number.isFinite(scrubSetting) ? scrubSetting : true,
    invalidateOnRefresh: true,
    onUpdate: (self) => {
      applyState(self.progress);
    },
    onRefresh: (self) => {
      applyState(self.progress);
    },
    onLeave: () => {
      setInactive({ restoreCanvas: false });
      gsap.set(heroCanvas, { autoAlpha: 0 });
    },
    onLeaveBack: () => {
      setInactive({ restoreCanvas: true });
    }
  });

  cleanups.push(() => st.kill());

  const onResize = () => {
    ScrollTrigger.refresh();
  };

  window.addEventListener("resize", onResize);
  cleanups.push(() => window.removeEventListener("resize", onResize));

  window.UNCOMMON.heroUspMaskHandoffCleanup = function () {
    cleanups.forEach((fn) => fn());
    gsap.killTweensOf([card, heroCanvas]);
    gsap.set(card, { clearProps: "all" });
    gsap.set(heroCanvas, { clearProps: "opacity,visibility" });
    setInactive({ restoreCanvas: false });
    window.UNCOMMON.heroUspMaskHandoffCleanup = null;
  };
}

// ============================================================
// BUNNY PLAYERS
// ============================================================

function initBunnyPlayers(scope = nextPage) {
  const page = getPageContainer(scope);

  // -----------------------------------------
  // SHARED HELPERS
  // -----------------------------------------

  function pad2(n) {
    return (n < 10 ? "0" : "") + n;
  }

  function formatTime(sec) {
    if (!isFinite(sec) || sec < 0) return "00:00";

    const s = Math.floor(sec);
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const r = s % 60;

    return h > 0
      ? h + ":" + pad2(m) + ":" + pad2(r)
      : pad2(m) + ":" + pad2(r);
  }

  function setText(nodes, text) {
    nodes.forEach((n) => (n.textContent = text));
  }

  function bestLevel(levels) {
    if (!levels || !levels.length) return null;
    return levels.reduce((a, b) => ((b.width || 0) > (a.width || 0) ? b : a), levels[0]);
  }

  function safePlay(video) {
    if (!video) return;
    const p = video.play();
    if (p && typeof p.then === "function") p.catch(() => {});
  }

  function readyIfIdle(player, pendingPlay) {
    if (
      !pendingPlay &&
      player.getAttribute("data-player-activated") !== "true" &&
      player.getAttribute("data-player-status") === "idle"
    ) {
      player.setAttribute("data-player-status", "ready");
    }
  }

  function setBeforeRatio(player, updateSize, w, h) {
    if (updateSize !== "true" || !w || !h) return;

    const before = player.querySelector("[data-player-before]");
    if (!before) return;

    before.style.paddingTop = (h / w) * 100 + "%";
  }

  function maybeSetRatioFromVideo(player, updateSize, video) {
    if (updateSize !== "true") return;

    const before = player.querySelector("[data-player-before]");
    if (!before) return;

    const hasPad = before.style.paddingTop && before.style.paddingTop !== "0%";

    if (!hasPad && video.videoWidth && video.videoHeight) {
      setBeforeRatio(player, updateSize, video.videoWidth, video.videoHeight);
    }
  }

  function resolveUrl(base, rel) {
    try {
      return new URL(rel, base).toString();
    } catch (_) {
      return rel;
    }
  }

  function getSourceMeta(src, useHlsJs) {
    return new Promise((resolve) => {
      if (useHlsJs && window.Hls && Hls.isSupported()) {
        try {
          const tmp = new Hls();
          const out = { width: 0, height: 0, duration: NaN };

          tmp.on(Hls.Events.MANIFEST_PARSED, (e, data) => {
            const lvls = (data && data.levels) || tmp.levels || [];
            const best = bestLevel(lvls);

            if (best && best.width && best.height) {
              out.width = best.width;
              out.height = best.height;
            }
          });

          tmp.on(Hls.Events.LEVEL_LOADED, (e, data) => {
            if (data && data.details && isFinite(data.details.totalduration)) {
              out.duration = data.details.totalduration;
            }

            try {
              tmp.destroy();
            } catch (_) {}

            resolve(out);
          });

          tmp.on(Hls.Events.ERROR, () => {
            try {
              tmp.destroy();
            } catch (_) {}

            resolve(out);
          });

          tmp.loadSource(src);
          return;
        } catch (_) {
          resolve({ width: 0, height: 0, duration: NaN });
          return;
        }
      }

      function parseMaster(text) {
        const lines = text.split(/\r?\n/);
        let bestW = 0;
        let bestH = 0;
        let firstMedia = null;
        let lastInf = null;

        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];

          if (line.indexOf("#EXT-X-STREAM-INF:") === 0) {
            lastInf = line;
          } else if (lastInf && line && line[0] !== "#") {
            if (!firstMedia) firstMedia = line.trim();

            const m = /RESOLUTION=(\d+)x(\d+)/.exec(lastInf);

            if (m) {
              const w = parseInt(m[1], 10);
              const h = parseInt(m[2], 10);

              if (w > bestW) {
                bestW = w;
                bestH = h;
              }
            }

            lastInf = null;
          }
        }

        return { bestW, bestH, media: firstMedia };
      }

      function sumDuration(mediaText) {
        let dur = 0;
        const re = /#EXTINF:([\d.]+)/g;
        let m;

        while ((m = re.exec(mediaText))) {
          dur += parseFloat(m[1]);
        }

        return dur;
      }

      fetch(src, { credentials: "omit", cache: "no-store" })
        .then((r) => {
          if (!r.ok) throw new Error();
          return r.text();
        })
        .then((master) => {
          const info = parseMaster(master);

          if (!info.media) {
            resolve({
              width: info.bestW || 0,
              height: info.bestH || 0,
              duration: NaN,
            });
            return;
          }

          const mediaUrl = resolveUrl(src, info.media);

          return fetch(mediaUrl, { credentials: "omit", cache: "no-store" })
            .then((r) => {
              if (!r.ok) throw new Error();
              return r.text();
            })
            .then((mediaText) => {
              resolve({
                width: info.bestW || 0,
                height: info.bestH || 0,
                duration: sumDuration(mediaText),
              });
            });
        })
        .catch(() => resolve({ width: 0, height: 0, duration: NaN }));
    });
  }

  // -----------------------------------------
  // CORE PLAYER BUILDER
  // -----------------------------------------

  function createCore(player, mode) {
    const video = player.querySelector("video");
    if (!video) return null;

    const isInsideAutoTabs = !!player.closest("[data-auto-tabs]");

    const isSafariNative = !!video.canPlayType("application/vnd.apple.mpegurl");
    const canUseHlsJs = !!(window.Hls && Hls.isSupported()) && !isSafariNative;

    const rawAutoplay = player.getAttribute("data-player-autoplay") === "true";
    const autoplay = isInsideAutoTabs ? false : rawAutoplay;

    const initialMuted = player.getAttribute("data-player-muted") === "true";
    const updateSize = player.getAttribute("data-player-update-size");
    const lazyMode = player.getAttribute("data-player-lazy");
    const isLazyTrue = lazyMode === "true";
    const isLazyMeta = lazyMode === "meta";

    let isAttached = false;
    let currentSrc = "";
    let pendingPlay = false;
    let lastPauseBy = "";

    function setStatus(s) {
      if (player.getAttribute("data-player-status") !== s) {
        player.setAttribute("data-player-status", s);
      }
    }

    function setActivated(v) {
      player.setAttribute("data-player-activated", v ? "true" : "false");
    }

    function setMuted(v) {
      video.muted = !!v;
      player.setAttribute("data-player-muted", video.muted ? "true" : "false");
    }

    video.setAttribute("muted", "");
    video.setAttribute("playsinline", "");
    video.setAttribute("webkit-playsinline", "");
    video.playsInline = true;

    if (typeof video.disableRemotePlayback !== "undefined") {
      video.disableRemotePlayback = true;
    }

    if (mode === "background") {
      video.muted = true;
    } else if (mode === "inline") {
      if (autoplay) {
        setMuted(true);
      } else {
        setMuted(initialMuted);
      }
    } else if (mode === "lightbox") {
      video.loop = false;
      setMuted(initialMuted);
    }

    // -----------------------------------------
    // SEAMLESS LOOP
    // -----------------------------------------
    // Important:
    // AutoTabsGallery videos must NOT use the seamless-loop rewind.
    // The gallery owns the playback lifecycle and needs the real ended event.
    const wantsLoop = !isInsideAutoTabs && (mode === "background" || (mode === "inline" && autoplay));

    if (wantsLoop) {
      video.loop = false;
      video.removeAttribute("loop");

      const LOOP_LEAD = 0.3;

      function seekToStart() {
        try {
          if (typeof video.fastSeek === "function") video.fastSeek(0);
          else video.currentTime = 0;
        } catch (_) {}
      }

      function shouldRewind() {
        return (
          video.duration &&
          isFinite(video.duration) &&
          !video.paused &&
          video.currentTime >= video.duration - LOOP_LEAD
        );
      }

      if (typeof video.requestVideoFrameCallback === "function") {
        const onFrame = () => {
          if (shouldRewind()) seekToStart();
          if (!video.ended) video.requestVideoFrameCallback(onFrame);
        };

        video.requestVideoFrameCallback(onFrame);
      } else {
        video.addEventListener("timeupdate", () => {
          if (shouldRewind()) seekToStart();
        });
      }

      video.addEventListener("ended", () => {
        seekToStart();
        safePlay(video);
      });
    }

    if (autoplay) video.autoplay = false;
    if (!player.hasAttribute("data-player-activated")) setActivated(false);

    function attachMedia(src, onReady) {
      if (isAttached && currentSrc === src) {
        if (onReady) onReady();
        return;
      }

      if (player._hls) {
        try {
          player._hls.destroy();
        } catch (_) {}

        player._hls = null;
      }

      isAttached = true;
      currentSrc = src;

      if (isSafariNative) {
        video.preload = isLazyTrue || isLazyMeta ? "auto" : video.preload || "metadata";
        video.src = src;

        video.addEventListener(
          "loadedmetadata",
          function onLoad() {
            video.removeEventListener("loadedmetadata", onLoad);
            readyIfIdle(player, pendingPlay);

            if (updateSize === "true") {
              setBeforeRatio(player, updateSize, video.videoWidth, video.videoHeight);
            }

            if (onReady) onReady();
          },
          { once: true }
        );
      } else if (canUseHlsJs) {
        const hls = new Hls({
          maxBufferLength: 10,
          backBufferLength: 90,
        });

        player._hls = hls;

        hls.attachMedia(video);
        hls.on(Hls.Events.MEDIA_ATTACHED, () => hls.loadSource(src));

        hls.on(Hls.Events.MANIFEST_PARSED, () => {
          readyIfIdle(player, pendingPlay);

          if (updateSize === "true") {
            const best = bestLevel(hls.levels || []);

            if (best && best.width && best.height) {
              setBeforeRatio(player, updateSize, best.width, best.height);
            }
          }

          if (onReady) onReady();
        });

        hls.on(Hls.Events.LEVEL_LOADED, (e, data) => {
          if (data && data.details && isFinite(data.details.totalduration)) {
            const durEls = player.querySelectorAll("[data-player-time-duration]");
            if (durEls.length) setText(durEls, formatTime(data.details.totalduration));
          }
        });
      } else {
        video.src = src;
      }
    }

    video.addEventListener("play", () => {
      setActivated(true);
      setStatus("playing");
    });

    video.addEventListener("playing", () => {
      pendingPlay = false;
      setStatus("playing");
    });

    video.addEventListener("pause", () => {
      pendingPlay = false;
      setStatus("paused");
    });

    video.addEventListener("waiting", () => setStatus("loading"));
    video.addEventListener("canplay", () => readyIfIdle(player, pendingPlay));

    function togglePlay() {
      if (video.paused || video.ended) {
        if ((isLazyTrue || isLazyMeta) && !isAttached) {
          const src = player.getAttribute("data-player-src");
          if (src) attachMedia(src);
        }

        pendingPlay = true;
        lastPauseBy = "";
        setStatus("loading");
        safePlay(video);
      } else {
        lastPauseBy = "manual";
        video.pause();
      }
    }

    function toggleMute() {
      setMuted(!video.muted);
    }

    return {
      player,
      video,
      autoplay,
      rawAutoplay,
      isInsideAutoTabs,
      updateSize,
      isLazyTrue,
      isLazyMeta,
      isSafariNative,
      canUseHlsJs,
      attachMedia,
      setStatus,
      setActivated,
      setMuted,
      togglePlay,
      toggleMute,
      getPendingPlay: () => pendingPlay,
      setPendingPlay: (v) => {
        pendingPlay = v;
      },
      getLastPauseBy: () => lastPauseBy,
      setLastPauseBy: (v) => {
        lastPauseBy = v;
      },
      getIsAttached: () => isAttached,
      getCurrentSrc: () => currentSrc,
      resetAttachment: () => {
        if (player._hls) {
          try {
            player._hls.destroy();
          } catch (_) {}

          player._hls = null;
        }

        isAttached = false;
        currentSrc = "";
      },
    };
  }

  // -----------------------------------------
  // SHARED MODULES
  // -----------------------------------------

  function attachControls(core, { fullscreen }) {
    const { player, video } = core;

    function isFsActive() {
      return !!(document.fullscreenElement || document.webkitFullscreenElement);
    }

    function enterFullscreen() {
      if (player.requestFullscreen) return player.requestFullscreen();
      if (video.requestFullscreen) return video.requestFullscreen();

      if (video.webkitSupportsFullscreen && typeof video.webkitEnterFullscreen === "function") {
        return video.webkitEnterFullscreen();
      }
    }

    function exitFullscreen() {
      if (document.exitFullscreen) return document.exitFullscreen();
      if (document.webkitExitFullscreen) return document.webkitExitFullscreen();

      if (video.webkitDisplayingFullscreen && typeof video.webkitExitFullscreen === "function") {
        return video.webkitExitFullscreen();
      }
    }

    function toggleFullscreen() {
      if (isFsActive() || video.webkitDisplayingFullscreen) exitFullscreen();
      else enterFullscreen();
    }

    function setFsAttr(v) {
      player.setAttribute("data-player-fullscreen", v ? "true" : "false");
    }

    if (fullscreen) {
      document.addEventListener("fullscreenchange", () => setFsAttr(isFsActive()));
      document.addEventListener("webkitfullscreenchange", () => setFsAttr(isFsActive()));
      video.addEventListener("webkitbeginfullscreen", () => setFsAttr(true));
      video.addEventListener("webkitendfullscreen", () => setFsAttr(false));
    }

    player.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-player-control]");
      if (!btn || !player.contains(btn)) return;

      const type = btn.getAttribute("data-player-control");

      if (type === "play" || type === "pause" || type === "playpause") {
        core.togglePlay();
      } else if (type === "mute") {
        core.toggleMute();
      } else if (type === "fullscreen" && fullscreen) {
        toggleFullscreen();
      }
    });
  }

  function attachTimeline(core) {
    const { player, video } = core;

    const timeline = player.querySelector("[data-player-timeline]");
    const progressBar = player.querySelector("[data-player-progress]");
    const bufferedBar = player.querySelector("[data-player-buffered]");
    const handle = player.querySelector("[data-player-timeline-handle]");
    const durEls = player.querySelectorAll("[data-player-time-duration]");
    const progEls = player.querySelectorAll("[data-player-time-progress]");

    function updateTimeTexts() {
      if (durEls.length) setText(durEls, formatTime(video.duration));
      if (progEls.length) setText(progEls, formatTime(video.currentTime));
    }

    video.addEventListener("timeupdate", updateTimeTexts);

    video.addEventListener("loadedmetadata", () => {
      updateTimeTexts();
      maybeSetRatioFromVideo(player, core.updateSize, video);
    });

    video.addEventListener("loadeddata", () => {
      maybeSetRatioFromVideo(player, core.updateSize, video);
    });

    video.addEventListener("playing", () => {
      maybeSetRatioFromVideo(player, core.updateSize, video);
    });

    video.addEventListener("durationchange", updateTimeTexts);

    let rafId;

    function updateProgressVisuals() {
      if (!video.duration) return;

      const pct = (video.currentTime / video.duration) * 100;

      if (progressBar) {
        progressBar.style.transform = "translateX(" + (-100 + pct) + "%)";
      }

      if (handle) {
        handle.style.left = Math.max(0, Math.min(100, pct)) + "%";
      }
    }

    function loop() {
      updateProgressVisuals();

      if (!video.paused && !video.ended) {
        rafId = requestAnimationFrame(loop);
      }
    }

    video.addEventListener("play", () => {
      cancelAnimationFrame(rafId);
      loop();
    });

    video.addEventListener("pause", () => {
      cancelAnimationFrame(rafId);
      updateProgressVisuals();
    });

    video.addEventListener("ended", () => {
      cancelAnimationFrame(rafId);
      updateProgressVisuals();
    });

    function updateBufferedBar() {
      if (!bufferedBar || !video.duration || !video.buffered.length) return;

      const end = video.buffered.end(video.buffered.length - 1);
      const pct = (end / video.duration) * 100;

      bufferedBar.style.transform = "translateX(" + (-100 + pct) + "%)";
    }

    video.addEventListener("progress", updateBufferedBar);
    video.addEventListener("loadedmetadata", updateBufferedBar);
    video.addEventListener("durationchange", updateBufferedBar);

    if (!timeline) return;

    let dragging = false;
    let wasPlaying = false;
    let targetTime = 0;
    let lastSeekTs = 0;
    let seekThrottle = 180;
    let rect = null;

    window.addEventListener("resize", () => {
      if (!dragging) rect = null;
    });

    function fracFromX(x) {
      if (!rect) rect = timeline.getBoundingClientRect();

      const f = (x - rect.left) / rect.width;
      return f < 0 ? 0 : f > 1 ? 1 : f;
    }

    function previewAt(f) {
      if (!video.duration) return;

      const pct = f * 100;

      if (progressBar) {
        progressBar.style.transform = "translateX(" + (-100 + pct) + "%)";
      }

      if (handle) {
        handle.style.left = pct + "%";
      }

      if (progEls.length) {
        setText(progEls, formatTime(f * video.duration));
      }
    }

    function maybeSeek(now) {
      if (!video.duration) return;
      if (now - lastSeekTs < seekThrottle) return;

      lastSeekTs = now;
      video.currentTime = targetTime;
    }

    function onDown(e) {
      if (!video.duration) return;

      dragging = true;
      wasPlaying = !video.paused && !video.ended;

      if (wasPlaying) video.pause();

      player.setAttribute("data-timeline-drag", "true");

      rect = timeline.getBoundingClientRect();

      const f = fracFromX(e.clientX);
      targetTime = f * video.duration;

      previewAt(f);
      maybeSeek(performance.now());

      timeline.setPointerCapture && timeline.setPointerCapture(e.pointerId);

      window.addEventListener("pointermove", onMove, { passive: false });
      window.addEventListener("pointerup", onUp, { passive: true });

      e.preventDefault();
    }

    function onMove(e) {
      if (!dragging) return;

      const f = fracFromX(e.clientX);
      targetTime = f * video.duration;

      previewAt(f);
      maybeSeek(performance.now());

      e.preventDefault();
    }

    function onUp() {
      if (!dragging) return;

      dragging = false;
      player.setAttribute("data-timeline-drag", "false");
      rect = null;

      video.currentTime = targetTime;

      if (wasPlaying) {
        safePlay(video);
      } else {
        updateProgressVisuals();
        updateTimeTexts();
      }

      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    }

    timeline.addEventListener("pointerdown", onDown, { passive: false });

    if (handle) {
      handle.addEventListener("pointerdown", onDown, { passive: false });
    }
  }

  function attachHoverIdle(core, hideDelay = 3000) {
    const { player } = core;
    let hoverTimer;

    function setHover(state) {
      if (player.getAttribute("data-player-hover") !== state) {
        player.setAttribute("data-player-hover", state);
      }
    }

    function scheduleHide() {
      clearTimeout(hoverTimer);
      hoverTimer = setTimeout(() => setHover("idle"), hideDelay);
    }

    function wake() {
      setHover("active");
      scheduleHide();
    }

    player.addEventListener("pointerdown", wake);
    document.addEventListener("fullscreenchange", wake);
    document.addEventListener("webkitfullscreenchange", wake);

    let tracking = false;

    function onMove(e) {
      const r = player.getBoundingClientRect();

      if (
        e.clientX >= r.left &&
        e.clientX <= r.right &&
        e.clientY >= r.top &&
        e.clientY <= r.bottom
      ) {
        wake();
      }
    }

    player.addEventListener("pointerenter", () => {
      wake();

      if (!tracking) {
        tracking = true;
        window.addEventListener("pointermove", onMove, { passive: true });
      }
    });

    player.addEventListener("pointerleave", () => {
      setHover("idle");
      clearTimeout(hoverTimer);

      if (tracking) {
        tracking = false;
        window.removeEventListener("pointermove", onMove);
      }
    });
  }

  function attachInViewAutoplay(core) {
    const { player, video } = core;

    if (core.isInsideAutoTabs) return;

    if (player._io) {
      try {
        player._io.disconnect();
      } catch (_) {}
    }

    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const inView = entry.isIntersecting && entry.intersectionRatio > 0;

          if (inView) {
            if ((core.isLazyTrue || core.isLazyMeta) && !core.getIsAttached()) {
              const src = player.getAttribute("data-player-src");
              if (src) core.attachMedia(src);
            }

            if (video.paused) {
              core.setLastPauseBy("");
              core.setPendingPlay(true);
              core.setStatus("loading");
              safePlay(video);
            } else {
              core.setStatus("playing");
            }
          } else {
            if (!video.paused && !video.ended) {
              core.setLastPauseBy("io");
              video.pause();
              core.setStatus("paused");
            }
          }
        });
      },
      { threshold: 0.1 }
    );

    io.observe(player);
    player._io = io;
  }

  // -----------------------------------------
  // LAZY PLAYER INIT
  // -----------------------------------------

  function lazyInitPlayers(players, initPlayer, options = {}) {
    const rootMargin = options.rootMargin || "400px 0px";
    const immediatePersist = options.immediatePersist !== false;

    if (!players.length) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;

          const player = entry.target;

          if (player.dataset.playerLoaded === "true") {
            observer.unobserve(player);
            return;
          }

          player.dataset.playerLoaded = "true";
          initPlayer(player);

          observer.unobserve(player);
        });
      },
      {
        rootMargin,
        threshold: 0,
      }
    );

    players.forEach((player) => {
      const isPersistent = player.getAttribute("data-player-persist") === "true";

      if (immediatePersist && isPersistent) {
        if (player.dataset.playerLoaded === "true") return;

        player.dataset.playerLoaded = "true";
        initPlayer(player);
        return;
      }

      observer.observe(player);
    });
  }

  // -----------------------------------------
  // MODE: BACKGROUND
  // -----------------------------------------

  function initBackground() {
    const players = [
      ...Array.from(page?.querySelectorAll("[data-bunny-background-init]") || []),
      ...Array.from(
        document.querySelectorAll('[data-bunny-background-init][data-player-persist="true"]')
      ),
    ].filter((p, i, arr) => arr.indexOf(p) === i);

    function initBackgroundPlayer(player) {
      const isPersistent = player.getAttribute("data-player-persist") === "true";

      if (isPersistent && player.__bunnyPersistentInitDone) return;
      if (player.__bunnyBackgroundInitDone) return;

      player.__bunnyBackgroundInitDone = true;

      const src = player.getAttribute("data-player-src");
      if (!src) return;

      const video = player.querySelector("video");
      if (!video) return;

      if (!isPersistent) {
        try {
          video.pause();
        } catch (_) {}

        try {
          video.removeAttribute("src");
          video.load();
        } catch (_) {}
      }

      if (isPersistent) {
        player.__bunnyPersistentInitDone = true;
        player.setAttribute("data-player-persistent-ready", "true");
      }

      const core = createCore(player, "background");
      if (!core) return;

      attachControls(core, { fullscreen: false });

      // AutoTabs videos need their source attached,
      // but playback is controlled by initAutoTabsGallery.
      if (core.isLazyTrue && !core.isInsideAutoTabs) {
        video.preload = "none";
      } else {
        core.attachMedia(src);
      }

      if (core.autoplay) attachInViewAutoplay(core);
    }

    lazyInitPlayers(players, initBackgroundPlayer, {
      rootMargin: "400px 0px",
    });
  }

  // -----------------------------------------
  // MODE: INLINE
  // -----------------------------------------

  function initInline() {
    const players = [
      ...Array.from(page?.querySelectorAll("[data-bunny-player-init]") || []),
      ...Array.from(document.querySelectorAll('[data-bunny-player-init][data-player-persist="true"]')),
    ].filter((p, i, arr) => arr.indexOf(p) === i);

    function initInlinePlayer(player) {
      const isPersistent = player.getAttribute("data-player-persist") === "true";

      if (isPersistent && player.__bunnyPersistentInitDone) return;
      if (player.__bunnyInlineInitDone) return;

      player.__bunnyInlineInitDone = true;

      const src = player.getAttribute("data-player-src");
      if (!src) return;

      const video = player.querySelector("video");
      if (!video) return;

      if (!isPersistent) {
        try {
          video.pause();
        } catch (_) {}

        try {
          video.removeAttribute("src");
          video.load();
        } catch (_) {}
      }

      if (isPersistent) {
        player.__bunnyPersistentInitDone = true;
        player.setAttribute("data-player-persistent-ready", "true");
      }

      const core = createCore(player, "inline");
      if (!core) return;

      attachControls(core, { fullscreen: true });
      attachTimeline(core);
      attachHoverIdle(core);

      const { updateSize, isLazyMeta, isLazyTrue } = core;

      if (updateSize === "true" && !isLazyMeta) {
        if (!isLazyTrue || core.isInsideAutoTabs) {
          const prev = video.preload;

          video.preload = "metadata";

          video.addEventListener(
            "loadedmetadata",
            function onMeta() {
              video.removeEventListener("loadedmetadata", onMeta);
              setBeforeRatio(player, updateSize, video.videoWidth, video.videoHeight);
              video.preload = prev || "";
            },
            { once: true }
          );

          video.src = src;
        }
      }

      if (isLazyMeta && !core.isInsideAutoTabs) {
        getSourceMeta(src, core.canUseHlsJs).then((meta) => {
          if (meta.width && meta.height) {
            setBeforeRatio(player, updateSize, meta.width, meta.height);
          }

          const durEls = player.querySelectorAll("[data-player-time-duration]");

          if (durEls.length && isFinite(meta.duration) && meta.duration > 0) {
            setText(durEls, formatTime(meta.duration));
          }

          readyIfIdle(player, core.getPendingPlay());
        });

        video.preload = "none";
      } else if (isLazyTrue && !core.isInsideAutoTabs) {
        video.preload = "none";
      } else {
        core.attachMedia(src);
      }

      if (core.autoplay) attachInViewAutoplay(core);
    }

    lazyInitPlayers(players, initInlinePlayer, {
      rootMargin: "400px 0px",
    });
  }

  // -----------------------------------------
  // MODE: LIGHTBOX
  // -----------------------------------------

function initLightbox() {
  const player = document.querySelector("[data-bunny-lightbox-init]");
  if (!player) return;

  if (player.__bunnyLightboxInitDone) return;
  player.__bunnyLightboxInitDone = true;

  const wrapper = player.closest("[data-bunny-lightbox-status]");
  if (!wrapper) return;

  const video = player.querySelector("video");
  if (!video) return;

  try {
    video.pause();
  } catch (_) {}

  try {
    video.removeAttribute("src");
    video.load();
  } catch (_) {}

  const core = createCore(player, "lightbox");
  if (!core) return;

  attachControls(core, { fullscreen: true });
  attachTimeline(core);
  attachHoverIdle(core);

  const { updateSize } = core;
  const placeholderImg = player.querySelector("[data-bunny-lightbox-placeholder]");

  let autoStartOnReady = false;

  function resetTimelineUI() {
    const progressBar = player.querySelector("[data-player-progress]");
    const bufferedBar = player.querySelector("[data-player-buffered]");
    const handle = player.querySelector("[data-player-timeline-handle]");
    const progEls = player.querySelectorAll("[data-player-time-progress]");

    if (progressBar) {
      progressBar.style.transform = "translateX(-100%)";
    }

    if (bufferedBar) {
      bufferedBar.style.transform = "translateX(-100%)";
    }

    if (handle) {
      handle.style.left = "0%";
    }

    if (progEls.length) {
      setText(progEls, "00:00");
    }
  }

  function stopAndResetVideo() {
    autoStartOnReady = false;

    try {
      video.pause();
    } catch (_) {}

    try {
      video.currentTime = 0;
    } catch (_) {}

    resetTimelineUI();

    core.setPendingPlay(false);
    core.setActivated(false);
    core.setStatus("idle");
  }

  function setupClamp() {
    const calcBox = wrapper.querySelector("[data-bunny-lightbox-calc-height]");
    if (!calcBox) return;

    function getRatio() {
      if (updateSize === "cover") return null;

      if (updateSize === "true") {
        if (video.videoWidth && video.videoHeight) {
          return video.videoWidth / video.videoHeight;
        }

        const before = player.querySelector("[data-player-before]");

        if (before && before.style.paddingTop) {
          const pct = parseFloat(before.style.paddingTop);
          if (pct > 0) return 100 / pct;
        }
      }

      const r = player.getBoundingClientRect();
      if (r.height > 0) return r.width / r.height;

      return 16 / 9;
    }

    function apply() {
      if (updateSize === "cover") {
        calcBox.style.maxWidth = "";
        calcBox.style.maxHeight = "";
        return;
      }

      const cs = getComputedStyle(wrapper);
      const pt = parseFloat(cs.paddingTop) || 0;
      const pb = parseFloat(cs.paddingBottom) || 0;
      const pl = parseFloat(cs.paddingLeft) || 0;
      const pr = parseFloat(cs.paddingRight) || 0;

      const cw = wrapper.clientWidth - pl - pr;
      const ch = wrapper.clientHeight - pt - pb;

      if (cw <= 0 || ch <= 0) return;

      const ratio = getRatio();

      if (!ratio) {
        calcBox.style.maxWidth = "";
        calcBox.style.maxHeight = "";
        return;
      }

      const hIfFullWidth = cw / ratio;

      if (hIfFullWidth <= ch) {
        calcBox.style.maxWidth = "100%";
        calcBox.style.maxHeight = (hIfFullWidth / ch) * 100 + "%";
      } else {
        calcBox.style.maxHeight = "100%";
        calcBox.style.maxWidth = ((ch * ratio) / cw) * 100 + "%";
      }
    }

    let pending = false;

    function debounced() {
      if (pending) return;
      if (wrapper.getAttribute("data-bunny-lightbox-status") !== "active") return;

      pending = true;

      requestAnimationFrame(() => {
        pending = false;
        apply();
      });
    }

    new ResizeObserver(debounced).observe(wrapper);

    window.addEventListener("resize", debounced);
    window.addEventListener("orientationchange", debounced);

    if (updateSize === "true") {
      video.addEventListener("loadedmetadata", debounced);
      video.addEventListener("loadeddata", debounced);
      video.addEventListener("playing", debounced);
    }

    player._applyClamp = debounced;
    debounced();
  }

  setupClamp();

  function ensureOpenUI(active) {
    const state = active ? "active" : "not-active";

    if (wrapper.getAttribute("data-bunny-lightbox-status") !== state) {
      wrapper.setAttribute("data-bunny-lightbox-status", state);
    }

    if (active && typeof player._applyClamp === "function") {
      player._applyClamp();
    }
  }

  function exitFullscreenIfNeeded() {
    if (
      document.fullscreenElement ||
      document.webkitFullscreenElement ||
      video.webkitDisplayingFullscreen
    ) {
      if (document.exitFullscreen) document.exitFullscreen();
      else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
      else if (video.webkitExitFullscreen) video.webkitExitFullscreen();
    }
  }

  function planOnOpen(nextSrc) {
    const same = core.getCurrentSrc() === nextSrc;

    if (!same) {
      stopAndResetVideo();
      core.resetAttachment();

      const durEls = player.querySelectorAll("[data-player-time-duration]");
      if (durEls.length) setText(durEls, "00:00");

      core.attachMedia(nextSrc, () => {
        if (
          autoStartOnReady &&
          wrapper.getAttribute("data-bunny-lightbox-status") === "active"
        ) {
          core.setStatus("loading");
          safePlay(video);
          autoStartOnReady = false;
        }
      });

      autoStartOnReady = !!core.autoplay;
      core.setPendingPlay(!!core.autoplay);
    } else {
      autoStartOnReady = !!core.autoplay;

      try {
        video.currentTime = 0;
      } catch (_) {}

      if (core.autoplay) {
        core.setStatus("loading");
        safePlay(video);
      } else {
        stopAndResetVideo();
      }
    }
  }

  function openLightbox(src, placeholderUrl) {
    if (!src) return;

    function activate() {
      ensureOpenUI(true);
      planOnOpen(src);
    }

    if (placeholderImg && placeholderUrl) {
      const needsSwap = placeholderImg.getAttribute("src") !== placeholderUrl;

      if (needsSwap || !placeholderImg.complete || !placeholderImg.naturalWidth) {
        placeholderImg.onload = () => {
          placeholderImg.onload = null;
          activate();
        };

        placeholderImg.onerror = () => {
          placeholderImg.onerror = null;
          activate();
        };

        if (needsSwap) {
          placeholderImg.setAttribute("src", placeholderUrl);
        } else {
          placeholderImg.dispatchEvent(new Event("load"));
        }
      } else {
        activate();
      }
    } else {
      activate();
    }
  }

  function closeLightbox() {
    ensureOpenUI(false);
    exitFullscreenIfNeeded();
    stopAndResetVideo();
  }

  video.addEventListener("ended", () => {
    closeLightbox();
  });

  document.addEventListener("click", (e) => {
    const openBtn = e.target.closest('[data-bunny-lightbox-control="open"]');

    if (openBtn) {
      const src = openBtn.getAttribute("data-bunny-lightbox-src") || "";
      if (!src) return;

      const imgEl = openBtn.querySelector("[data-bunny-lightbox-placeholder]");
      const placeholderUrl = imgEl ? imgEl.getAttribute("src") : "";

      openLightbox(src, placeholderUrl);
      return;
    }

    const closeBtn = e.target.closest('[data-bunny-lightbox-control="close"]');

    if (closeBtn) {
      const closeInWrapper = closeBtn.closest("[data-bunny-lightbox-status]");
      if (closeInWrapper === wrapper) closeLightbox();
      return;
    }

    const isActive = wrapper.getAttribute("data-bunny-lightbox-status") === "active";
    if (!isActive) return;

    const clickedInsidePlayer = !!e.target.closest("[data-bunny-lightbox-init]");
    const clickedInsideCalcBox = !!e.target.closest("[data-bunny-lightbox-calc-height]");
    const clickedInsideControls = !!e.target.closest("[data-player-control], [data-player-timeline]");

    const clickedInsideWrapper = wrapper.contains(e.target);

    if (
      clickedInsideWrapper &&
      !clickedInsidePlayer &&
      !clickedInsideCalcBox &&
      !clickedInsideControls
    ) {
      closeLightbox();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeLightbox();
    }
  });
}

  // -----------------------------------------
  // RUN MODES
  // -----------------------------------------

  initBackground();
  initInline();
  initLightbox();
}

function initMediaSetup(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};
  window.UNCOMMON.mediaRuntimePlayed = window.UNCOMMON.mediaRuntimePlayed || {};

  const page = getPageContainer(scope);
  const mediaElements = [...(page?.querySelectorAll("[data-media-init]") || [])];
  if (!mediaElements.length) return;

  initMediaSetup._cleanup?.forEach((fn) => fn());
  const cleanupFns = [];

  const pauseDelay = 200;
  const viewportOffset = 0.1;
  const isHoverDevice = window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  const rootMarginValue = viewportOffset * 100;

  mediaElements.forEach((mediaEl) => {
    const video = mediaEl.querySelector("[data-media-video-src]");
    if (!video) return;

    const mode = mediaEl.dataset.mediaMode || "autoplay";
    const touchMode = mediaEl.dataset.mediaTouchMode;
    const resetAttr = mediaEl.dataset.mediaReset;
    const pausedStatusAttr = mediaEl.dataset.mediaOnPause;
    const mediaId = mediaEl.dataset.mediaId;
    const toggleElements = [...mediaEl.querySelectorAll("[data-media-toggle]")];

    const replayButtons = mediaId ? [...document.querySelectorAll(
      `[data-media-replay="${mediaId}"]`)] : [...mediaEl.querySelectorAll(
      "[data-media-replay]")];

    const playOnce = mediaEl.dataset.mediaOnce === "true" || mode === "once";
    const effectiveMode = mode === "once" ? "autoplay" : mode;

    const activeMode = !isHoverDevice ?
      (touchMode || (effectiveMode === "hover" ? "autoplay" : effectiveMode)) :
      effectiveMode;

    const shouldUseClickToggle =
      activeMode === "click" || (activeMode === "autoplay" && toggleElements.length);

    const shouldResetOnPause =
      resetAttr === "true" ?
      true :
      resetAttr === "false" ?
      false :
      activeMode === "hover";

    const pausedStatus = pausedStatusAttr === "paused" ? "paused" : "not-active";

    const clickTargets = toggleElements.length ? toggleElements : [mediaEl];

    // -----------------------------------------
    // Runtime once key
    // -----------------------------------------
    const runtimeOnceKey =
      mediaEl.getAttribute("data-media-runtime-once") ||
      mediaEl.getAttribute("data-media-once-key") ||
      (mediaEl.hasAttribute("data-home-hero-primary-media") ? "home-hero-intro" : null);

    const runtimePlayed = !!(
      runtimeOnceKey &&
      (
        window.UNCOMMON.mediaRuntimePlayed[runtimeOnceKey] === true ||
        (runtimeOnceKey === "home-hero-intro" && window.UNCOMMON.homeHeroIntroPlayed === true)
      )
    );

    function markRuntimePlayed() {
      if (!runtimeOnceKey) return;
      window.UNCOMMON.mediaRuntimePlayed[runtimeOnceKey] = true;

      if (runtimeOnceKey === "home-hero-intro") {
        window.UNCOMMON.homeHeroIntroPlayed = true;
      }

      mediaEl.setAttribute("data-media-runtime-played", "true");
    }

    if (runtimePlayed) {
      mediaEl.setAttribute("data-media-runtime-played", "true");
    } else {
      mediaEl.removeAttribute("data-media-runtime-played");
    }

    // -----------------------------------------
    // State
    // -----------------------------------------
    let isInView = false;
    let isHovering = false;
    let hasLoaded = false;
    let userPaused = false;
    let userActivated = false;
    let isActivated = false;
    let shouldBePlaying = false;
    let hasPlayedOnce = runtimePlayed;
    let isReplaying = false;
    let playOnceDone = runtimePlayed;
    let pauseTimer = null;
    let observer = null;

    const setStatus = (status) => {
      mediaEl.dataset.mediaStatus = status;
    };

    const clearPauseTimer = () => clearTimeout(pauseTimer);
    const addCleanup = (fn) => cleanupFns.push(fn);

    const on = (target, event, handler, options) => {
      target.addEventListener(event, handler, options);
      addCleanup(() => target.removeEventListener(event, handler, options));
    };

    const lockReplayButtons = () => {
      replayButtons.forEach((btn) => {
        btn.setAttribute("data-media-replay-locked", "true");
        btn.style.pointerEvents = "none";
      });
    };

    const unlockReplayButtons = () => {
      replayButtons.forEach((btn) => {
        btn.removeAttribute("data-media-replay-locked");
        btn.style.pointerEvents = "";
      });
    };

    const animateReplayIcon = (btn) => {
      const icon = btn.querySelector(".replay-icon_svg");
      if (icon && typeof gsap !== "undefined") {
        gsap.fromTo(
          icon, { rotation: 0 },
          {
            rotation: -360,
            duration: 0.6,
            ease: "power2.out"
          }
        );
      }
    };

    const playAttempt = () => {
      const p = video.play();
      if (p && typeof p.then === "function") {
        p.then(() => {
          if (shouldBePlaying) setStatus("playing");
        }).catch(() => {});
      }
    };

    const loadVideo = () => {
      if (hasLoaded) return;

      const src = video.dataset.mediaVideoSrc;
      if (!src) return;

      video.muted = true;
      video.playsInline = true;
      video.setAttribute("muted", "");
      video.setAttribute("playsinline", "");
      video.setAttribute("webkit-playsinline", "");

      if (playOnce) {
        video.loop = false;
        video.removeAttribute("loop");
      }

      video.src = src;
      video.load();
      hasLoaded = true;
    };

    const shouldResume = () => {
      if (!isInView || document.hidden) return false;
      if (playOnce && hasPlayedOnce && !isReplaying) return false;
      if (activeMode === "autoplay") return !userPaused;
      if (activeMode === "click") return userActivated && !userPaused;
      return isHovering;
    };

    const playVideo = () => {
      if (!isInView || document.hidden) return;
      if (playOnce && hasPlayedOnce && !isReplaying) return;

      shouldBePlaying = true;
      clearPauseTimer();
      loadVideo();
      setStatus(video.readyState < 3 ? "loading" : "playing");
      playAttempt();
    };

    const pauseVideo = (delay = 0, reset = false) => {
      shouldBePlaying = false;
      clearPauseTimer();

      pauseTimer = setTimeout(() => {
        try {
          video.pause();
          if (reset) video.currentTime = 0;
        } catch (_) {}
      }, delay);
    };

    const handlePlayOnceEnd = () => {
      if (playOnceDone) return;

      playOnceDone = true;

      try {
        video.pause();
        if (video.duration) video.currentTime = video.duration - 0.05;
      } catch (_) {}

      hasPlayedOnce = true;
      isReplaying = false;
      shouldBePlaying = false;

      markRuntimePlayed();
      setStatus("ended");

      if (replayButtons.length) unlockReplayButtons();
    };

    // -----------------------------------------
    // Replay button state at init
    // -----------------------------------------
    if (replayButtons.length) {
      if (runtimePlayed) unlockReplayButtons();
      else lockReplayButtons();
    }

    replayButtons.forEach((btn) => {
      const handleReplayClick = (e) => {
        e.preventDefault();

        if (btn.getAttribute("data-media-replay-locked") === "true") return;

        lockReplayButtons();
        animateReplayIcon(btn);

        playOnceDone = false;
        isReplaying = true;
        hasPlayedOnce = false;
        userPaused = false;

        video.loop = false;
        video.removeAttribute("loop");

        try {
          video.currentTime = 0;
        } catch (_) {}

        playVideo();
      };

      btn.addEventListener("click", handleReplayClick);
      addCleanup(() => btn.removeEventListener("click", handleReplayClick));
    });

    const handleHoverIn = () => {
      if (!isInView || document.hidden) return;
      isHovering = true;
      clearPauseTimer();

      if (!video.paused) {
        shouldBePlaying = true;
        setStatus("playing");
        return;
      }

      playVideo();
    };

    const handleHoverOut = () => {
      if (!isInView) return;
      isHovering = false;
      setStatus(pausedStatus);
      pauseVideo(pauseDelay, shouldResetOnPause);
    };

    const handleClick = () => {
      if (!isInView || document.hidden) return;
      clearPauseTimer();

      if (video.paused) {
        userActivated = true;
        userPaused = false;
        playVideo();
      } else {
        userActivated = true;
        userPaused = true;
        setStatus(pausedStatus);
        pauseVideo(pauseDelay, shouldResetOnPause);
      }
    };

    const handleViewport = (entries) => {
      entries.forEach((entry) => {
        if (entry.target !== mediaEl) return;

        if (!isActivated && entry.isIntersecting) {
          isActivated = true;

          if (shouldUseClickToggle) {
            clickTargets.forEach((toggleEl) => on(toggleEl, "click", handleClick));
          }

          if (activeMode === "hover") {
            on(mediaEl, "mouseenter", handleHoverIn);
            on(mediaEl, "mouseleave", handleHoverOut);
          }
        }

        isInView = entry.isIntersecting;

        if (isInView) {
          if (shouldResume()) playVideo();
        } else {
          isHovering = false;

          if (!video.paused || shouldBePlaying) {
            setStatus("paused");
            pauseVideo(0, false);
          }
        }
      });
    };

    const handlePageVisibilityChange = () => {
      if (document.hidden) {
        if (!video.paused || shouldBePlaying) {
          setStatus("paused");
          pauseVideo(0, false);
        }
        return;
      }

      if (shouldResume()) playVideo();
    };

    // -----------------------------------------
    // Initial status
    // -----------------------------------------
    if (runtimePlayed && playOnce) {
      setStatus("not-active");
    } else {
      setStatus("not-active");
    }

    observer = new IntersectionObserver(handleViewport, {
      rootMargin: `${rootMarginValue}% 0px ${rootMarginValue}% 0px`,
      threshold: 0
    });

    observer.observe(mediaEl);

    on(video, "playing", () => {
      if (shouldBePlaying) setStatus("playing");
    });

    on(video, "waiting", () => {
      if (shouldBePlaying) setStatus("loading");
    });

    on(video, "canplay", () => {
      if (shouldBePlaying && isInView && !document.hidden) playAttempt();
    });

    on(video, "loadeddata", () => {
      if (shouldBePlaying && isInView && !document.hidden) playAttempt();
    });

    on(video, "timeupdate", () => {
      if (!playOnce) return;

      if (playOnceDone) {
        if (video.duration && video.currentTime < video.duration - 0.1) {
          try {
            video.currentTime = video.duration - 0.05;
          } catch (_) {}
        }
        return;
      }

      if (!shouldBePlaying) return;

      if (video.duration && video.currentTime >= video.duration - 0.05) {
        handlePlayOnceEnd();
      }
    });

    on(video, "ended", () => {
      if (playOnce) {
        handlePlayOnceEnd();
        return;
      }

      if (!shouldBePlaying || !isInView || document.hidden) return;

      try {
        video.currentTime = 0;
      } catch (_) {}

      playAttempt();
    });

    on(document, "visibilitychange", handlePageVisibilityChange);

    addCleanup(() => observer?.disconnect());
    addCleanup(() => {
      clearPauseTimer();
      shouldBePlaying = false;

      try {
        video.pause();
      } catch (_) {}
    });
  });

  initMediaSetup._cleanup = cleanupFns;
}

function toggleModalMedia(scope, action) {
  if (!scope) return;

  const mediaElements = scope.querySelectorAll("[data-media-init]");

  mediaElements.forEach((mediaEl) => {
    const video = mediaEl.querySelector("[data-media-video-src]");
    if (!video) return;

    if (action === "play") {
      const mode = mediaEl.dataset.mediaMode || "autoplay";
      const playOnce = mode === "once" || mediaEl.dataset.mediaOnce === "true";

      // Lazy-load src bij eerste activatie
      if (!video.src) {
        const src = video.dataset.mediaVideoSrc;
        if (!src) return;

        video.muted = true;
        video.playsInline = true;
        video.setAttribute("muted", "");
        video.setAttribute("playsinline", "");
        video.setAttribute("webkit-playsinline", "");
        video.src = src;
        video.load();
      }

      // Loop tenzij expliciet "once"
      video.loop = !playOnce;
      if (playOnce) {
        video.removeAttribute("loop");
      }

      // Reset zodat de video elke keer vooraan begint
      try {
        video.currentTime = 0;
      } catch (_) {}

      mediaEl.dataset.mediaStatus = "playing";

      const playPromise = video.play();
      if (playPromise && typeof playPromise.then === "function") {
        playPromise.catch(() => {
          // Autoplay geblokkeerd — status blijft staan
        });
      }
    } else if (action === "stop") {
      try {
        video.pause();
        video.currentTime = 0;
      } catch (_) {}

      mediaEl.dataset.mediaStatus = "not-active";
    }
  });
}

// -----------------------------------------
// CONFIGURATOR
// -----------------------------------------
function initConfigurator(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.configuratorCleanup) {
    window.UNCOMMON.configuratorCleanup();
    window.UNCOMMON.configuratorCleanup = null;
  }

  const page = getPageContainer(scope);
  const root = page?.querySelector("[data-configurator]");
  if (!root) return;

  const STRIPE_LINKS = {
    "EXR-EEA-ST-SY-SWP": "https://buy.stripe.com/bJe7sM7IA60z3gM8UCgYU06",
    "EXR-EEA-ST-SY-NOSWP": "https://buy.stripe.com/14A8wQbYQ4Wv6sY3AigYU07",
    "EXR-EEA-ST-RG-SWP": "https://buy.stripe.com/fZucN65As60zbNi3AigYU08",
    "EXR-EEA-ST-RG-NOSWP": "https://buy.stripe.com/7sY7sMfb24WvcRmeeWgYU09"
  };

  const PRICING = {
    "eu-uk": {
      standard: { base: 14750, label: "€ 14.750" }
    }
  };

  const SWAP_PRICE = 3450;
  const VOUCHER_AMOUNT = 99;

  const state = {
    region: null,
    edition: null,
    color: null,
    swap: null
  };

  const allOptions = Array.from(root.querySelectorAll("[data-config-option]"));
  const allSteps = Array.from(root.querySelectorAll("[data-config-step]"));
  const highlightLists = Array.from(root.querySelectorAll("[data-config-highlights-list]"));
  const stepValueLabels = Array.from(root.querySelectorAll("[data-config-step-value]"));
  const summaryTexts = Array.from(root.querySelectorAll("[data-config-summary-text]"));
  const hiddenFields = Array.from(root.querySelectorAll("[data-config-hidden]"));

  const reserveBtn = root.querySelector("[data-config-reserve]");
  const reserveBtnEu = root.querySelector("[data-config-reserve-eu]");

  const priceEl = root.querySelector("[data-config-price]");
  const priceElEu = root.querySelector("[data-config-price-eu]");

  const stickyBar = root.querySelector("[data-config-sticky-bar]");
  const stickyConfig = root.querySelector("[data-config-sticky-config]");
  const stickyDelivery = root.querySelector("[data-config-sticky-delivery]");
  const stickyPay = root.querySelector("[data-config-sticky-pay]");
  const stickyVoucher = root.querySelector("[data-config-sticky-voucher]");
  const stickyBtn = root.querySelector("[data-config-sticky-btn]");

  const cleanups = [];
  let regionScrollTimer = null;
  let hasScrolledAfterRegion = false;

  // Editions die niet meer besteld kunnen worden
  const SOLD_OUT_EDITIONS = ["founders"];

  const STEP_FLOW = {
    "eu-uk": ["region", "edition", "color", "battery", "swap", "cta"],
    "row": ["region", "color", "battery", "swap", "waitlist"]
  };

  const REGION_LABELS = {
    "eu-uk": "Europe",
    "row": "Rest of world"
  };

  const EDITION_LABELS = {
    founders: "Founders Edition",
    standard: "Standard Edition"
  };

  function getOptionsForGroup(group) {
    return allOptions.filter(
      (opt) => opt.getAttribute("data-config-option") === group
    );
  }

  function setActiveOption(group, value) {
    getOptionsForGroup(group).forEach((opt) => {
      const isActive = opt.getAttribute("data-config-value") === value;
      opt.classList.toggle("is-active", isActive);
    });
  }

  function getStepEl(name) {
    return allSteps.find((s) => s.getAttribute("data-config-step") === name);
  }

  function getProductCode() {
    if (!state.region || state.region === "row") return null;

    const regionMap = { "eu-uk": "EEA" };
    const editionMap = { standard: "ST" };
    const colorMap = { "stern-yellow": "SY", "rock-grey": "RG" };
    const swapMap = { swap: "SWP", "no-swap": "NOSWP" };

    const r = regionMap[state.region];
    const ed = editionMap[state.edition] || "ST";
    const c = colorMap[state.color];
    const s = swapMap[state.swap];

    if (!r || !c || !s) return null;
    return `EXR-${r}-${ed}-${c}-${s}`;
  }

  function getStripeUrl() {
    const code = getProductCode();
    if (!code) return "#";
    return STRIPE_LINKS[code] || "#";
  }

  function getTotalPrice() {
    const regionPricing = PRICING[state.region];
    if (!regionPricing) return null;

    const ed = state.edition || "standard";
    const editionPricing = regionPricing[ed];
    if (!editionPricing) return null;

    let total = editionPricing.base;
    if (state.swap === "swap") total += SWAP_PRICE;
    return total;
  }

  function formatPrice(amount) {
    return "€ " + amount.toLocaleString("nl-NL");
  }

  function scrollToStep(stepName) {
    const stepEl = getStepEl(stepName);
    if (!stepEl || stepEl.style.display === "none") return;

    requestAnimationFrame(() => {
      const y = stepEl.getBoundingClientRect().top + window.pageYOffset - 120;

      if (typeof lenis !== "undefined" && lenis) {
        lenis.scrollTo(y, { duration: 0.9 });
      } else {
        window.scrollTo({ top: y, behavior: "smooth" });
      }
    });
  }

  function getCompletedStepIndex() {
    if (!state.region) return 0;

    const flow = STEP_FLOW[state.region];
    if (!flow) return 0;

    let completed = 0;

    for (let i = 1; i < flow.length; i++) {
      const stepName = flow[i];

      if (stepName === "edition") {
        if (!state.edition) break;
        completed = i;
      } else if (stepName === "color") {
        if (!state.color) break;
        completed = i;
      } else if (stepName === "battery") {
        completed = i;
      } else if (stepName === "swap") {
        if (!state.swap) break;
        completed = i;
      } else if (stepName === "cta" || stepName === "waitlist") {
        completed = i;
      }
    }

    return completed;
  }

  function updateStepVisibility() {
    const flow = state.region ? STEP_FLOW[state.region] : null;
    const completedIdx = getCompletedStepIndex();
    const showUpTo = flow ? Math.min(completedIdx + 1, flow.length - 1) : 0;

    allSteps.forEach((step) => {
      const stepName = step.getAttribute("data-config-step");

      if (stepName === "region") {
        step.style.display = "";
        return;
      }

      if (!flow) {
        step.style.display = "none";
        return;
      }

      const indexInFlow = flow.indexOf(stepName);

      if (indexInFlow === -1) {
        step.style.display = "none";
        return;
      }

      const shouldShow = indexInFlow <= showUpTo;
      const wasHidden = step.style.display === "none";

      step.style.display = shouldShow ? "" : "none";

      if (shouldShow && wasHidden && !reducedMotion) {
        step.classList.add("is-entering");
        step.addEventListener(
          "animationend",
          () => {
            step.classList.remove("is-entering");
          }, { once: true }
        );
      }
    });
  }

  function markSoldOutEditions() {
    getOptionsForGroup("edition").forEach((opt) => {
      const value = opt.getAttribute("data-config-value");
      if (SOLD_OUT_EDITIONS.includes(value)) {
        opt.classList.add("is-disabled");
        opt.classList.remove("is-active");
      }
    });
  }

  function updateHighlights() {
    highlightLists.forEach((list) => {
      const listEdition = list.getAttribute("data-config-highlights-list");
      list.classList.toggle("is-visible", listEdition === state.edition);
    });
  }

  function updateStepValueLabel(group, label) {
    stepValueLabels.forEach((el) => {
      if (el.getAttribute("data-config-step-value") === group) {
        el.textContent = label;
      }
    });
  }

  function getConfigParts() {
    const parts = [REGION_LABELS[state.region] || ""];
    if (state.edition) parts.push(EDITION_LABELS[state.edition]);
    parts.push("EXR / Enduro");
    return parts;
  }

  function updateSummaryText() {
    const text = "Your configuration: " + getConfigParts().join(" · ");
    summaryTexts.forEach((el) => {
      el.textContent = text;
    });
  }

  function updatePricing() {
    const total = getTotalPrice();
    if (total === null) return;

    const formatted = formatPrice(total);

    if (priceEl) priceEl.textContent = formatted;
    if (priceElEu) priceElEu.textContent = formatted;
  }

  function hideInlineReserveButtons() {
    if (reserveBtn) reserveBtn.style.display = "none";
    if (reserveBtnEu) reserveBtnEu.style.display = "none";
  }

  function updateHiddenFields() {
    const LABELS = {
      region: {
        "eu-uk": "Europe (EEA + Switzerland + UK)",
        "row": "Rest of world"
      },
      color: {
        "stern-yellow": "Stern Yellow",
        "rock-grey": "Rock Grey"
      },
      swap: {
        "swap": "Swap Package",
        "no-swap": "No Swap Package"
      }
    };

    hiddenFields.forEach((input) => {
      const field = input.getAttribute("data-config-hidden");
      const raw = state[field];
      if (raw == null) return;
      const labelMap = LABELS[field];
      input.value = labelMap && labelMap[raw] ? labelMap[raw] : raw;
    });
  }

  function updateVariantSlide() {
    const variantSlide = root.querySelector("[data-variant-slide]");
    if (!variantSlide) return;

    const color = state.color || "stern-yellow";
    const swap = state.swap || "no-swap";

    const url = variantSlide.getAttribute(`data-img-${color}-${swap}`);
    if (!url) return;

    const img = variantSlide.querySelector("img");
    if (img && img.src !== url) {
      img.src = url;
      img.removeAttribute("srcset");
    }
  }

  function updateStickyBar() {
    if (!stickyBar) return;

    const shouldShow =
      state.region &&
      state.region !== "row" &&
      state.edition &&
      state.color &&
      state.swap;

    stickyBar.classList.toggle("is-visible", !!shouldShow);

    if (!shouldShow) return;

    if (stickyConfig) stickyConfig.textContent = getConfigParts().join(" · ");

    const deliveryMap = {
      "eu-uk": { standard: "From 2028" }
    };
    const delivery =
      deliveryMap[state.region]?.[state.edition || "standard"] || "From 2028";

    if (stickyDelivery) {
      stickyDelivery.textContent = "Estimated delivery: " + delivery;
    }

    const total = getTotalPrice();
    if (total !== null) {
      if (stickyPay) {
        stickyPay.textContent =
          "Pay today to reserve: €" + VOUCHER_AMOUNT + " (incl. VAT)";
      }
      if (stickyVoucher) {
        const remaining = total - VOUCHER_AMOUNT;
        stickyVoucher.textContent =
          "Total expected price minus voucher: € " +
          remaining.toLocaleString("nl-NL") +
          " (incl. VAT)";
      }
    }

    const url = getStripeUrl();
    if (stickyBtn) stickyBtn.setAttribute("href", url);
  }

  function updateAll() {
    updateStepVisibility();
    markSoldOutEditions();
    updateHighlights();
    updateSummaryText();
    updatePricing();
    updateHiddenFields();
    updateVariantSlide();
    updateStickyBar();
  }

  function selectRegion(value) {
    state.region = value;
    state.edition = null;
    state.color = null;
    state.swap = null;

    setActiveOption("region", value);

    ["edition", "color", "swap"].forEach((group) => {
      getOptionsForGroup(group).forEach((opt) =>
        opt.classList.remove("is-active")
      );
    });

    if (value === "eu-uk") {
      // Standard Edition is de enige beschikbare edition
      state.edition = "standard";
      setActiveOption("edition", "standard");
      updateStepValueLabel("edition", EDITION_LABELS.standard);
    } else if (value === "row") {
      state.edition = null;
    }

    updateAll();

    // Alleen bij de ALLEREERSTE region-keuze scrollen naar de volgende stap
    if (!hasScrolledAfterRegion) {
      hasScrolledAfterRegion = true;
      const flow = STEP_FLOW[value];
      const nextStepName = flow && flow[1];

      if (nextStepName) {
        if (regionScrollTimer) clearTimeout(regionScrollTimer);
        regionScrollTimer = setTimeout(() => {
          scrollToStep(nextStepName);
        }, 150);
      }
    }
  }

  function selectEdition(value) {
    if (SOLD_OUT_EDITIONS.includes(value)) return;

    state.edition = value;
    setActiveOption("edition", value);
    updateStepValueLabel("edition", EDITION_LABELS[value] || value);

    updateAll();
  }

  function selectColor(value) {
    const opt = allOptions.find(
      (o) =>
      o.getAttribute("data-config-option") === "color" &&
      o.getAttribute("data-config-value") === value
    );
    if (opt && opt.classList.contains("is-disabled")) return;

    state.color = value;
    setActiveOption("color", value);

    const label = value === "stern-yellow" ? "Stern Yellow" : "Rock Grey";
    updateStepValueLabel("color", label);

    updateAll();
    window.UNCOMMON.configMediaSlider?.goToFirst();
  }

  function selectSwap(value) {
    state.swap = value;
    setActiveOption("swap", value);
    updateAll();
    window.UNCOMMON.configMediaSlider?.goToFirst();
  }

  function handleClick(e) {
    const option = e.target.closest("[data-config-option]");
    if (!option) return;
    if (!root.contains(option)) return;
    if (option.classList.contains("is-disabled")) return;

    const link = e.target.closest("a.config-option__link");
    if (link) return;

    const group = option.getAttribute("data-config-option");
    const value = option.getAttribute("data-config-value");
    if (!group || !value) return;

    e.preventDefault();

    switch (group) {
    case "region":
      selectRegion(value);
      break;
    case "edition":
      selectEdition(value);
      break;
    case "color":
      selectColor(value);
      break;
    case "swap":
      selectSwap(value);
      break;
    case "battery":
      break;
    }
  }

  allSteps.forEach((step) => {
    const stepName = step.getAttribute("data-config-step");
    if (stepName !== "region") {
      step.style.display = "none";
    }
  });

  setActiveOption("battery", "endurance");
  markSoldOutEditions();
  hideInlineReserveButtons();

  if (stickyBar) stickyBar.classList.remove("is-visible");
  if (stickyBtn) stickyBtn.setAttribute("href", "#");

  root.addEventListener("click", handleClick);
  cleanups.push(() => root.removeEventListener("click", handleClick));
  cleanups.push(() => {
    if (regionScrollTimer) clearTimeout(regionScrollTimer);
  });

  updateAll();

  window.UNCOMMON.configuratorCleanup = function () {
    cleanups.forEach((fn) => fn());
    if (stickyBar) stickyBar.classList.remove("is-visible");
    window.UNCOMMON.configuratorCleanup = null;
  };
}

function initConfigMediaSlider(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.configMediaSliderCleanup) {
    window.UNCOMMON.configMediaSliderCleanup();
    window.UNCOMMON.configMediaSliderCleanup = null;
  }

  const page = getPageContainer(scope);
  const slider = page?.querySelector(".config-media__slider");
  if (!slider) return;

  const slides = Array.from(slider.querySelectorAll(".config-media__slide"));
  const prevBtn = page.querySelector(".config-media__arrow-prev");
  const nextBtn = page.querySelector(".config-media__arrow-next");
  if (slides.length < 2) return;

  // -----------------------------------------
  // LIGHTBOX DOM
  // -----------------------------------------

  const lb = document.querySelector("[data-config-lb]");
  const lbClose = document.querySelector("[data-config-lb-close]");
  const lbPrev = document.querySelector("[data-config-lb-prev]");
  const lbNext = document.querySelector("[data-config-lb-next]");
  const lbCounter = document.querySelector("[data-config-lb-counter]");

  let lbImg = null;
  if (lb) {
    lbImg = document.createElement("img");
    lbImg.className = "config-lb__img";
    lbImg.style.cssText = `
      position:absolute;
      inset:0;
      width:100%;
      height:100%;
      user-select:none;
      -webkit-user-drag:none;
      cursor:zoom-in;
      transform-origin:50% 50%;
      will-change:transform;
      touch-action:none;
    `;
    lbImg.setAttribute("draggable", "false");
    lbImg.setAttribute("alt", "Radian EXR");
    lb.insertBefore(lbImg, lb.querySelector(".config-lb__bar"));
  }

  const hasLightbox = !!(lb && lbImg);
  const isTouchDevice = () => window.matchMedia("(hover: none) and (pointer: coarse)").matches;

  const cleanups = [];
  let current = 0;
  let isAnimating = false;
  let lbOpen = false;
  let lbIndex = 0;

  const DURATION = 0.32;
  const EASE = "uncommon";
  const DRAG_THRESHOLD = 50;
  const CLICK_THRESHOLD = 8;

  // Desktop zoom
  const ZOOM_SCALE = 2.5;
  let lbZoomed = false;
  let lbZoomTy = 0;
  let lbZoomOriginY = 0;

  // Touch pan/zoom state
  const TOUCH_MIN_SCALE = 1;
  const TOUCH_MAX_SCALE = 4;
  let touchScale = 1;
  let touchTx = 0;
  let touchTy = 0;
  let pinchStartDist = 0;
  let pinchStartScale = 1;
  let panStartX = 0;
  let panStartY = 0;
  let panStartTx = 0;
  let panStartTy = 0;
  let isPinching = false;
  let isPanning = false;

  let pointerDownX = 0;
  let pointerDownY = 0;
  let dragStartX = 0;
  let isDragging = false;
  let hasDragNavigated = false;

  const scrollLock = window.UNCOMMON?.scrollLock;

  // -----------------------------------------
  // SLIDE INDICATOR
  // -----------------------------------------

  const indicatorCurrent = page.querySelector('[data-config-slide="current"]');
  const indicatorTotal = page.querySelector('[data-config-slide="total"]');

  function updateIndicator() {
    if (indicatorCurrent) indicatorCurrent.textContent = current + 1;
    if (indicatorTotal) indicatorTotal.textContent = slides.length;
  }

  // -----------------------------------------
  // IMAGE SRC HELPER
  // -----------------------------------------

  function getSlideImageSrc(slide) {
    const img = slide.querySelector("img");
    if (img?.src) return img.src;
    const style = window.getComputedStyle(slide).backgroundImage;
    const m = style.match(/url\(["']?(.+?)["']?\)/);
    return m ? m[1] : null;
  }

  // -----------------------------------------
  // INITIËLE STAAT SLIDER
  // -----------------------------------------

  slides.forEach((slide, i) => {
    gsap.set(slide, i === 0 ? { xPercent: 0, opacity: 1, visibility: "visible" } :
    { xPercent: 100, opacity: 0, visibility: "hidden" });
    slide.querySelectorAll("img").forEach(img => {
      img.setAttribute("draggable", "false");
      img.style.pointerEvents = "none";
      img.style.userSelect = "none";
    });
  });

  updateIndicator();

  slider.addEventListener("dragstart", e => e.preventDefault());
  cleanups.push(() => slider.removeEventListener("dragstart", e => e.preventDefault()));

  // -----------------------------------------
  // SLIDER NAVIGATIE
  // -----------------------------------------

  function goTo(index, direction) {
    if (isAnimating || index === current) return;
    index = (index + slides.length) % slides.length;
    isAnimating = true;

    const fromSlide = slides[current];
    const toSlide = slides[index];

    current = index;
    updateIndicator();

    gsap.set(toSlide, { xPercent: direction > 0 ? 100 : -100, opacity: 1, visibility: "visible" });

    const tl = gsap.timeline({
      defaults: { ease: EASE, duration: DURATION },
      onComplete: () => {
        gsap.set(fromSlide, { opacity: 0, visibility: "hidden", xPercent: 0 });
        isAnimating = false;
      }
    });

    tl.to(fromSlide, { xPercent: direction > 0 ? -100 : 100 }, 0);
    tl.to(toSlide, { xPercent: 0 }, 0);
  }

  function next() { goTo(current + 1, 1); }

  function prev() { goTo(current - 1, -1); }

  if (prevBtn) {
    prevBtn.addEventListener("click", prev);
    cleanups.push(() => prevBtn.removeEventListener("click", prev));
  }
  if (nextBtn) {
    nextBtn.addEventListener("click", next);
    cleanups.push(() => nextBtn.removeEventListener("click", next));
  }

  slider.setAttribute("tabindex", "0");

  function onSliderKeydown(e) {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      prev();
    }
    if (e.key === "ArrowRight") {
      e.preventDefault();
      next();
    }
  }
  slider.addEventListener("keydown", onSliderKeydown);
  cleanups.push(() => slider.removeEventListener("keydown", onSliderKeydown));

  // -----------------------------------------
  // DRAG (muis — slider)
  // -----------------------------------------

  function onPointerDown(e) {
    if (e.pointerType === "touch" || e.button !== 0) return;
    isDragging = true;
    hasDragNavigated = false;
    dragStartX = e.clientX;
    pointerDownX = e.clientX;
    pointerDownY = e.clientY;
    slider.classList.add("is-dragging");
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
  }

  function onPointerMove(e) {
    if (!isDragging) return;
    const dx = e.clientX - dragStartX;
    if (!hasDragNavigated && Math.abs(dx) > DRAG_THRESHOLD) {
      hasDragNavigated = true;
      if (dx < 0) next();
      else prev();
    }
  }

  function onPointerUp() {
    if (!isDragging) return;
    isDragging = false;
    slider.classList.remove("is-dragging");
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
  }

  slider.addEventListener("pointerdown", onPointerDown);
  cleanups.push(() => {
    slider.removeEventListener("pointerdown", onPointerDown);
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
    slider.classList.remove("is-dragging");
  });

  // -----------------------------------------
  // TOUCH / SWIPE (slider)
  // -----------------------------------------

  let touchStartX = 0,
    touchStartY = 0,
    hasSwiped = false;

  function onTouchStart(e) {
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    pointerDownX = e.touches[0].clientX;
    pointerDownY = e.touches[0].clientY;
    hasSwiped = false;
  }

  function onTouchMove(e) {
    if (hasSwiped) return;
    const dx = e.touches[0].clientX - touchStartX;
    const dy = e.touches[0].clientY - touchStartY;
    if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 30) {
      hasSwiped = true;
      if (dx < 0) next();
      else prev();
    }
  }

  slider.addEventListener("touchstart", onTouchStart, { passive: true });
  slider.addEventListener("touchmove", onTouchMove, { passive: true });
  cleanups.push(() => {
    slider.removeEventListener("touchstart", onTouchStart);
    slider.removeEventListener("touchmove", onTouchMove);
  });

  // -----------------------------------------
  // CLICK → LIGHTBOX OPENEN
  // -----------------------------------------

  function onSliderClick(e) {
    if (!hasLightbox) return;
    const dx = Math.abs(e.clientX - pointerDownX);
    const dy = Math.abs(e.clientY - pointerDownY);
    if (dx > CLICK_THRESHOLD || dy > CLICK_THRESHOLD) return;
    openLb(current);
  }

  slider.addEventListener("click", onSliderClick);
  cleanups.push(() => slider.removeEventListener("click", onSliderClick));

  // -----------------------------------------
  // LIGHTBOX — TELLER
  // -----------------------------------------

  function updateLbCounter() {
    if (!lbCounter) return;
    const pad = n => String(n).padStart(2, "0");
    lbCounter.textContent = `${pad(lbIndex + 1)} / ${pad(slides.length)}`;
  }

  // -----------------------------------------
  // LIGHTBOX — TOUCH PAN / PINCH ZOOM
  // -----------------------------------------

  function getTouchDist(touches) {
    const dx = touches[0].clientX - touches[1].clientX;
    const dy = touches[0].clientY - touches[1].clientY;
    return Math.sqrt(dx * dx + dy * dy);
  }

  function clampTouchTranslate(tx, ty, scale) {
    const W = window.innerWidth;
    const H = window.innerHeight;
    const overflowX = (W * scale - W) / 2;
    const overflowY = (H * scale - H) / 2;
    return {
      tx: Math.max(-overflowX, Math.min(overflowX, tx)),
      ty: Math.max(-overflowY, Math.min(overflowY, ty))
    };
  }

  function applyTouchTransform(immediate = false) {
    const { tx, ty } = clampTouchTranslate(touchTx, touchTy, touchScale);
    touchTx = tx;
    touchTy = ty;
    if (immediate) {
      gsap.set(lbImg, { scale: touchScale, x: tx, y: ty, transformOrigin: "50% 50%" });
    } else {
      gsap.to(lbImg, {
        scale: touchScale,
        x: tx,
        y: ty,
        duration: 0.08,
        ease: "none",
        overwrite: "auto"
      });
    }
  }

  function resetTouchTransform(animated = true) {
    touchScale = 1;
    touchTx = 0;
    touchTy = 0;
    if (animated) {
      gsap.to(lbImg, {
        scale: 1,
        x: 0,
        y: 0,
        duration: 0.3,
        ease: "power2.out",
        transformOrigin: "50% 50%"
      });
    } else {
      gsap.set(lbImg, { scale: 1, x: 0, y: 0, transformOrigin: "50% 50%" });
    }
    lbImg.style.cursor = "default";
  }

  function onLbTouchStart(e) {
    if (e.touches.length === 2) {
      isPinching = true;
      isPanning = false;
      pinchStartDist = getTouchDist(e.touches);
      pinchStartScale = touchScale;
    } else if (e.touches.length === 1) {
      isPinching = false;
      isPanning = true;
      panStartX = e.touches[0].clientX;
      panStartY = e.touches[0].clientY;
      panStartTx = touchTx;
      panStartTy = touchTy;
    }
  }

  function onLbTouchMove(e) {
    e.preventDefault();

    if (e.touches.length === 2 && isPinching) {
      const dist = getTouchDist(e.touches);
      const ratio = dist / pinchStartDist;
      touchScale = Math.max(TOUCH_MIN_SCALE, Math.min(TOUCH_MAX_SCALE, pinchStartScale * ratio));
      applyTouchTransform();

      lbImg.style.cursor = touchScale > 1 ? "grab" : "default";

    } else if (e.touches.length === 1 && isPanning && !isPinching) {
      if (touchScale <= 1) return;
      const dx = e.touches[0].clientX - panStartX;
      const dy = e.touches[0].clientY - panStartY;
      touchTx = panStartTx + dx;
      touchTy = panStartTy + dy;
      applyTouchTransform();
    }
  }

  function onLbTouchEnd(e) {
    if (e.touches.length < 2) {
      isPinching = false;
      if (touchScale < 1.1) {
        resetTouchTransform(true);
      }
    }
    if (e.touches.length === 0) {
      isPanning = false;
    }
  }

  // -----------------------------------------
  // LIGHTBOX — DESKTOP ZOOM IN/UIT
  // -----------------------------------------

  function openZoom(e) {
    const rect = lbImg.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;
    const xPct = (clickX / rect.width * 100).toFixed(2);
    const yPct = (clickY / rect.height * 100).toFixed(2);

    lbZoomOriginY = clickY;
    lbZoomTy = 0;
    lbZoomed = true;

    gsap.killTweensOf(lbImg);
    gsap.set(lbImg, { transformOrigin: `${xPct}% ${yPct}%` });
    gsap.to(lbImg, { scale: ZOOM_SCALE, y: 0, duration: 0.32, ease: "power2.out" });
    lbImg.style.cursor = "zoom-out";
  }

  function closeZoom(immediate = false) {
    if (!lbZoomed) return;
    lbZoomed = false;
    lbZoomTy = 0;
    gsap.killTweensOf(lbImg);
    if (immediate) {
      gsap.set(lbImg, { scale: 1, y: 0, transformOrigin: "50% 50%" });
    } else {
      gsap.to(lbImg, {
        scale: 1,
        y: 0,
        duration: 0.25,
        ease: "power2.in",
        onComplete: () => gsap.set(lbImg, { transformOrigin: "50% 50%" })
      });
    }
    lbImg.style.cursor = "zoom-in";
  }

  function onLbImgClick(e) {
    if (isTouchDevice()) return;
    e.stopPropagation();
    if (!lbZoomed) openZoom(e);
    else closeZoom();
  }

  // -----------------------------------------
  // LIGHTBOX — SCROLL (desktop pan)
  // -----------------------------------------

  function onLbWheel(e) {
    if (!lbZoomed || isTouchDevice()) return;
    e.preventDefault();

    const H = lbImg.getBoundingClientRect().height / ZOOM_SCALE;
    const maxDown = lbZoomOriginY * (ZOOM_SCALE - 1);
    const maxUp = -(H - lbZoomOriginY) * (ZOOM_SCALE - 1);

    lbZoomTy -= e.deltaY * 0.85;
    lbZoomTy = Math.max(maxUp, Math.min(maxDown, lbZoomTy));

    gsap.to(lbImg, { y: lbZoomTy, duration: 0.12, ease: "power2.out", overwrite: "auto" });
  }

  // -----------------------------------------
  // LIGHTBOX — NAVIGATIE
  // -----------------------------------------

  function lbGoTo(index) {
    const n = (index + slides.length) % slides.length;
    if (n === lbIndex) return;
    const dir = index >= lbIndex ? 1 : -1;
    lbIndex = n;

    if (isTouchDevice()) {
      resetTouchTransform(false);
    } else {
      closeZoom(true);
    }

    const src = getSlideImageSrc(slides[lbIndex]);
    if (src && lbImg) {
      gsap.fromTo(lbImg, { autoAlpha: 0, x: dir > 0 ? 24 : -24 }, {
        autoAlpha: 1,
        x: 0,
        duration: 0.28,
        ease: "power3.out"
      });
      lbImg.src = src;
    }

    updateLbCounter();
  }

  // -----------------------------------------
  // LIGHTBOX — OPENEN
  // -----------------------------------------

  function openLb(index) {
    if (!hasLightbox) return;

    lbIndex = index;

    if (isTouchDevice()) {
      resetTouchTransform(false);
    } else {
      closeZoom(true);
    }

    const src = getSlideImageSrc(slides[lbIndex]);
    if (src && lbImg) {
      lbImg.src = src;
      gsap.set(lbImg, { autoAlpha: 1, x: 0, scale: 1, y: 0, transformOrigin: "50% 50%" });
    }

    lbImg.style.cursor = isTouchDevice() ? "default" : "zoom-in";

    updateLbCounter();

    lbOpen = true;
    lb.style.display = "flex";
    gsap.fromTo(lb, { opacity: 0 }, { opacity: 1, duration: 0.28, ease: "power2.out" });
    scrollLock?.lock?.();
    document.addEventListener("keydown", onLbKey);
  }

  // -----------------------------------------
  // LIGHTBOX — SLUITEN
  // -----------------------------------------

  function closeLb() {
    if (!lbOpen || !hasLightbox) return;
    lbOpen = false;
    if (isTouchDevice()) {
      resetTouchTransform(false);
    } else {
      closeZoom(true);
    }
    gsap.to(lb, {
      opacity: 0,
      duration: 0.2,
      ease: "power2.in",
      onComplete: () => { lb.style.display = "none"; }
    });
    scrollLock?.unlock?.();
    document.removeEventListener("keydown", onLbKey);
  }

  // -----------------------------------------
  // LIGHTBOX — KEYBOARD
  // -----------------------------------------

  function onLbKey(e) {
    if (e.key === "Escape") {
      if (!isTouchDevice() && lbZoomed) closeZoom();
      else closeLb();
    }
    if (!lbZoomed) {
      if (e.key === "ArrowLeft") lbGoTo(lbIndex - 1);
      if (e.key === "ArrowRight") lbGoTo(lbIndex + 1);
    }
  }

  // -----------------------------------------
  // LIGHTBOX — EVENT LISTENERS
  // -----------------------------------------

  if (hasLightbox) {
    if (lbClose) {
      lbClose.addEventListener("click", closeLb);
      cleanups.push(() => lbClose.removeEventListener("click", closeLb));
    }

    if (lbPrev) {
      const onPrev = e => {
        e.stopPropagation();
        lbGoTo(lbIndex - 1);
      };
      lbPrev.addEventListener("click", onPrev);
      cleanups.push(() => lbPrev.removeEventListener("click", onPrev));
    }

    if (lbNext) {
      const onNext = e => {
        e.stopPropagation();
        lbGoTo(lbIndex + 1);
      };
      lbNext.addEventListener("click", onNext);
      cleanups.push(() => lbNext.removeEventListener("click", onNext));
    }

    lbImg.addEventListener("click", onLbImgClick);
    cleanups.push(() => lbImg.removeEventListener("click", onLbImgClick));

    lb.addEventListener("wheel", onLbWheel, { passive: false });
    cleanups.push(() => lb.removeEventListener("wheel", onLbWheel));

    lb.addEventListener("click", e => {
      if (e.target === lb) closeLb();
    });

    lb.addEventListener("touchstart", onLbTouchStart, { passive: false });
    lb.addEventListener("touchmove", onLbTouchMove, { passive: false });
    lb.addEventListener("touchend", onLbTouchEnd, { passive: true });

    cleanups.push(() => {
      document.removeEventListener("keydown", onLbKey);
      scrollLock?.unlock?.();
      lb.removeEventListener("touchstart", onLbTouchStart);
      lb.removeEventListener("touchmove", onLbTouchMove);
      lb.removeEventListener("touchend", onLbTouchEnd);
    });
  }

  // -----------------------------------------
  // PUBLIC API (voor configurator)
  // -----------------------------------------

  window.UNCOMMON.configMediaSlider = {
    goToFirst: () => goTo(0, -1)
  };

  // -----------------------------------------
  // CLEANUP
  // -----------------------------------------

  window.UNCOMMON.configMediaSliderCleanup = function () {
    cleanups.forEach(fn => fn());
    window.UNCOMMON.configMediaSlider = null;
    window.UNCOMMON.configMediaSliderCleanup = null;
  };
}

// -----------------------------------------
// THEME 
// -----------------------------------------

function getTopSectionThemeClass(scope = nextPage) {
  const page = getPageContainer(scope);
  if (!page) return getPageThemeClassFromScope(scope);

  // Eerste section met een theme class OF een data-theme-switch —
  // dit is wat bovenin staat na scrollTo(0,0)
  const firstSection = page.querySelector(
    'section[class*="theme-"], [data-theme-switch][class*="theme-"], [data-nav-hero][class*="theme-"]'
  );

  if (firstSection) {
    const t = Array.from(firstSection.classList).find(c => c.startsWith("theme-"));
    if (t) return t;
  }

  return getPageThemeClassFromScope(scope);
}

function applyThemeClassToTargets(themeClass) {
  if (!themeClass) return;

  const targets = Array.from(document.querySelectorAll("[data-theme-target]"));
  if (!targets.length) return;

  targets.forEach(target => {
    Array.from(target.classList)
      .filter(c => c.startsWith("theme-"))
      .forEach(c => target.classList.remove(c));

    target.classList.add(themeClass);
    target.setAttribute("data-theme-current", themeClass);
  });
}

function getPageThemeClassFromScope(scope) {
  const THEME_PREFIX = "theme-";
  const root = scope || nextPage || document;

  const containerTheme = Array.from(root.classList || []).find(c =>
    c.startsWith(THEME_PREFIX)
  );
  if (containerTheme) return containerTheme;

  const themedEl = root.querySelector?.("[data-page-theme]");
  if (themedEl) {
    const themeValue = themedEl.getAttribute("data-page-theme");
    if (themeValue) {
      return themeValue.startsWith(THEME_PREFIX) ?
        themeValue :
        `${THEME_PREFIX}${themeValue}`;
    }
  }

  const bodyTheme = Array.from(document.body.classList).find(c =>
    c.startsWith(THEME_PREFIX)
  );
  if (bodyTheme) return bodyTheme;

  return null;
}

function initThemeSwitch() {
  if (typeof ScrollTrigger === "undefined") return;
  if (typeof gsap !== "undefined" && gsap.registerPlugin) {
    gsap.registerPlugin(ScrollTrigger);
  }

  ScrollTrigger.getAll()
    .filter(t => t.vars && t.vars.__themeSwitch === true)
    .forEach(t => t.kill());

  const THEME_PREFIX = "theme-";

  const switches = Array.from(
    (nextPage || document).querySelectorAll(
      "[data-theme-switch], section.theme-dark, section.theme-light"
    )
  );
  const targets = Array.from(document.querySelectorAll("[data-theme-target]"));

  if (!targets.length) return;

  const COLOR_PROPS = [
    "color",
    "backgroundColor",
    "borderTopColor",
    "borderRightColor",
    "borderBottomColor",
    "borderLeftColor",
    "outlineColor",
    "fill",
    "stroke",
  ];

  const getThemeClass = (el) =>
    Array.from(el.classList).find(c => c.startsWith(THEME_PREFIX)) || null;

  const stripTheme = (el) => {
    Array.from(el.classList)
      .filter(c => c.startsWith(THEME_PREFIX))
      .forEach(c => el.classList.remove(c));
  };

  const snapshotColors = (el) => {
    const cs = getComputedStyle(el);
    const snap = {};
    COLOR_PROPS.forEach(p => {
      snap[p] = cs[p];
    });
    return snap;
  };

  const applyInlineColors = (el, snap) => {
    COLOR_PROPS.forEach(p => {
      el.style[p] = snap[p];
    });
  };

  const clearInlineColors = (el) => {
    COLOR_PROPS.forEach(p => {
      el.style[p] = "";
    });
  };

  const hasTween = (target) => target.hasAttribute("data-theme-tween");

  const tweenDur = (target) => {
    const raw = target.getAttribute("data-theme-tween-duration");
    const n = raw == null ? NaN : parseFloat(raw);
    return Number.isFinite(n) ? Math.max(0, n) : 0.35;
  };

  const tweenEase = (target) =>
    target.getAttribute("data-theme-tween-ease") || "power2.out";

  const getPageThemeClass = () => {
    const containerTheme = Array.from((nextPage || document).classList || []).find(c =>
      c.startsWith(THEME_PREFIX)
    );
    if (containerTheme) return containerTheme;

    const themedEl = (nextPage || document).querySelector("[data-page-theme]");
    if (themedEl) {
      const themeValue = themedEl.getAttribute("data-page-theme");
      if (themeValue) {
        return themeValue.startsWith(THEME_PREFIX) ?
          themeValue :
          `${THEME_PREFIX}${themeValue}`;
      }
    }

    const bodyTheme = Array.from(document.body.classList).find(c =>
      c.startsWith(THEME_PREFIX)
    );
    if (bodyTheme) return bodyTheme;

    return null;
  };

  const setThemeInstant = (target, themeClass) => {
    if (!themeClass) return;
    stripTheme(target);
    target.classList.add(themeClass);
    target.setAttribute("data-theme-current", themeClass);
  };

  const setThemeTweened = (target, themeClass) => {
    const rm = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;

    if (rm || typeof gsap === "undefined") {
      setThemeInstant(target, themeClass);
      return;
    }

    const els = [target, ...Array.from(target.querySelectorAll("*"))];

    const fromSnaps = new Map();
    els.forEach(el => fromSnaps.set(el, snapshotColors(el)));

    setThemeInstant(target, themeClass);

    const toSnaps = new Map();
    els.forEach(el => toSnaps.set(el, snapshotColors(el)));

    els.forEach(el => applyInlineColors(el, fromSnaps.get(el)));

    const vars = {
      duration: tweenDur(target),
      ease: tweenEase(target),
      overwrite: "auto",
      onComplete: () => els.forEach(clearInlineColors),
    };

    COLOR_PROPS.forEach(p => {
      vars[p] = (i, el) => toSnaps.get(el)[p];
    });

    gsap.to(els, vars);
  };

  const applyThemeToTarget = (target, themeClass, forceInstant = false) => {
    if (!themeClass) return;
    if (!forceInstant && target.getAttribute("data-theme-current") === themeClass) return;

    if (!forceInstant && hasTween(target)) {
      setThemeTweened(target, themeClass);
    } else {
      setThemeInstant(target, themeClass);
    }
  };

  const probeY = (target) => {
    const r = target.getBoundingClientRect();
    return r.top + r.height * 0.5;
  };

  const applyPageDefaultNow = () => {
    const pageTheme = getTopSectionThemeClass(nextPage); // was: getPageThemeClass()
    if (!pageTheme) return;

    targets.forEach(target => {
      applyThemeToTarget(target, pageTheme, true);
    });
  };
  const applyNow = () => {
    let foundActiveSwitch = false;

    targets.forEach(target => {
      const y = probeY(target);

      const active = switches.find(sw => {
        const r = sw.getBoundingClientRect();
        return r.top <= y && r.bottom >= y;
      });

      if (active) {
        foundActiveSwitch = true;
        applyThemeToTarget(target, getThemeClass(active));
      }
    });

    if (!foundActiveSwitch) {
      applyPageDefaultNow();
    }
  };

  applyPageDefaultNow();

  if (!switches.length) return;

  targets.forEach(target => {
    switches.forEach(sw => {
      const themeClass = getThemeClass(sw);
      if (!themeClass) return;

      ScrollTrigger.create({
        __themeSwitch: true,
        trigger: sw,
        start: () => `top ${probeY(target)}px`,
        end: () => `bottom ${probeY(target)}px`,
        onEnter: () => applyThemeToTarget(target, themeClass),
        onEnterBack: () => applyThemeToTarget(target, themeClass),
        onRefresh: (self) => {
          if (self.isActive) {
            applyThemeToTarget(target, themeClass);
          }
        }
      });
    });
  });

  applyNow();

  requestAnimationFrame(() => {
    ScrollTrigger.refresh(true);
    applyNow();
  });

  if (document.fonts?.ready?.then) {
    document.fonts.ready.then(() => {
      ScrollTrigger.refresh(true);
      applyNow();
    }).catch(() => {});
  }
}

function syncBodyThemeClass(data) {
  if (!data || !data.next || !data.next.html) return;

  const parser = new DOMParser();
  const nextDoc = parser.parseFromString(data.next.html, "text/html");
  const nextBody = nextDoc.body;

  if (!nextBody) return;

  const nextThemeClasses = Array.from(nextBody.classList).filter(c =>
    c.startsWith("theme-")
  );

  // oude theme classes verwijderen
  Array.from(document.body.classList)
    .filter(c => c.startsWith("theme-"))
    .forEach(c => document.body.classList.remove(c));

  // nieuwe theme classes toevoegen
  nextThemeClasses.forEach(c => document.body.classList.add(c));

  console.log("Synced body theme classes:", nextThemeClasses);
}

// -----------------------------------------
// NAV GLOBAL  
// -----------------------------------------

function syncNavStateInstant(scope = nextPage, prevNavMode = null) {
  const nav = document.querySelector(".nav[data-theme-target], .nav");
  if (!nav || typeof gsap === "undefined") return;

  const page = getPageContainer(scope);
  if (!page) return;

  // 1) THEME — direct op basis van de sectie die bovenin komt
  applyThemeClassToTargets(getTopSectionThemeClass(scope));

  // 2) IS-HERO class (behoudt bestaand gedrag voor .nav styling)
  const heroMarker = page.querySelector("[data-nav-hero]");
  nav.classList.toggle("is-hero", !!heroMarker);

  // 3) VISIBILITY — altijd expliciet, ongeacht waar je vandaan komt
  const navMode = page.getAttribute("data-nav-mode");
  const heroEl = page.querySelector("[data-hero]");

  const heroWillPlayIntro =
    heroEl &&
    window.innerWidth >= 992 &&
    !reducedMotion &&
    window.UNCOMMON?.homeHeroIntroPlayed !== true &&
    heroEl.getAttribute("data-hero-intro-state") !== "skipped";

  if (navMode === "pre-order") {
    // Verborgen op alle breakpoints
    gsap.set(nav, { yPercent: -100, autoAlpha: 0 });
  } else if (prevNavMode === "pre-order") {
    // Kom je van pre-order: start hidden, enter-animatie fadet in
    gsap.set(nav, { yPercent: -100, autoAlpha: 0 });
  } else if (heroWillPlayIntro) {
    // Hero intro speelt → nav komt later in beeld via initHero
    gsap.set(nav, { yPercent: 0, autoAlpha: 0 });
  } else {
    // Standaard zichtbaar
    gsap.set(nav, { yPercent: 0, autoAlpha: 1 });
  }
}

function initNavHeroState() {
  if (typeof ScrollTrigger === "undefined") return;
  if (typeof gsap !== "undefined" && gsap.registerPlugin) {
    gsap.registerPlugin(ScrollTrigger);
  }

  ScrollTrigger.getAll()
    .filter(t => t.vars && t.vars.__navHero === true)
    .forEach(t => t.kill());

  const nav = document.querySelector(".nav[data-theme-target], .nav");
  const hero = (nextPage || document).querySelector("[data-nav-hero]");

  if (!nav) return;

  // fallback: geen hero op de pagina = normale nav
  nav.classList.remove("is-hero");

  if (!hero) return;

  ScrollTrigger.create({
    __navHero: true,
    trigger: hero,
    start: "top top",
    end: "bottom top",
    onEnter: () => nav.classList.add("is-hero"),
    onEnterBack: () => nav.classList.add("is-hero"),
    onLeave: () => nav.classList.remove("is-hero"),
    onLeaveBack: () => nav.classList.remove("is-hero")
  });

  const rect = hero.getBoundingClientRect();
  const heroActive = rect.top <= 0 && rect.bottom > 0 || (rect.top >= 0 && rect.top < window
    .innerHeight);
  nav.classList.toggle("is-hero", heroActive);
}

function setNavBaseStateInstant(scope) {
  const root = scope || nextPage || document;
  const nav = document.querySelector(".nav[data-theme-target], .nav");
  if (!nav) return;

  const pageTheme = getPageThemeClassFromScope(root);
  applyThemeClassToTargets(pageTheme);

  const hero = root.querySelector("[data-nav-hero]");

  // Omdat jij bij enter altijd naar boven reset, is hero op load actief als hij bestaat
  nav.classList.toggle("is-hero", !!hero);
}

function initNavBackgroundReveal() {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.navBackgroundRevealCleanup) {
    window.UNCOMMON.navBackgroundRevealCleanup();
    window.UNCOMMON.navBackgroundRevealCleanup = null;
  }

  const nav = document.querySelector(".nav[data-theme-target], .nav");
  const navBg = nav?.querySelector(".nav__bg");

  if (!nav || !navBg || typeof gsap === "undefined") return;

  let isHoveringNav = false;
  let currentTween = null;
  let hoverEnabled = false;

  const OPEN_DURATION = 0.22;
  const CLOSE_DURATION = 0.18;
  const EASE = "uncommon";
  const DESKTOP_MQ = window.matchMedia("(min-width: 992px)");

  function killTween() {
    if (currentTween) {
      currentTween.kill();
      currentTween = null;
    }
  }

  function openBg() {
    killTween();

    currentTween = gsap.to(navBg, {
      scaleY: 1,
      duration: OPEN_DURATION,
      ease: EASE,
      overwrite: "auto",
      onComplete: () => {
        currentTween = null;
      }
    });
  }

  function closeBg() {
    killTween();

    currentTween = gsap.to(navBg, {
      scaleY: 0,
      duration: CLOSE_DURATION,
      ease: EASE,
      overwrite: "auto",
      onComplete: () => {
        currentTween = null;
      }
    });
  }

  function closeBgInstant() {
    killTween();
    gsap.set(navBg, { scaleY: 0 });
  }

  function getBoolAttr(name) {
    return nav.getAttribute(name) === "true";
  }

  function isLockedOpen() {
    return (
      getBoolAttr("data-nav-bg-lock-open") ||
      getBoolAttr("data-nav-bg-menu-open") ||
      getBoolAttr("data-nav-bg-product-open")
    );
  }

  function syncNavBackgroundReveal() {
    // Hover werkt alleen op desktop, lock-open werkt overal
    if (DESKTOP_MQ.matches) {
      if (isHoveringNav || isLockedOpen()) {
        openBg();
      } else {
        closeBg();
      }
    } else {
      // Tablet/mobile: alleen openen als expliciet gelockt (menu, product-nav)
      if (isLockedOpen()) {
        openBg();
      } else {
        closeBg();
      }
    }
  }

  function setNavBgLockOpen(locked) {
    nav.setAttribute("data-nav-bg-lock-open", locked ? "true" : "false");

    syncNavBackgroundReveal();
  }

  function handlePointerEnter() {
    if (!DESKTOP_MQ.matches) return;
    isHoveringNav = true;
    openBg();
  }

  function handlePointerLeave() {
    if (!DESKTOP_MQ.matches) return;

    isHoveringNav = false;

    if (isLockedOpen()) {
      openBg();
      return;
    }

    closeBg();
  }

  function bindHover() {
    if (hoverEnabled) return;
    hoverEnabled = true;
    nav.addEventListener("pointerenter", handlePointerEnter);
    nav.addEventListener("pointerleave", handlePointerLeave);
  }

  function unbindHover() {
    if (!hoverEnabled) return;
    hoverEnabled = false;
    nav.removeEventListener("pointerenter", handlePointerEnter);
    nav.removeEventListener("pointerleave", handlePointerLeave);
  }

  function applyBreakpointState() {
    isHoveringNav = false;

    if (DESKTOP_MQ.matches) {
      bindHover();
    } else {
      unbindHover();
    }

    // Altijd syncen — ook op tablet/mobile voor lock-open states
    syncNavBackgroundReveal();
  }
  gsap.set(navBg, {
    scaleY: 0,
    transformOrigin: "50% 100%"
  });

  if (DESKTOP_MQ.addEventListener) {
    DESKTOP_MQ.addEventListener("change", applyBreakpointState);
  } else if (DESKTOP_MQ.addListener) {
    DESKTOP_MQ.addListener(applyBreakpointState);
  }

  window.UNCOMMON.syncNavBackgroundReveal = syncNavBackgroundReveal;
  window.UNCOMMON.setNavBgLockOpen = setNavBgLockOpen;
  window.UNCOMMON.isNavBgHovered = () => isHoveringNav;

  window.UNCOMMON.navBackgroundRevealCleanup = function () {
    unbindHover();
    killTween();

    if (DESKTOP_MQ.removeEventListener) {
      DESKTOP_MQ.removeEventListener("change", applyBreakpointState);
    } else if (DESKTOP_MQ.removeListener) {
      DESKTOP_MQ.removeListener(applyBreakpointState);
    }

    window.UNCOMMON.syncNavBackgroundReveal = null;
    window.UNCOMMON.setNavBgLockOpen = null;
    window.UNCOMMON.isNavBgHovered = null;
    window.UNCOMMON.navBackgroundRevealCleanup = null;
  };

  applyBreakpointState();
}

// -----------------------------------------
// NAV MENU  (TABLET / MOBILE)
// -----------------------------------------

function initMenu() {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.menuCleanup) {
    window.UNCOMMON.menuCleanup();
    window.UNCOMMON.menuCleanup = null;
  }

  const wrap =
    document.querySelector('[data-menu="wrap"]') ||
    document.querySelector("[data-menu-open]");

  const panel = document.querySelector('[data-menu="panel"]');
  const toggles = Array.from(document.querySelectorAll('[data-menu="toggle"]'));
  const closes = Array.from(document.querySelectorAll('[data-menu="close"]'));
  const items = Array.from(panel?.querySelectorAll('[data-menu="item"]') || []);

  if (!panel || !toggles.length) return;

  const scrollLock = window.UNCOMMON.scrollLock || null;

  let isOpen = wrap?.getAttribute("data-menu-open") === "true";
  let navBgTimer = null;
  let menuVideoPauseTimer = null;

  function getNav() {
    return document.querySelector(".nav[data-theme-target], .nav");
  }

  function clearNavBgTimer() {
    if (!navBgTimer) return;
    clearTimeout(navBgTimer);
    navBgTimer = null;
  }

  function clearMenuVideoPauseTimer() {
    if (!menuVideoPauseTimer) return;
    clearTimeout(menuVideoPauseTimer);
    menuVideoPauseTimer = null;
  }

  function getMenuVideo() {
    return panel.querySelector(".nav__video video.nav-video__menu");
  }

  function prepareMenuVideo() {
    const video = getMenuVideo();
    if (!video) return null;

    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;
    video.loop = true;
    video.preload = "auto";

    video.setAttribute("muted", "");
    video.setAttribute("playsinline", "");
    video.setAttribute("webkit-playsinline", "");
    video.setAttribute("preload", "auto");
    video.setAttribute("loop", "");

    if (typeof video.disableRemotePlayback !== "undefined") {
      video.disableRemotePlayback = true;
    }

    if (!video.getAttribute("src") && video.dataset.src) {
      video.setAttribute("src", video.dataset.src);
    }

    try {
      video.load();
    } catch (_) {}

    return video;
  }

  function playMenuVideo() {
    clearMenuVideoPauseTimer();

    const video = prepareMenuVideo();
    if (!video) return;

    const playPromise = video.play();

    if (playPromise && typeof playPromise.then === "function") {
      playPromise.catch(() => {
        requestAnimationFrame(() => {
          const retryPromise = video.play();

          if (retryPromise && typeof retryPromise.then === "function") {
            retryPromise.catch(() => {});
          }
        });
      });
    }
  }

  function pauseMenuVideo() {
    clearMenuVideoPauseTimer();

    menuVideoPauseTimer = setTimeout(() => {
      const video = getMenuVideo();
      if (!video) return;

      try {
        if (!video.paused && !video.ended) {
          video.pause();
        }
      } catch (_) {}

      menuVideoPauseTimer = null;
    }, 250);
  }

  function setMenuState(open) {
    isOpen = open;

    if (wrap) wrap.setAttribute("data-menu-open", open ? "true" : "false");

    panel.classList.toggle("is-active", open);

    const nav = getNav();
    nav?.classList.toggle("is-menu-open", open);
    nav?.setAttribute("data-nav-bg-menu-open", open ? "true" : "false");

    window.UNCOMMON?.syncNavBackgroundReveal?.();
  }

  function setInitialState() {
    prepareMenuVideo();
    setMenuState(isOpen);

    if (items.length) {
      gsap.set(items, {
        autoAlpha: isOpen ? 1 : 0,
        y: isOpen ? "0em" : "0.75em"
      });
    }

    if (isOpen) {
      scrollLock?.lock();
      playMenuVideo();
    } else {
      scrollLock?.unlock();
    }
  }

  function openMenu() {
    if (isOpen) return;

    clearNavBgTimer();
    clearMenuVideoPauseTimer();

    const nav = getNav();
    nav?.setAttribute("data-nav-bg-menu-open", "true");

    setMenuState(true);
    window.UNCOMMON?.syncNavBackgroundReveal?.();

    scrollLock?.lock();

    playMenuVideo();

    requestAnimationFrame(() => {
      playMenuVideo();
    });

    gsap.killTweensOf(items);

    if (items.length) {
      gsap.fromTo(
        items,
        {
          autoAlpha: 0,
          y: "0.75em"
        },
        {
          autoAlpha: 1,
          y: "0em",
          duration: 0.45,
          ease: "power2.out",
          stagger: 0.04,
          delay: 0.12
        }
      );
    }
  }

  function closeMenu() {
    if (!isOpen) return;

    clearNavBgTimer();

    const nav = getNav();

    setMenuState(false);
    pauseMenuVideo();

    gsap.killTweensOf(items);

    if (items.length) {
      gsap.to(items, {
        autoAlpha: 0,
        y: "0.5em",
        duration: 0.22,
        ease: "power2.in",
        stagger: {
          each: 0.025,
          from: "end"
        }
      });
    }

    scrollLock?.unlock();

    navBgTimer = setTimeout(() => {
      nav?.setAttribute("data-nav-bg-menu-open", "false");
      window.UNCOMMON?.syncNavBackgroundReveal?.();
      navBgTimer = null;
    }, 700);
  }

  function toggleMenu(e) {
    e?.preventDefault();

    if (isOpen) closeMenu();
    else openMenu();
  }

  function handleCloseClick(e) {
    e?.preventDefault();
    closeMenu();
  }

  function handleKeydown(e) {
    if (e.key === "Escape") closeMenu();
  }

  function handlePanelClick(e) {
    if (!isOpen) return;

    const closeButton = e.target.closest('[data-menu="close"]');
    if (closeButton) return;

    const video = e.target.closest(".nav__video video.nav-video__menu");
    if (video) return;

    const clickedMenuButton = e.target.closest(
      '[data-menu="item"], a, button, [role="button"], .btn-icon-link, [data-anchor-link]'
    );

    if (!clickedMenuButton) return;
    if (!panel.contains(clickedMenuButton)) return;

    closeMenu();
  }

  toggles.forEach(toggle => {
    toggle.addEventListener("click", toggleMenu);
  });

  closes.forEach(close => {
    close.addEventListener("click", handleCloseClick);
  });

  panel.addEventListener("click", handlePanelClick);
  document.addEventListener("keydown", handleKeydown);

  setInitialState();

  window.UNCOMMON.menuCleanup = function () {
    clearNavBgTimer();
    clearMenuVideoPauseTimer();

    const video = getMenuVideo();

    if (video) {
      try {
        video.pause();
      } catch (_) {}
    }

    toggles.forEach(toggle => {
      toggle.removeEventListener("click", toggleMenu);
    });

    closes.forEach(close => {
      close.removeEventListener("click", handleCloseClick);
    });

    panel.removeEventListener("click", handlePanelClick);
    document.removeEventListener("keydown", handleKeydown);

    window.UNCOMMON.menuCleanup = null;
  };
}

// -----------------------------------------
// PRODUCT NAV 
// -----------------------------------------

function initProductNav(scope = nextPage) {
  initProductNavMode(scope);
  initProductNavDropdown();
  initProductNavHorizontalScroll();
  initProductNavIndicator(scope);

  if (hasInPage('[data-anchor-section]', scope)) {
    initProductNavAnchors(scope);
  }
}

function initProductNavAnchors(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.productNavAnchorsCleanup) {
    window.UNCOMMON.productNavAnchorsCleanup();
    window.UNCOMMON.productNavAnchorsCleanup = null;
  }

  const page = getPageContainer(scope);

  const navLinks = Array.from(
    document.querySelectorAll(
      "[data-product-nav-scroll] [data-anchor-link], [data-product-nav-list] [data-anchor-link]"
    )
  );

  const sections = Array.from(page?.querySelectorAll("[data-anchor-section]") || []);

  if (!navLinks.length || !sections.length) return;
  if (typeof ScrollTrigger === "undefined") return;

  gsap.registerPlugin(ScrollTrigger);

  let isProgrammaticScroll = false;
  let activeAnchor = null;
  let fallbackTimer = null;
  const triggers = [];

  function setActiveLink(anchorName) {
    if (!anchorName) return;
    activeAnchor = anchorName;

    navLinks.forEach((link) => {
      const isMatch = link.getAttribute("data-anchor-link") === anchorName;
      link.classList.toggle("is-active", isMatch);
    });

    const listIsOpen = document
      .querySelector("[data-product-nav-list]")
      ?.classList.contains("is-active");

    scrollActiveProductNavItemIntoView(listIsOpen ? "smooth" : "auto");
  }

  function getSectionByName(name) {
    return sections.find(
      (section) => section.getAttribute("data-anchor-section") === name
    );
  }

  function getClosestSection() {
    const probeY = window.innerHeight * 0.55;
    let closest = null;
    let closestDistance = Infinity;

    sections.forEach((section) => {
      const rect = section.getBoundingClientRect();
      const sectionCenter = rect.top + rect.height * 0.5;
      const distance = Math.abs(sectionCenter - probeY);

      if (distance < closestDistance) {
        closestDistance = distance;
        closest = section;
      }
    });

    return closest;
  }

  function updateActiveFromScroll() {
    if (isProgrammaticScroll) return;

    const closestSection = getClosestSection();
    if (!closestSection) return;

    const anchorName = closestSection.getAttribute("data-anchor-section");
    if (!anchorName || anchorName === activeAnchor) return;

    setActiveLink(anchorName);
  }

  function scrollToSection(section, anchorName) {
    if (!section || !anchorName) return;

    isProgrammaticScroll = true;
    setActiveLink(anchorName);
    clearTimeout(fallbackTimer);

    const targetY = section.getBoundingClientRect().top + window.pageYOffset;

    if (typeof lenis !== "undefined" && lenis) {
      lenis.scrollTo(targetY, {
        duration: 1.1,
        lock: true,
        onComplete: () => {
          isProgrammaticScroll = false;
          setActiveLink(anchorName);
          ScrollTrigger.refresh();
        }
      });

      fallbackTimer = setTimeout(() => {
        isProgrammaticScroll = false;
        setActiveLink(anchorName);
      }, 1400);
    } else {
      window.scrollTo({
        top: targetY,
        behavior: "smooth"
      });

      fallbackTimer = setTimeout(() => {
        isProgrammaticScroll = false;
        setActiveLink(anchorName);
      }, 1200);
    }
  }

  function handleClick(e) {
    const link = e.target.closest("[data-anchor-link]");
    if (!link) return;
    if (!navLinks.includes(link)) return;

    const anchorName = link.getAttribute("data-anchor-link");
    const targetSection = getSectionByName(anchorName);

    if (!anchorName || !targetSection) return;

    e.preventDefault();
    scrollToSection(targetSection, anchorName);
  }

  document.addEventListener("click", handleClick);

  sections.forEach((section) => {
    const anchorName = section.getAttribute("data-anchor-section");
    if (!anchorName) return;

    const trigger = ScrollTrigger.create({
      trigger: section,
      start: "top 55%",
      end: "bottom 55%",
      onEnter: () => {
        if (!isProgrammaticScroll) setActiveLink(anchorName);
      },
      onEnterBack: () => {
        if (!isProgrammaticScroll) setActiveLink(anchorName);
      }
    });

    triggers.push(trigger);
  });

  updateActiveFromScroll();

  window.UNCOMMON.productNavAnchorsCleanup = function () {
    clearTimeout(fallbackTimer);
    document.removeEventListener("click", handleClick);
    triggers.forEach((trigger) => trigger.kill());
  };
}

function initProductNavDropdown() {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.productNavDropdownCleanup) {
    window.UNCOMMON.productNavDropdownCleanup();
    window.UNCOMMON.productNavDropdownCleanup = null;
  }

  const trigger = document.querySelector("[data-product-nav-trigger]");
  const list = document.querySelector("[data-product-nav-list]");
  const wrapper = document.querySelector(".product-nav_wrapper");
  const productNav = document.querySelector(".product-nav");
  const navBar = document.querySelector(".nav__bar");
  const navBg = navBar?.querySelector(".nav__bg");
  const overlay = document.querySelector(".product-nav_overlay");
  const navRoot = trigger?.closest(".nav");

  if (!trigger || !list || !wrapper || !productNav || !navBar || !navBg) return;
  if (typeof gsap === "undefined") return;

  let isOpen = false;
  let scrollCloseTicking = false;
  let currentTween = null;

  const OPEN_DURATION = 0.18;
  const CLOSE_DURATION = 0.16;
  const EASE = "uncommon";
  const CLOSED_RADIUS = "0.25em";
  const OPEN_RADIUS = "0em";

  function killTween() {
    if (currentTween) {
      currentTween.kill();
      currentTween = null;
    }
  }

  function setClosedStateInstant() {
    killTween();

    isOpen = false;

    trigger.classList.remove("is-active");
    list.classList.remove("is-active");
    overlay?.classList.remove("is-active");
    navRoot?.classList.remove("is-product-nav-open");
    navRoot?.setAttribute("data-nav-bg-product-open", "false");

    window.UNCOMMON?.setNavBgLockOpen?.(false);

    gsap.set(wrapper, {
      height: 0,
      overflow: "hidden"
    });

    gsap.set(productNav, {
      yPercent: -100,
      borderTopLeftRadius: CLOSED_RADIUS,
      borderTopRightRadius: CLOSED_RADIUS,
      borderBottomLeftRadius: CLOSED_RADIUS,
      borderBottomRightRadius: CLOSED_RADIUS
    });

    gsap.set([navBg, navBar], {
      borderTopLeftRadius: CLOSED_RADIUS,
      borderTopRightRadius: CLOSED_RADIUS,
      borderBottomLeftRadius: CLOSED_RADIUS,
      borderBottomRightRadius: CLOSED_RADIUS
    });

    window.UNCOMMON?.syncNavBackgroundReveal?.();
  }

  function openDropdown() {
    if (isOpen) return;
    isOpen = true;

    killTween();

    trigger.classList.add("is-active");
    list.classList.add("is-active");
    overlay?.classList.add("is-active");
    navRoot?.classList.add("is-product-nav-open");
    navRoot?.setAttribute("data-nav-bg-product-open", "true");

    // lock bg open regardless of pointerleave
    window.UNCOMMON?.setNavBgLockOpen?.(true);

    currentTween = gsap.timeline({
      defaults: { ease: EASE },
      onComplete: () => {
        currentTween = null;
        gsap.set(wrapper, { height: "auto" });
        scrollActiveProductNavItemIntoView("smooth");
      }
    });

    currentTween.set(wrapper, {
      overflow: "hidden"
    });

    currentTween.set(productNav, {
      yPercent: -100
    }, 0);

    currentTween.to(wrapper, {
      height: "auto",
      duration: OPEN_DURATION
    }, 0);

    currentTween.to(productNav, {
      yPercent: 0,
      duration: OPEN_DURATION
    }, 0);

    currentTween.to([navBg, navBar], {
      borderBottomLeftRadius: OPEN_RADIUS,
      borderBottomRightRadius: OPEN_RADIUS,
      duration: OPEN_DURATION
    }, 0);

    currentTween.to(productNav, {
      borderTopLeftRadius: OPEN_RADIUS,
      borderTopRightRadius: OPEN_RADIUS,
      borderBottomLeftRadius: CLOSED_RADIUS,
      borderBottomRightRadius: CLOSED_RADIUS,
      duration: OPEN_DURATION
    }, 0);
  }

  function closeDropdown() {
    if (!isOpen) return;
    isOpen = false;

    killTween();

    trigger.classList.remove("is-active");
    overlay?.classList.remove("is-active");
    navRoot?.classList.remove("is-product-nav-open");
    navRoot?.setAttribute("data-nav-bg-product-open", "false");

    // unlock bg again
    window.UNCOMMON?.setNavBgLockOpen?.(false);

    currentTween = gsap.timeline({
      defaults: { ease: EASE },
      onComplete: () => {
        list.classList.remove("is-active");

        gsap.set(wrapper, {
          height: 0
        });

        gsap.set(productNav, {
          yPercent: -100,
          borderTopLeftRadius: CLOSED_RADIUS,
          borderTopRightRadius: CLOSED_RADIUS,
          borderBottomLeftRadius: CLOSED_RADIUS,
          borderBottomRightRadius: CLOSED_RADIUS
        });

        gsap.set([navBg, navBar], {
          borderTopLeftRadius: CLOSED_RADIUS,
          borderTopRightRadius: CLOSED_RADIUS,
          borderBottomLeftRadius: CLOSED_RADIUS,
          borderBottomRightRadius: CLOSED_RADIUS
        });

        currentTween = null;

        // after closing:
        // if still hovered -> keep open
        // if not hovered -> collapse
        window.UNCOMMON?.syncNavBackgroundReveal?.();
      }
    });

    currentTween.to(productNav, {
      yPercent: -100,
      duration: CLOSE_DURATION
    }, 0);

    currentTween.to(wrapper, {
      height: 0,
      duration: CLOSE_DURATION
    }, 0);

    currentTween.to([navBg, navBar], {
      borderBottomLeftRadius: CLOSED_RADIUS,
      borderBottomRightRadius: CLOSED_RADIUS,
      duration: CLOSE_DURATION
    }, 0);

    currentTween.to(productNav, {
      borderTopLeftRadius: CLOSED_RADIUS,
      borderTopRightRadius: CLOSED_RADIUS,
      borderBottomLeftRadius: CLOSED_RADIUS,
      borderBottomRightRadius: CLOSED_RADIUS,
      duration: CLOSE_DURATION
    }, 0);
  }

  function toggleDropdown() {
    if (isOpen) closeDropdown();
    else openDropdown();
  }

  function handleTriggerClick(e) {
    e.preventDefault();
    e.stopPropagation();
    toggleDropdown();
  }

  function handleDocumentClick(e) {
    if (!isOpen) return;

    const clickedInsideTrigger = trigger.contains(e.target);
    const clickedInsideList = list.contains(e.target);

    if (!clickedInsideTrigger && !clickedInsideList) {
      closeDropdown();
    }
  }

  function handleScrollClose() {
    if (!isOpen) return;
    if (scrollCloseTicking) return;

    scrollCloseTicking = true;

    requestAnimationFrame(() => {
      closeDropdown();
      scrollCloseTicking = false;
    });
  }

  function handleAnchorClick(e) {
    const anchorLink = e.target.closest("[data-anchor-link]");
    if (!anchorLink) return;
    if (!list.contains(anchorLink)) return;

    closeDropdown();
  }

  function handleResize() {
    if (!isOpen) return;
    gsap.set(wrapper, { height: "auto" });
  }

  trigger.addEventListener("click", handleTriggerClick);
  document.addEventListener("click", handleDocumentClick);
  document.addEventListener("click", handleAnchorClick, true);
  window.addEventListener("scroll", handleScrollClose, { passive: true });
  window.addEventListener("resize", handleResize);

  if (typeof lenis !== "undefined" && lenis && typeof lenis.on === "function") {
    lenis.on("scroll", handleScrollClose);
  }

  setClosedStateInstant();

  window.UNCOMMON.productNavDropdownCleanup = function () {
    trigger.removeEventListener("click", handleTriggerClick);
    document.removeEventListener("click", handleDocumentClick);
    document.removeEventListener("click", handleAnchorClick, true);
    window.removeEventListener("scroll", handleScrollClose);
    window.removeEventListener("resize", handleResize);

    if (typeof lenis !== "undefined" && lenis && typeof lenis.off === "function") {
      lenis.off("scroll", handleScrollClose);
    }

    killTween();
    setClosedStateInstant();
    window.UNCOMMON.productNavDropdownCleanup = null;
  };
}

function getNaturalWidth(el) {
  if (!el) return 0;

  const prevWidth = el.style.width;
  const prevMinWidth = el.style.minWidth;

  el.style.width = "auto";
  el.style.minWidth = "0px";

  const width = el.scrollWidth || el.getBoundingClientRect().width || 0;

  el.style.width = prevWidth;
  el.style.minWidth = prevMinWidth;

  return width;
}

function animateProductNavMode(isProductPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.productNavModeTimeline) {
    window.UNCOMMON.productNavModeTimeline.kill();
    window.UNCOMMON.productNavModeTimeline = null;
  }

  const productNavWrap = document.querySelector(".product-nav_dropdown-wrap");
  const productNav = document.querySelector(".product-nav_dropdown");
  const productSource = document.querySelector("[data-product-nav-source]");

  if (!productNavWrap || !productNav) return;

  gsap.killTweensOf(productNavWrap);
  gsap.killTweensOf(productNav);
  if (productSource) gsap.killTweensOf(productSource);

  const dropdownWidth = productNav.scrollWidth;
  const sourceWidth = productSource ? getNaturalWidth(productSource) : 0;

  const tl = gsap.timeline({
    defaults: {
      duration: 0.7,
      ease: "uncommon"
    }
  });

  if (isProductPage) {
    if (productSource) {
      tl.to(productSource, {
        width: 0,
        opacity: 0,
        x: "-0.75em",
        marginRight: 0,
        pointerEvents: "none"
      }, 0);
    }

    tl.set(productNav, {
      pointerEvents: "auto"
    }, 0.42);

    tl.to(productNavWrap, {
      width: dropdownWidth
    }, 0.42);

    tl.to(productNav, {
      autoAlpha: 1,
      x: "0em",
      scale: 1
    }, 0.48);
  } else {
    tl.to(productNav, {
      autoAlpha: 0,
      x: "-1em",
      scale: 0.96
    }, 0);

    tl.to(productNavWrap, {
      width: 0
    }, 0.08);

    tl.set(productNav, {
      pointerEvents: "none"
    }, 0.42);

    if (productSource) {
      tl.set(productSource, {
        pointerEvents: "auto",
        clearProps: "marginRight"
      }, 0.42);

      tl.to(productSource, {
        width: sourceWidth,
        opacity: 1,
        x: "0em"
      }, 0.42);
    }
  }

  window.UNCOMMON.productNavModeTimeline = tl;
  return tl;
}

function initProductNavMode(scope = nextPage) {
  const pageContainer = getPageContainer(scope);
  if (!pageContainer) return;

  const navMode = pageContainer.getAttribute("data-nav-mode");
  const isProductPage = navMode === "product";

  animateProductNavMode(isProductPage);
}

function setProductNavModeInitialState(scope = document) {
  const productNavWrap = document.querySelector(".product-nav_dropdown-wrap");
  const productNav = document.querySelector(".product-nav_dropdown");
  const productSource = document.querySelector("[data-product-nav-source]");
  const pageContainer = getPageContainer(scope);

  if (!productNavWrap || !productNav || !pageContainer) return;

  const navMode = pageContainer.getAttribute("data-nav-mode");
  const isProductPage = navMode === "product";

  const dropdownWidth = productNav.scrollWidth;
  const sourceWidth = productSource ? getNaturalWidth(productSource) : 0;

  if (isProductPage) {
    gsap.set(productNavWrap, {
      width: dropdownWidth
    });

    gsap.set(productNav, {
      autoAlpha: 1,
      x: 0,
      scale: 1,
      pointerEvents: "auto"
    });

    if (productSource) {
      gsap.set(productSource, {
        width: 0,
        opacity: 0,
        x: "-0.75em",
        marginRight: 0,
        pointerEvents: "none"
      });
    }
  } else {
    gsap.set(productNavWrap, {
      width: 0
    });

    gsap.set(productNav, {
      autoAlpha: 0,
      x: "-1em",
      scale: 0.96,
      pointerEvents: "none"
    });

    if (productSource) {
      gsap.set(productSource, {
        width: sourceWidth,
        opacity: 1,
        x: 0,
        pointerEvents: "auto",
        clearProps: "marginRight"
      });
    }
  }
}

function initProductNavIndicator(scope = nextPage) {
  if (typeof ScrollTrigger === "undefined") return;
  if (typeof gsap !== "undefined" && gsap.registerPlugin) {
    gsap.registerPlugin(ScrollTrigger);
  }

  ScrollTrigger.getAll()
    .filter(t => t.vars && t.vars.__productNavIndicator === true)
    .forEach(t => t.kill());

  const pageContainer = getPageContainer(scope);
  const fill = document.querySelector(".product-nav_indicator-fill");

  if (!pageContainer || !fill) return;

  const navMode = pageContainer.getAttribute("data-nav-mode");
  const isProductPage = navMode === "product";

  if (!isProductPage) {
    gsap.set(fill, { scaleX: 0 });
    return;
  }

  gsap.set(fill, { scaleX: 0 });

  ScrollTrigger.create({
    __productNavIndicator: true,
    trigger: pageContainer,
    start: "top top",
    end: "bottom bottom",
    scrub: true,
    onUpdate: (self) => {
      gsap.set(fill, {
        scaleX: self.progress
      });
    }
  });
}

function scrollProductNavItemIntoView(item, behavior = "auto") {
  const scroller = document.querySelector("[data-product-nav-scroll]");
  if (!scroller || !item) return;

  const scrollerRect = scroller.getBoundingClientRect();
  const itemRect = item.getBoundingClientRect();

  const currentScroll = scroller.scrollLeft;
  const itemLeft = itemRect.left - scrollerRect.left + currentScroll;
  const targetLeft = itemLeft - (scroller.clientWidth - itemRect.width) / 2;
  const maxScroll = scroller.scrollWidth - scroller.clientWidth;

  scroller.scrollTo({
    left: Math.max(0, Math.min(targetLeft, maxScroll)),
    behavior
  });
}

function scrollActiveProductNavItemIntoView(behavior = "auto") {
  const activeLink =
    document.querySelector("[data-product-nav-scroll] .product-nav_li-link.is-active") ||
    document.querySelector("[data-product-nav-scroll] [data-anchor-link].is-active");

  if (!activeLink) return;

  const activeItem = activeLink.closest(".product-nav_li") || activeLink;
  scrollProductNavItemIntoView(activeItem, behavior);
}

function initProductNavHorizontalScroll() {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.productNavHorizontalScrollCleanup) {
    window.UNCOMMON.productNavHorizontalScrollCleanup();
    window.UNCOMMON.productNavHorizontalScrollCleanup = null;
  }

  const scroller = document.querySelector("[data-product-nav-scroll]");
  if (!scroller) return;

  let isPointerDown = false;
  let startX = 0;
  let startScrollLeft = 0;
  let hasDragged = false;

  function onPointerDown(e) {
    if (e.pointerType !== "mouse") return;
    if (e.button !== 0) return;

    isPointerDown = true;
    hasDragged = false;
    startX = e.clientX;
    startScrollLeft = scroller.scrollLeft;

    scroller.classList.add("is-dragging");
    scroller.style.scrollBehavior = "auto";
  }

  function onPointerMove(e) {
    if (!isPointerDown) return;

    const deltaX = e.clientX - startX;
    if (Math.abs(deltaX) > 4) hasDragged = true;

    scroller.scrollLeft = startScrollLeft - deltaX;
  }

  function onPointerUp() {
    if (!isPointerDown) return;

    isPointerDown = false;
    scroller.classList.remove("is-dragging");
    scroller.style.scrollBehavior = "";
  }

  function onClickCapture(e) {
    if (!hasDragged) return;
    e.preventDefault();
    e.stopPropagation();
    hasDragged = false;
  }

  scroller.addEventListener("pointerdown", onPointerDown);
  window.addEventListener("pointermove", onPointerMove);
  window.addEventListener("pointerup", onPointerUp);
  window.addEventListener("pointercancel", onPointerUp);
  scroller.addEventListener("click", onClickCapture, true);

  scrollActiveProductNavItemIntoView("auto");

  window.UNCOMMON.productNavHorizontalScrollCleanup = function () {
    scroller.removeEventListener("pointerdown", onPointerDown);
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
    window.removeEventListener("pointercancel", onPointerUp);
    scroller.removeEventListener("click", onClickCapture, true);
    scroller.classList.remove("is-dragging");
    scroller.style.scrollBehavior = "";
    window.UNCOMMON.productNavHorizontalScrollCleanup = null;
  };
}

// -----------------------------------------
// ODOMETER
// -----------------------------------------

function initScrollOdometer(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.scrollOdometerCleanup) {
    window.UNCOMMON.scrollOdometerCleanup();
    window.UNCOMMON.scrollOdometerCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;

  gsap.registerPlugin(ScrollTrigger);

  const page = getPageContainer(scope);
  const odometerEl = document.querySelector("[data-odometer-element]");
  const labelEl = document.querySelector("[data-odometer-label-element]");

  const sections = Array.from(page?.querySelectorAll("[data-odometer-step]") || [])
    .filter((section) => !isNaN(parseInt(section.getAttribute("data-odometer-step"), 10)));

  if (!odometerEl || !sections.length) return;

  ScrollTrigger.getAll()
    .filter((trigger) => trigger.vars && trigger.vars.__odometerTracker === true)
    .forEach((trigger) => trigger.kill());

  const duration =
    parseFloat(odometerEl.getAttribute("data-odometer-duration")) || 0.55;

  const baseTriggerRatio = gsap.utils.clamp(
    0.08,
    0.6,
    parseFloat(odometerEl.getAttribute("data-odometer-trigger-line")) || 0.22
  );

  const hysteresis = gsap.utils.clamp(
    0,
    0.12,
    parseFloat(odometerEl.getAttribute("data-odometer-hysteresis")) || 0.04
  );

  const firstSectionValue =
    parseInt(sections[0].getAttribute("data-odometer-step"), 10) || 1;

  const startValueAttr =
    parseInt(odometerEl.getAttribute("data-odometer-start"), 10);

  let displayedValue = !isNaN(startValueAttr) ? startValueAttr : firstSectionValue;
  let activeValue = displayedValue;

  let currentTimeline = null;
  let lastDirection = 1;
  let lastScrollY = window.scrollY;

  function formatNumber(value) {
    return String(value).padStart(2, "0");
  }

  function getLabelByValue(value) {
    const match = sections.find((section) => {
      return parseInt(section.getAttribute("data-odometer-step"), 10) === value;
    });

    return match ? (match.getAttribute("data-odometer-label") || "") : "";
  }

  function ensureNumberStructure() {
    let inner = odometerEl.querySelector("[data-odometer-inner]");
    let current = odometerEl.querySelector("[data-odometer-current]");
    let next = odometerEl.querySelector("[data-odometer-next]");

    if (!inner) {
      odometerEl.innerHTML = `
        <span data-odometer-inner>
          <span data-odometer-current></span>
          <span data-odometer-next></span>
        </span>
      `;
      inner = odometerEl.querySelector("[data-odometer-inner]");
      current = odometerEl.querySelector("[data-odometer-current]");
      next = odometerEl.querySelector("[data-odometer-next]");
    }

    return { inner, current, next };
  }

  function ensureLabelStructure() {
    if (!labelEl) return null;

    let inner = labelEl.querySelector("[data-odometer-label-inner]");
    let current = labelEl.querySelector("[data-odometer-label-current]");
    let next = labelEl.querySelector("[data-odometer-label-next]");

    if (!inner) {
      labelEl.innerHTML = `
        <span data-odometer-label-inner>
          <span data-odometer-label-current></span>
          <span data-odometer-label-next></span>
        </span>
      `;
      inner = labelEl.querySelector("[data-odometer-label-inner]");
      current = labelEl.querySelector("[data-odometer-label-current]");
      next = labelEl.querySelector("[data-odometer-label-next]");
    }

    return { inner, current, next };
  }

  function setNumberInstant(value) {
    const { current, next } = ensureNumberStructure();

    current.textContent = formatNumber(value);
    next.textContent = "";

    gsap.set(current, { yPercent: 0, opacity: 1 });
    gsap.set(next, { yPercent: 0, opacity: 0 });
  }

  function setLabelInstant(value) {
    if (!labelEl) return;

    const structure = ensureLabelStructure();
    if (!structure) return;

    const { inner, current, next } = structure;

    current.textContent = getLabelByValue(value);
    next.textContent = "";

    gsap.set(current, { yPercent: 0, opacity: 1 });
    gsap.set(next, { yPercent: 0, opacity: 0 });

    labelEl.style.width = "auto";
    inner.style.width = "auto";
  }

  function resetToDisplayedState() {
    setNumberInstant(displayedValue);
    setLabelInstant(displayedValue);
  }

  function animateToValue(nextValue) {
    if (isNaN(nextValue)) return;

    if (nextValue === activeValue && !currentTimeline) return;

    activeValue = nextValue;

    if (currentTimeline) {
      currentTimeline.kill();
      currentTimeline = null;
      resetToDisplayedState();
    }

    if (nextValue === displayedValue) return;

    const direction = nextValue > displayedValue ? 1 : -1;

    const num = ensureNumberStructure();
    const label = ensureLabelStructure();

    num.current.textContent = formatNumber(displayedValue);
    num.next.textContent = formatNumber(nextValue);

    gsap.set(num.current, {
      yPercent: 0,
      opacity: 1
    });

    gsap.set(num.next, {
      yPercent: direction > 0 ? 100 : -100,
      opacity: 1
    });

    if (label) {
      const currentLabel = getLabelByValue(displayedValue);
      const nextLabel = getLabelByValue(nextValue);

      label.current.textContent = currentLabel;
      label.next.textContent = nextLabel;

      gsap.set(label.current, {
        yPercent: 0,
        opacity: 1
      });

      gsap.set(label.next, {
        yPercent: direction > 0 ? 100 : -100,
        opacity: 1
      });

      labelEl.style.width = "auto";
      label.inner.style.width = "auto";

      const currentWidth = label.current.offsetWidth;
      const nextWidth = label.next.offsetWidth;
      const targetWidth = Math.max(currentWidth, nextWidth);

      labelEl.style.width = `${targetWidth}px`;
      label.inner.style.width = `${targetWidth}px`;
    }

    currentTimeline = gsap.timeline({
      defaults: {
        duration,
        ease: "uncommon"
      },
      onComplete: () => {
        displayedValue = nextValue;
        activeValue = nextValue;
        currentTimeline = null;
        resetToDisplayedState();
      }
    });

    currentTimeline.to(num.current, {
      yPercent: direction > 0 ? -100 : 100,
      opacity: 0
    }, 0);

    currentTimeline.to(num.next, {
      yPercent: 0,
      opacity: 1
    }, 0);

    if (label) {
      currentTimeline.to(label.current, {
        yPercent: direction > 0 ? -100 : 100,
        opacity: 0
      }, 0);

      currentTimeline.to(label.next, {
        yPercent: 0,
        opacity: 1
      }, 0);
    }
  }

  function getActiveSection() {
    const doc = document.documentElement;

    if (window.scrollY <= 2) return sections[0];
    if (window.innerHeight + window.scrollY >= doc.scrollHeight - 2) {
      return sections[sections.length - 1];
    }

    const ratio = gsap.utils.clamp(
      0.08,
      0.6,
      baseTriggerRatio + (lastDirection >= 0 ? hysteresis * 0.5 : -hysteresis * 0.5)
    );

    const triggerY = window.innerHeight * ratio;
    let lastPassed = sections[0];

    for (const section of sections) {
      const rect = section.getBoundingClientRect();

      if (rect.top <= triggerY && rect.bottom > triggerY) {
        return section;
      }

      if (rect.top <= triggerY) {
        lastPassed = section;
      }
    }

    return lastPassed;
  }

  function syncDirection(directionOverride) {
    if (typeof directionOverride === "number" && directionOverride !== 0) {
      lastDirection = directionOverride > 0 ? 1 : -1;
      lastScrollY = window.scrollY;
      return;
    }

    const currentY = window.scrollY;
    const delta = currentY - lastScrollY;

    if (delta !== 0) {
      lastDirection = delta > 0 ? 1 : -1;
    }

    lastScrollY = currentY;
  }

  function syncOdometerToScroll(directionOverride) {
    syncDirection(directionOverride);

    const activeSection = getActiveSection();
    if (!activeSection) return;

    const nextValue = parseInt(activeSection.getAttribute("data-odometer-step"), 10);
    if (isNaN(nextValue)) return;

    if (nextValue !== activeValue) {
      animateToValue(nextValue);
    }
  }

  resetToDisplayedState();

  const tracker = ScrollTrigger.create({
    __odometerTracker: true,
    trigger: page,
    start: "top top",
    end: "bottom bottom",
    onUpdate: (self) => {
      syncOdometerToScroll(self.direction);
    },
    onRefresh: () => {
      requestAnimationFrame(() => {
        syncOdometerToScroll();
      });
    }
  });

  requestAnimationFrame(() => {
    syncOdometerToScroll();
  });

  if (document.fonts?.ready?.then) {
    document.fonts.ready.then(() => {
      ScrollTrigger.refresh();
      syncOdometerToScroll();
    }).catch(() => {});
  }

  window.UNCOMMON.scrollOdometerCleanup = function () {
    tracker.kill();
    currentTimeline?.kill();
    currentTimeline = null;
    window.UNCOMMON.scrollOdometerCleanup = null;
  };
}

