function initSpecsAnchors(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.specsAnchorsCleanup) {
    window.UNCOMMON.specsAnchorsCleanup();
    window.UNCOMMON.specsAnchorsCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;
  gsap.registerPlugin(ScrollTrigger);

  const page = scope && scope.querySelector ? scope : document;

  const wrappers = Array.from(page.querySelectorAll(".specs_wrapper")).filter(
    (wrapper) =>
    wrapper.querySelector(".specs_li-link[data-anchor-link]") &&
    wrapper.querySelector("[data-anchor-section]")
  );

  if (!wrappers.length) return;

  const cleanups = [];

  wrappers.forEach((wrapper) => {
    const navLinks = Array.from(
      wrapper.querySelectorAll(".specs_li-link[data-anchor-link]")
    );

    const sections = Array.from(
      wrapper.querySelectorAll("[data-anchor-section]")
    ).filter((section) => section.getAttribute("data-anchor-section"));

    if (!navLinks.length || !sections.length) return;

    let isProgrammaticScroll = false;
    let activeAnchor = null;
    let fallbackTimer = null;

    function normalize(value) {
      return (value || "").trim();
    }

    function setActiveLink(anchorName) {
      const normalized = normalize(anchorName);
      if (!normalized) return;

      activeAnchor = normalized;

      navLinks.forEach((link) => {
        const isMatch = normalize(link.getAttribute("data-anchor-link")) === normalized;
        link.classList.toggle("is-active", isMatch);
      });
    }

    function getSectionByName(name) {
      const normalized = normalize(name);
      return sections.find(
        (section) =>
        normalize(section.getAttribute("data-anchor-section")) === normalized
      );
    }

    function getActiveSection() {
      if (!sections.length) return null;

      const triggerLine = window.innerHeight * 0.22;
      let current = sections[0];

      sections.forEach((section) => {
        const rect = section.getBoundingClientRect();
        if (rect.top <= triggerLine) current = section;
      });

      return current;
    }

    function updateActiveFromScroll() {
      if (isProgrammaticScroll) return;

      const activeSection = getActiveSection();
      if (!activeSection) return;

      const anchorName = activeSection.getAttribute("data-anchor-section");
      if (!anchorName || normalize(anchorName) === activeAnchor) return;

      setActiveLink(anchorName);
    }

    function finishProgrammaticScroll(anchorName) {
      isProgrammaticScroll = false;
      setActiveLink(anchorName);
      ScrollTrigger.refresh();
    }

    function scrollToSection(section, anchorName) {
      if (!section || !anchorName) return;

      isProgrammaticScroll = true;
      setActiveLink(anchorName);
      clearTimeout(fallbackTimer);

      if (typeof lenis !== "undefined" && lenis) {
        lenis.scrollTo(section, {
          duration: 1.1,
          lock: true,
          onComplete: () => finishProgrammaticScroll(anchorName)
        });

        fallbackTimer = setTimeout(() => {
          finishProgrammaticScroll(anchorName);
        }, 1400);
      } else {
        const targetY = section.getBoundingClientRect().top + window.pageYOffset;

        window.scrollTo({
          top: targetY,
          behavior: "smooth"
        });

        fallbackTimer = setTimeout(() => {
          finishProgrammaticScroll(anchorName);
        }, 1200);
      }
    }

    function handleClick(e) {
      const link = e.target.closest(".specs_li-link[data-anchor-link]");
      if (!link || !wrapper.contains(link)) return;

      const anchorName = link.getAttribute("data-anchor-link");
      const targetSection = getSectionByName(anchorName);

      if (!anchorName || !targetSection) return;

      e.preventDefault();
      scrollToSection(targetSection, anchorName);
    }

    wrapper.addEventListener("click", handleClick);

    const triggerElement = wrapper.closest("section") || wrapper;

    const st = ScrollTrigger.create({
      trigger: triggerElement,
      start: "top top",
      end: "bottom bottom",
      onUpdate: updateActiveFromScroll,
      onRefresh: updateActiveFromScroll
    });

    updateActiveFromScroll();

    cleanups.push(() => {
      clearTimeout(fallbackTimer);
      wrapper.removeEventListener("click", handleClick);
      st.kill();
    });
  });

  if (!cleanups.length) return;

  window.UNCOMMON.specsAnchorsCleanup = function () {
    cleanups.forEach((cleanup) => cleanup());
  };
}

function initLiveSearch() {
  document.querySelectorAll('[data-live-search]').forEach(function (root) {
    const input = root.querySelector('[data-live-search-input]');
    const notFound = root.querySelector('[data-live-search-not-found]');
    const listEl = root.querySelector('.live-search__list');

    if (!listEl) return;

    const searchableFields = [
      'live-search-title',
      'live-search-label',
      'live-search-value'
    ];

    // Build searchable data attributes on each list item
    Array.from(listEl.children).forEach(function (item) {
      const titleEls = Array.from(item.querySelectorAll('[data-live-search-title]'));
      const labelEls = Array.from(item.querySelectorAll('[data-live-search-label]'));
      const valueEls = Array.from(item.querySelectorAll('[data-live-search-value]'));

      const title = titleEls.map(el => el.textContent.trim()).filter(Boolean).join(' ');
      const labels = labelEls.map(el => el.textContent.trim()).filter(Boolean).join(' ');
      const values = valueEls.map(el => el.textContent.trim()).filter(Boolean).join(' ');

      item.setAttribute('data-live-search-title', title);
      item.setAttribute('data-live-search-label', labels);
      item.setAttribute('data-live-search-value', values);

      // Store original text once so we can safely restore it after highlighting
      [...titleEls, ...labelEls, ...valueEls].forEach(el => {
        if (!el.hasAttribute('data-live-search-original')) {
          el.setAttribute('data-live-search-original', el.textContent);
        }
      });
    });

    const options = {
      listClass: 'live-search__list',
      valueNames: [
        { data: searchableFields }
      ],
      fuzzySearch: {
        location: 0,
        distance: 100,
        threshold: 0.3
      }
    };

    const list = new List(root, options);

    function escapeRegExp(string) {
      return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function getSearchTerms(query) {
      return query
        .trim()
        .split(/\s+/)
        .map(term => term.trim())
        .filter(Boolean)
        .filter((term, index, arr) => arr.indexOf(term) === index)
        .sort((a, b) => b.length - a.length);
    }

    function clearHighlights() {
      root.querySelectorAll(
        '[data-live-search-title], [data-live-search-label], [data-live-search-value]'
      ).forEach(el => {
        const original = el.getAttribute('data-live-search-original');
        if (original !== null) {
          el.textContent = original;
        }
      });
    }

    function highlightElement(el, terms) {
      const original = el.getAttribute('data-live-search-original');
      if (!original) return;

      if (!terms.length) {
        el.textContent = original;
        return;
      }

      const pattern = terms.map(term => escapeRegExp(term)).join('|');
      if (!pattern) {
        el.textContent = original;
        return;
      }

      const regex = new RegExp(`(${pattern})`, 'gi');
      el.innerHTML = original.replace(regex, '<span class="live-search__highlight">$1</span>');
    }

    function applyHighlights(query) {
      clearHighlights();

      const terms = getSearchTerms(query);
      if (!terms.length) return;

      list.matchingItems.forEach(item => {
        const itemEl = item.elm;
        if (!itemEl) return;

        itemEl.querySelectorAll(
          '[data-live-search-title], [data-live-search-label], [data-live-search-value]'
        ).forEach(el => {
          highlightElement(el, terms);
        });
      });
    }

    function updateNotFound() {
      if (!notFound) return;

      const q = (input && input.value ? input.value : '').trim();

      if (list.matchingItems.length === 0 && q !== '') {
        notFound.style.display = 'block';
        const p = notFound.querySelector('p');
        if (p) p.textContent = `We couldn't find a match for "${q}" 😕`;
      } else {
        notFound.style.display = 'none';
      }
    }

    function runSearch() {
      const q = (input && input.value ? input.value : '').trim();

      if (!q) {
        list.search();
        clearHighlights();
        updateNotFound();
        return;
      }

      if (typeof list.fuzzySearch === 'function') {
        list.fuzzySearch(q, searchableFields);
      } else {
        list.search(q, searchableFields);
      }

      applyHighlights(q);
      updateNotFound();
    }

    if (input) {
      input.addEventListener('input', runSearch);
    }

    root._pageSearchList = list;

    list.search();
    clearHighlights();
    updateNotFound();
  });
}

function initSpecsHorizontalScroll() {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.specsHorizontalScrollCleanup) {
    window.UNCOMMON.specsHorizontalScrollCleanup();
    window.UNCOMMON.specsHorizontalScrollCleanup = null;
  }

  const scroller = document.querySelector("[data-specs-nav-scroll]");
  if (!scroller) return;

  // alleen tablet en kleiner
  if (window.innerWidth > 991) {
    scroller.style.removeProperty("--specs-fade-left");
    scroller.style.removeProperty("--specs-fade-right");
    return;
  }

  let isPointerDown = false;
  let startX = 0;
  let startScrollLeft = 0;
  let hasDragged = false;

  function updateEdgeFade() {
    const maxScroll = scroller.scrollWidth - scroller.clientWidth;

    if (maxScroll <= 2) {
      scroller.style.setProperty("--specs-fade-left", "0px");
      scroller.style.setProperty("--specs-fade-right", "0px");
      return;
    }

    const atStart = scroller.scrollLeft <= 2;
    const atEnd = scroller.scrollLeft >= maxScroll - 2;

    scroller.style.setProperty(
      "--specs-fade-left",
      atStart ? "0px" : "var(--specs-fade-size)"
    );

    scroller.style.setProperty(
      "--specs-fade-right",
      atEnd ? "0px" : "var(--specs-fade-size)"
    );
  }

  function onPointerDown(e) {
    // touch doet native scroll al prima, dus alleen mouse drag
    if (e.pointerType !== "mouse") return;
    if (e.button !== 0) return;

    isPointerDown = true;
    hasDragged = false;
    startX = e.clientX;
    startScrollLeft = scroller.scrollLeft;

    scroller.classList.add("is-dragging");
    scroller.style.scrollBehavior = "auto";
  }

  function onPointerMove(e) {
    if (!isPointerDown) return;

    const deltaX = e.clientX - startX;
    if (Math.abs(deltaX) > 4) hasDragged = true;

    scroller.scrollLeft = startScrollLeft - deltaX;
    updateEdgeFade();
  }

  function onPointerUp() {
    if (!isPointerDown) return;

    isPointerDown = false;
    scroller.classList.remove("is-dragging");
    scroller.style.scrollBehavior = "";
  }

  function onClickCapture(e) {
    if (!hasDragged) return;
    e.preventDefault();
    e.stopPropagation();
    hasDragged = false;
  }

  function onScroll() {
    updateEdgeFade();
  }

  function onResize() {
    if (window.innerWidth > 991) {
      scroller.style.removeProperty("--specs-fade-left");
      scroller.style.removeProperty("--specs-fade-right");
      return;
    }
    updateEdgeFade();
  }

  scroller.addEventListener("pointerdown", onPointerDown);
  window.addEventListener("pointermove", onPointerMove);
  window.addEventListener("pointerup", onPointerUp);
  window.addEventListener("pointercancel", onPointerUp);
  scroller.addEventListener("click", onClickCapture, true);
  scroller.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onResize);

  updateEdgeFade();

  window.UNCOMMON.specsHorizontalScrollCleanup = function () {
    scroller.removeEventListener("pointerdown", onPointerDown);
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
    window.removeEventListener("pointercancel", onPointerUp);
    scroller.removeEventListener("click", onClickCapture, true);
    scroller.removeEventListener("scroll", onScroll);
    window.removeEventListener("resize", onResize);
    scroller.classList.remove("is-dragging");
    scroller.style.scrollBehavior = "";
    scroller.style.removeProperty("--specs-fade-left");
    scroller.style.removeProperty("--specs-fade-right");
  };
}

function initAccordionCSS() {
  document.querySelectorAll('[data-accordion-css-init]').forEach((accordion) => {
    const closeSiblings = accordion.getAttribute('data-accordion-close-siblings') === 'true';

    accordion.addEventListener('click', (event) => {
      const toggle = event.target.closest('[data-accordion-toggle]');
      if (!toggle) return; // Exit if the clicked element is not a toggle

      const singleAccordion = toggle.closest('[data-accordion-status]');
      if (!singleAccordion) return; // Exit if no accordion container is found

      const isActive = singleAccordion.getAttribute('data-accordion-status') === 'active';
      singleAccordion.setAttribute('data-accordion-status', isActive ? 'not-active' :
        'active');

      // When [data-accordion-close-siblings="true"]
      if (closeSiblings && !isActive) {
        accordion.querySelectorAll('[data-accordion-status="active"]').forEach((
          sibling) => {
          if (sibling !== singleAccordion) sibling.setAttribute('data-accordion-status',
            'not-active');
        });
      }
    });
  });
}

