function initBikeExplorerSequence(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.bikeExplorerSequenceCleanup) {
    window.UNCOMMON.bikeExplorerSequenceCleanup();
    window.UNCOMMON.bikeExplorerSequenceCleanup = null;
  }

  if (window.innerWidth < 992) return;
  if (typeof ScrollTrigger === "undefined") return;

  const page = getPageContainer(scope);
  const explorers = Array.from(page?.querySelectorAll("[data-bike-explorer]") || []);
  if (!explorers.length) return;

  const cleanups = [];

  explorers.forEach((explorer) => {
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const startChapter = explorer.querySelector('[data-chapter="start"]');
    const endChapter = explorer.querySelector('[data-chapter="end"]');

    const sequenceWraps = Array.from(
      explorer.querySelectorAll('.bike-explorer__sequence-wrap[data-color]')
    );

    if (!startChapter || !endChapter || !sequenceWraps.length) return;

    // ── Sequence config ────────────────────────────────────────────────────
    // No hold chapter anymore. The full sequence scrubs continuously.
    const HOLD_FRAME = 30;

    // Controls when hotspot groups appear.
    // Lower = earlier. Higher = later.
    const HOTSPOT_GROUP_1_PROGRESS = 0.18;
    const HOTSPOT_GROUP_2_PROGRESS = 0.58;

    const hotspotGroups = {
      1: Array.from(explorer.querySelectorAll('[data-hotspot-group="1"]')),
      2: Array.from(explorer.querySelectorAll('[data-hotspot-group="2"]'))
    };

    let activeHotspotGroup = null;

    function setHotspotGroup(group) {
      if (activeHotspotGroup === group) return;

      activeHotspotGroup = group;

      explorer.setAttribute("data-hotspot-state", group ? `group-${group}` : "none");

      Object.entries(hotspotGroups).forEach(([key, elements]) => {
        const shouldShow = String(group) === key;

        if (!elements.length) return;

        if (typeof gsap !== "undefined") {
          gsap.to(elements, {
            autoAlpha: shouldShow ? 1 : 0,
            y: shouldShow ? 0 : 16,
            duration: shouldShow ? 0.45 : 0.25,
            stagger: shouldShow ? 0.06 : 0,
            overwrite: true
          });
        } else {
          elements.forEach((el) => {
            el.style.visibility = shouldShow ? "visible" : "hidden";
            el.style.opacity = shouldShow ? "1" : "0";
          });
        }
      });
    }

    function updateHotspots(progress) {
      if (progress >= HOTSPOT_GROUP_2_PROGRESS) {
        setHotspotGroup(2);
      } else if (progress >= HOTSPOT_GROUP_1_PROGRESS) {
        setHotspotGroup(1);
      } else {
        setHotspotGroup(null);
      }
    }

    if (typeof gsap !== "undefined") {
      Object.values(hotspotGroups).flat().forEach((el) => {
        gsap.set(el, {
          autoAlpha: 0,
          y: 16
        });
      });
    } else {
      Object.values(hotspotGroups).flat().forEach((el) => {
        el.style.visibility = "hidden";
        el.style.opacity = "0";
      });
    }

    // Read the first canvas to derive shared frame metadata.
    const firstCanvas = sequenceWraps[0]?.querySelector("[data-sequence-canvas]");
    const totalFrames = parseInt(firstCanvas?.dataset.frames, 10) || 85;
    const indexStart = parseInt(firstCanvas?.dataset.indexStart, 10) || 1;

    // Kept only as a reference point for the side-view frame.
    const holdProgress = (HOLD_FRAME - indexStart) / (totalFrames - 1);

    // ── Build per-canvas renderers ─────────────────────────────────────────
    const sequences = sequenceWraps.map((wrap) => {
      const element = wrap.querySelector("[data-sequence-element]");
      const canvas = wrap.querySelector("[data-sequence-canvas]");
      if (!element || !canvas) return null;

      const frames = parseInt(canvas.dataset.frames, 10) || 1;
      const digits = parseInt(canvas.dataset.digits, 10) || 3;
      const idxStart = parseInt(canvas.dataset.indexStart, 10) || 1;
      const desktopSrc = canvas.dataset.desktopSrc || "";
      const staticSrc = canvas.dataset.staticSrc || "";
      const filetype = canvas.dataset.filetype || "webp";
      const lastIndex = idxStart + frames - 1;

      const ctx = canvas.getContext("2d");
      if (!ctx) return null;

      const loaded = new Map();
      const loading = new Set();

      let resizeTimer = null;
      let currentProgress = 0;
      let lastRenderedIndex = null;

      function pad(num) {
        return String(num).padStart(digits, "0");
      }

      function getUrl(i) {
        return `${desktopSrc}${pad(i)}.${filetype}`;
      }

      function resizeCanvas() {
        const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
        const w = element.clientWidth;
        const h = element.clientHeight;

        if (!w || !h) return;

        if (canvas.width !== w * dpr || canvas.height !== h * dpr) {
          canvas.width = w * dpr;
          canvas.height = h * dpr;
          canvas.style.width = `${w}px`;
          canvas.style.height = `${h}px`;
        }
      }

      function drawCover(img) {
        if (!img) return;

        resizeCanvas();

        const cw = canvas.width;
        const ch = canvas.height;

        const scale = Math.max(cw / img.width, ch / img.height);
        const x = (cw - img.width * scale) / 2;
        const y = (ch - img.height * scale) / 2;

        ctx.clearRect(0, 0, cw, ch);
        ctx.drawImage(img, x, y, img.width * scale, img.height * scale);
      }

      function loadFrame(i, onDone) {
        if (i < idxStart || i > lastIndex) {
          onDone?.();
          return;
        }

        if (loaded.has(i)) {
          onDone?.();
          return;
        }

        if (loading.has(i)) return;

        loading.add(i);

        const img = new Image();
        img.decoding = "async";
        img.src = getUrl(i);

        img.onload = () => {
          loading.delete(i);
          loaded.set(i, img);
          onDone?.();
        };

        img.onerror = () => {
          loading.delete(i);
          onDone?.();
        };
      }

      function preloadAll() {
        loadFrame(idxStart, () => renderProgress(0, true));
        loadFrame(lastIndex);

        for (let i = idxStart + 1; i < lastIndex; i++) {
          loadFrame(i);
        }
      }

      function findNearestLoaded(i) {
        if (loaded.has(i)) return i;

        for (let r = 1; r <= 8; r++) {
          if (loaded.has(i - r)) return i - r;
          if (loaded.has(i + r)) return i + r;
        }

        return null;
      }

      function drawFrame(index, force = false) {
        if (!force && lastRenderedIndex === index) return;

        const nearestIndex = findNearestLoaded(index);
        const img = loaded.get(index) || loaded.get(nearestIndex);

        if (!img) return;

        drawCover(img);
        lastRenderedIndex = index;
      }

      function progressToIndex(p) {
        const clamped = Math.max(0, Math.min(1, p));

        if (clamped <= 0) return idxStart;
        if (clamped >= 0.999) return lastIndex;

        return idxStart + Math.round(clamped * (frames - 1));
      }

      function renderProgress(p, force = false) {
        const clamped = Math.max(0, Math.min(1, p));
        drawFrame(progressToIndex(clamped), force);
      }

      function handleResize() {
        clearTimeout(resizeTimer);

        resizeTimer = setTimeout(() => {
          resizeCanvas();
          lastRenderedIndex = null;
          renderProgress(currentProgress, true);
          ScrollTrigger?.refresh();
        }, 150);
      }

      window.addEventListener("resize", handleResize);
      cleanups.push(() => window.removeEventListener("resize", handleResize));

      resizeCanvas();

      if (reduceMotion) {
        if (staticSrc) {
          const img = new Image();
          img.src = staticSrc;
          img.onload = () => drawCover(img);
        } else {
          loadFrame(idxStart, () => renderProgress(0, true));
        }

        return null;
      }

      preloadAll();

      return {
        render(p) {
          currentProgress = p;
          renderProgress(p);
        },

        renderStart() {
          currentProgress = 0;
          renderProgress(0, true);
        },

        renderSideView() {
          currentProgress = holdProgress;
          renderProgress(holdProgress, true);
        },

        renderEnd() {
          currentProgress = 1;
          drawFrame(lastIndex, true);
        }
      };
    }).filter(Boolean);

    if (!sequences.length) return;

    function renderAll(p) {
      sequences.forEach((s) => s.render(p));
    }

    function renderStartAll() {
      sequences.forEach((s) => s.renderStart());
    }

    function renderEndAll() {
      sequences.forEach((s) => s.renderEnd());
    }

    renderStartAll();
    setHotspotGroup(null);

    if (reduceMotion) return;

    // ── Single continuous scrub: start → end ────────────────────────────────
    // The full sequence now scrubs from frame 1 to the last frame.
    const stSequence = ScrollTrigger.create({
      trigger: explorer,
      start: "top bottom",
      endTrigger: endChapter,
      end: "bottom bottom",
      scrub: true,

      onUpdate: (self) => {
        const progress = self.progress;

        renderAll(progress);
        updateHotspots(progress);
      },

      onLeave: () => {
        renderEndAll();
        setHotspotGroup(2);
      },

      onLeaveBack: () => {
        renderStartAll();
        setHotspotGroup(null);
      }
    });

    cleanups.push(() => stSequence.kill());
  });

  window.UNCOMMON.bikeExplorerSequenceCleanup = () => {
    cleanups.forEach((fn) => fn());
    window.UNCOMMON.bikeExplorerSequenceCleanup = null;
  };
}

function initBikeExplorer(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.bikeExplorerCleanup) {
    window.UNCOMMON.bikeExplorerCleanup();
    window.UNCOMMON.bikeExplorerCleanup = null;
  }

  const page = getPageContainer(scope);
  const explorers = Array.from(page?.querySelectorAll("[data-bike-explorer]") || []);
  if (!explorers.length) return;
  if (typeof ScrollTrigger === "undefined" || typeof gsap === "undefined") return;

  const cleanups = [];

  explorers.forEach((explorer, index) => {
    const sequenceWraps = Array.from(
      explorer.querySelectorAll(".bike-explorer__sequence-wrap[data-color]")
    );

    const colorImages = Array.from(
      explorer.querySelectorAll(".bike-explorer-color__img[data-bike-color]")
    );

    // Mapping voor naam-verschil tussen switch ("dark") en image ("grey").
    // Verwijder dit als je je image-attribute aanpast naar data-bike-color="dark".
    const COLOR_ALIAS = { dark: "grey" };
    const resolveImageColor = (color) => COLOR_ALIAS[color] || color;

    const hotspotGroups = Array.from(explorer.querySelectorAll("[data-hotspot-group]"));
    const hotspotButtons = Array.from(explorer.querySelectorAll("[data-hotspot-trigger]"));
    const storeItems = Array.from(explorer.querySelectorAll("[data-hotspot-content]"));

    const modal = explorer.querySelector("[data-hotspot-modal]");
    const modalBackdrop = explorer.querySelector(".bike-modal__backdrop");
    const modalCard = explorer.querySelector(".bike-modal__card");
    const modalMedia = explorer.querySelector("[data-modal-media]");
    const modalContent = explorer.querySelector("[data-modal-content]");
    const modalPrev = explorer.querySelector("[data-modal-prev]");
    const modalNext = explorer.querySelector("[data-modal-next]");
    const modalProgress = explorer.querySelector(".bike-modal__nav-progress");
    const modalCloseButtons = Array.from(explorer.querySelectorAll("[data-modal-close]"));

    const colorButtons = Array.from(explorer.querySelectorAll("[data-color-target]"));

    const chapters = {
      start: explorer.querySelector('[data-chapter="start"]'),
      end: explorer.querySelector('[data-chapter="end"]')
    };

    if (!chapters.start || !chapters.end) return;

    // ─── Hotspot timing ────────────────────────────────────────────────────
    const HOTSPOT_GROUP_1_PROGRESS = 0.18;
    const HOTSPOT_GROUP_2_PROGRESS = 0.58;

    const state = {
      activeGroup: null,
      activeColor: sequenceWraps.find((w) => w.classList.contains("is-active"))?.dataset
        .color ||
        sequenceWraps[0]?.dataset.color ||
        "yellow",
      activeHotspotId: null,
      modalOpen: false,

      // "group" = navigeer binnen de huidige hotspot-groep (default).
      // "all"   = navigeer door álle hotspots achter elkaar — gebruikt
      //           wanneer de modal vanuit een swiper-slide wordt geopend.
      navigationMode: "group"
    };

    let modalMountedToBody = false;

    // ─── Scroll lock ───────────────────────────────────────────────────────

    function getLenisInstance() {
      if (typeof lenis !== "undefined" && lenis) return lenis;
      if (window.lenis) return window.lenis;
      if (window.UNCOMMON?.lenis) return window.UNCOMMON.lenis;
      return null;
    }

    function lockExplorerScroll() {
      const sl = window.UNCOMMON?.scrollLock;
      if (sl?.lock) {
        sl.lock();
        return;
      }

      getLenisInstance()?.stop?.();
    }

    function unlockExplorerScroll() {
      const sl = window.UNCOMMON?.scrollLock;
      if (sl?.unlock) {
        sl.unlock();
        return;
      }

      const l = getLenisInstance();
      l?.start?.();
      l?.resize?.();
    }

    // ─── Modal helpers ─────────────────────────────────────────────────────

    function ensureModalMountedToBody() {
      if (!modal || modal.parentNode === document.body) return;

      modal.dataset.bikeModalOwner = `bike-modal-${index}`;
      document.body.appendChild(modal);
      modalMountedToBody = true;
    }

    function getModalOffscreenX() {
      return (modalCard?.offsetWidth || modalCard?.getBoundingClientRect().width || 0) + 40;
    }

    function getHotspotId(button) {
      return button?.dataset.hotspotTrigger || null;
    }

    function getStoreItemById(id) {
      return storeItems.find((item) => item.dataset.hotspotContent === id) || null;
    }

    function getGroupEl(groupId) {
      return hotspotGroups.find((group) => group.dataset.hotspotGroup === String(groupId)) ||
        null;
    }

    function getGroupButtons(groupId) {
      const group = getGroupEl(groupId);
      if (!group) return [];
      return Array.from(group.querySelectorAll("[data-hotspot-trigger]"));
    }

    function getButtonGroup(button) {
      return button?.closest("[data-hotspot-group]")?.dataset.hotspotGroup || null;
    }

    // In "all" mode geven we elke hotspot terug, ongeacht groep.
    function getActiveGroupButtons() {
      if (state.navigationMode === "all") return hotspotButtons;
      if (!state.activeGroup) return [];
      return getGroupButtons(state.activeGroup);
    }

    function getGroupByHotspotId(id) {
      const button = hotspotButtons.find((btn) => getHotspotId(btn) === id);
      return getButtonGroup(button);
    }

    // ─── Hotspot animation ─────────────────────────────────────────────────

    function setGroupButtonsHidden(groupId) {
      const group = getGroupEl(groupId);
      const buttons = getGroupButtons(groupId);

      gsap.killTweensOf(buttons);

      if (buttons.length) {
        gsap.set(buttons, {
          autoAlpha: 0,
          scale: 0,
          pointerEvents: "none",
          transformOrigin: "50% 50%"
        });
      }

      if (group) {
        gsap.set(group, {
          autoAlpha: 0,
          pointerEvents: "none"
        });
      }
    }

    function revealHotspotGroup(groupId) {
      const group = getGroupEl(groupId);
      const buttons = getGroupButtons(groupId);

      if (!group || !buttons.length) return;

      gsap.set(group, {
        autoAlpha: 1,
        pointerEvents: "auto"
      });

      gsap.killTweensOf(buttons);

      gsap.set(buttons, {
        pointerEvents: "auto"
      });

      gsap.fromTo(
        buttons,
        {
          autoAlpha: 0,
          scale: 0,
          transformOrigin: "50% 50%"
        },
        {
          autoAlpha: 1,
          scale: 1,
          duration: 0.45,
          ease: "back.out(1.7)",
          stagger: 0.08,
          overwrite: true
        }
      );
    }

    function hideHotspotGroup(groupId, instant = false) {
      const group = getGroupEl(groupId);
      const buttons = getGroupButtons(groupId);

      if (!group || !buttons.length) return;

      gsap.killTweensOf(buttons);

      if (instant) {
        gsap.set(buttons, {
          autoAlpha: 0,
          scale: 0,
          pointerEvents: "none"
        });

        gsap.set(group, {
          autoAlpha: 0,
          pointerEvents: "none"
        });

        return;
      }

      gsap.to(buttons, {
        autoAlpha: 0,
        scale: 0,
        duration: 0.24,
        ease: "power2.in",
        stagger: {
          each: 0.04,
          from: "end"
        },
        overwrite: true,
        onComplete: () => {
          gsap.set(buttons, {
            pointerEvents: "none"
          });

          gsap.set(group, {
            autoAlpha: 0,
            pointerEvents: "none"
          });
        }
      });
    }

    function setActiveHotspotGroup(groupId) {
      const nextGroup = groupId ? String(groupId) : null;
      if (state.activeGroup === nextGroup) return;

      const previousGroup = state.activeGroup;
      state.activeGroup = nextGroup;

      explorer.setAttribute(
        "data-hotspot-state",
        nextGroup ? `group-${nextGroup}` : "none"
      );

      if (previousGroup) {
        hideHotspotGroup(previousGroup, false);
      }

      if (nextGroup) {
        revealHotspotGroup(nextGroup);
      }

      updateModalProgress();
    }

    function updateHotspotGroupsByProgress(progress) {
      if (progress >= HOTSPOT_GROUP_2_PROGRESS) {
        setActiveHotspotGroup("2");
      } else if (progress >= HOTSPOT_GROUP_1_PROGRESS) {
        setActiveHotspotGroup("1");
      } else {
        setActiveHotspotGroup(null);
      }
    }

    function hideAllHotspotGroupsInstant() {
      hotspotGroups.forEach((group) => {
        setGroupButtonsHidden(group.dataset.hotspotGroup);
      });

      state.activeGroup = null;
      explorer.setAttribute("data-hotspot-state", "none");
    }

    // ─── Modal content ─────────────────────────────────────────────────────

    function updateModalProgress() {
      if (!modalProgress) return;

      const groupButtons = getActiveGroupButtons();
      modalProgress.innerHTML = "";

      groupButtons.forEach((button, i) => {
        const hotspotId = getHotspotId(button);

        const label =
          button.querySelector(".bike-hotspot__label")?.textContent?.trim() ||
          `Slide ${i + 1}`;

        const dot = document.createElement("button");
        dot.type = "button";
        dot.className = "bike-modal__progress-dot";
        dot.setAttribute("aria-label", label);
        dot.setAttribute("title", label);

        if (hotspotId === state.activeHotspotId) {
          dot.classList.add("is-active");
          dot.setAttribute("aria-current", "true");
        }

        dot.addEventListener("click", () => {
          if (!state.modalOpen || !hotspotId || hotspotId === state.activeHotspotId)
            return;

          const currentIndex = groupButtons.findIndex(
            (btn) => getHotspotId(btn) === state.activeHotspotId
          );

          const nextIndex = groupButtons.findIndex(
            (btn) => getHotspotId(btn) === hotspotId
          );

          swapModalContent(hotspotId, nextIndex >= currentIndex ? 1 : -1);
        });

        modalProgress.appendChild(dot);
      });

      const hasMultiple = groupButtons.length > 1;

      if (modalPrev) {
        modalPrev.disabled = !hasMultiple;
        modalPrev.style.pointerEvents = hasMultiple ? "auto" : "none";
        modalPrev.style.opacity = hasMultiple ? "1" : "0.35";
      }

      if (modalNext) {
        modalNext.disabled = !hasMultiple;
        modalNext.style.pointerEvents = hasMultiple ? "auto" : "none";
        modalNext.style.opacity = hasMultiple ? "1" : "0.35";
      }

      modalProgress.style.visibility = groupButtons.length ? "visible" : "hidden";
    }

    function clearHotspotOpenStates() {
      hotspotButtons.forEach((btn) => btn.classList.remove("is-open"));
    }

    function setModalContent(id) {
      const item = getStoreItemById(id);
      if (!item || !modalMedia || !modalContent) return;

      toggleModalMedia(modal, "stop");

      const media = item.querySelector("[data-hotspot-media]");
      const text = item.querySelector("[data-hotspot-text]");

      modalMedia.innerHTML = media ? media.innerHTML : "";
      modalContent.innerHTML = text ? text.innerHTML : item.innerHTML;
      modalContent.scrollTop = 0;

      clearHotspotOpenStates();

      const activeButton = hotspotButtons.find((btn) => getHotspotId(btn) === id);
      activeButton?.classList.add("is-open");

      // Alleen in "group" mode synchroniseren we de bike's groep-state.
      // In "all" mode mag de bike z'n eigen groep-state houden zodat de
      // dots op de fiets niet wisselen tijdens modal-navigatie.
      if (state.navigationMode === "group") {
        const activeButtonGroup = getButtonGroup(activeButton);
        if (activeButtonGroup && state.activeGroup !== activeButtonGroup) {
          state.activeGroup = activeButtonGroup;
          explorer.setAttribute("data-hotspot-state", `group-${activeButtonGroup}`);
        }
      }

      state.activeHotspotId = id;

      updateModalProgress();
    }

    function swapModalContent(id, direction = 1) {
      if (!modal || !modalMedia || !modalContent || id === state.activeHotspotId) return;

      gsap.killTweensOf([modalMedia, modalContent]);

      const tl = gsap.timeline({
        defaults: {
          ease: "uncommon"
        }
      });

      tl.to(
        [modalMedia, modalContent],
        {
          x: direction > 0 ? -20 : 20,
          autoAlpha: 0,
          duration: 0.22
        },
        0
      );

      tl.add(() => {
        setModalContent(id);

        gsap.set([modalMedia, modalContent], {
          x: direction > 0 ? 20 : -20,
          autoAlpha: 0
        });

        toggleModalMedia(modal, "play");
      });

      tl.to([modalMedia, modalContent], {
        x: 0,
        autoAlpha: 1,
        duration: 0.32
      });
    }

    function openModal(id, options = {}) {
      if (!modal || !modalBackdrop || !modalCard) return;

      ensureModalMountedToBody();

      // Bij een "fresh" open (modal was dicht) leggen we de navigation
      // mode vast voor de duur van deze sessie. Latere swaps via
      // prev/next/dots erven die mode.
      if (!state.modalOpen) {
        state.navigationMode = options.mode === "all" ? "all" : "group";
      }

      // Alleen in "group" mode laten we de bike z'n hotspot-groep volgen.
      if (state.navigationMode === "group") {
        const groupForId = getGroupByHotspotId(id);
        if (groupForId) {
          state.activeGroup = groupForId;
          explorer.setAttribute("data-hotspot-state", `group-${groupForId}`);
        }
      }

      if (state.modalOpen) {
        const groupButtons = getActiveGroupButtons();

        const currentIndex = groupButtons.findIndex(
          (btn) => getHotspotId(btn) === state.activeHotspotId
        );

        const nextIndex = groupButtons.findIndex(
          (btn) => getHotspotId(btn) === id
        );

        swapModalContent(id, nextIndex >= currentIndex ? 1 : -1);
        return;
      }

      setModalContent(id);

      state.modalOpen = true;
      modal.hidden = false;
      modal.classList.add("is-active");

      lockExplorerScroll();

      gsap.killTweensOf([modalBackdrop, modalCard, modalMedia, modalContent]);

      gsap.set(modalBackdrop, {
        autoAlpha: 0
      });

      gsap.set(modalCard, {
        x: getModalOffscreenX()
      });

      gsap.set([modalMedia, modalContent], {
        x: 0,
        autoAlpha: 1
      });

      toggleModalMedia(modal, "play");

      gsap.timeline({
          defaults: {
            ease: "uncommon"
          }
        })
        .to(
          modalBackdrop,
          {
            autoAlpha: 1,
            duration: 0.28
          },
          0
        )
        .to(
          modalCard,
          {
            x: 0,
            duration: 0.7
          },
          0
        );
    }

    function closeModal() {
      if (!modal || !modalBackdrop || !modalCard || !state.modalOpen) return;

      state.modalOpen = false;
      clearHotspotOpenStates();

      toggleModalMedia(modal, "stop");

      gsap.killTweensOf([modalBackdrop, modalCard, modalMedia, modalContent]);

      gsap.timeline({
          defaults: {
            ease: "uncommon"
          },
          onComplete: () => {
            if (!state.modalOpen) {
              modal.hidden = true;
              modal.classList.remove("is-active");
            }

            unlockExplorerScroll();
          }
        })
        .to(
          modalBackdrop,
          {
            autoAlpha: 0,
            duration: 0.22
          },
          0
        )
        .to(
          modalCard,
          {
            x: getModalOffscreenX(),
            duration: 0.62
          },
          0
        );
    }

    function stepModal(direction) {
      const groupButtons = getActiveGroupButtons();
      if (!groupButtons.length) return;

      const currentIndex = groupButtons.findIndex(
        (btn) => getHotspotId(btn) === state.activeHotspotId
      );

      const nextIndex =
        currentIndex === -1 ?
        0 :
        (currentIndex + direction + groupButtons.length) % groupButtons.length;

      const nextId = getHotspotId(groupButtons[nextIndex]);

      if (nextId) {
        swapModalContent(nextId, direction);
      }
    }

    // ─── Color switch ──────────────────────────────────────────────────────

    function syncColorUI() {
      sequenceWraps.forEach((wrap) => {
        wrap.classList.toggle("is-active", wrap.dataset.color === state.activeColor);
      });

      colorButtons.forEach((btn) => {
        btn.classList.toggle("is-active", btn.dataset.colorTarget === state.activeColor);
      });

      const imageColor = resolveImageColor(state.activeColor);
      colorImages.forEach((img) => {
        img.classList.toggle("is-active", img.dataset.bikeColor === imageColor);
      });
    }

    // ─── Event listeners ───────────────────────────────────────────────────

    colorButtons.forEach((btn) => {
      const onClick = () => {
        if (!btn.dataset.colorTarget || btn.dataset.colorTarget === state.activeColor)
          return;

        state.activeColor = btn.dataset.colorTarget;
        syncColorUI();
      };

      btn.addEventListener("click", onClick);
      cleanups.push(() => btn.removeEventListener("click", onClick));
    });

    hotspotButtons.forEach((btn) => {
      const onClick = (e) => {
        e.preventDefault();

        const id = getHotspotId(btn);
        if (id) openModal(id); // interne hotspot → default "group" mode
      };

      btn.addEventListener("click", onClick);
      cleanups.push(() => btn.removeEventListener("click", onClick));
    });

    // ─── External triggers ─────────────────────────────────────────────────
    // Triggers buiten de explorer (bv. CTA's, swiper-slides). Wanneer de
    // trigger binnen een .swiper-slide zit, opent de modal in "all" mode
    // zodat álle items doorlopen kunnen worden in plaats van alleen de
    // groep waartoe de id behoort.
    //
    // Override mogelijk via [data-hotspot-mode="all" | "group"] op de trigger.

    function handleExternalTriggerClick(e) {
      const trigger = e.target.closest("[data-hotspot-trigger]");
      if (!trigger) return;
      if (explorer.contains(trigger)) return;

      const id = trigger.dataset.hotspotTrigger;
      if (!id) return;
      if (!getStoreItemById(id)) return;

      const explicitMode = trigger.dataset.hotspotMode;
      const inSwiperSlide = !!trigger.closest(".swiper-slide");
      const mode = explicitMode || (inSwiperSlide ? "all" : "group");

      e.preventDefault();
      openModal(id, { mode });
    }

    document.addEventListener("click", handleExternalTriggerClick);
    cleanups.push(() => document.removeEventListener("click", handleExternalTriggerClick));

    modalCloseButtons.forEach((btn) => {
      btn.addEventListener("click", closeModal);
      cleanups.push(() => btn.removeEventListener("click", closeModal));
    });

    if (modalPrev) {
      const fn = () => stepModal(-1);
      modalPrev.addEventListener("click", fn);
      cleanups.push(() => modalPrev.removeEventListener("click", fn));
    }

    if (modalNext) {
      const fn = () => stepModal(1);
      modalNext.addEventListener("click", fn);
      cleanups.push(() => modalNext.removeEventListener("click", fn));
    }

    function handleKeydown(e) {
      if (!state.modalOpen) return;

      if (e.key === "Escape") closeModal();
      if (e.key === "ArrowLeft") stepModal(-1);
      if (e.key === "ArrowRight") stepModal(1);
    }

    document.addEventListener("keydown", handleKeydown);
    cleanups.push(() => document.removeEventListener("keydown", handleKeydown));

    // ─── Init: hide all hotspot groups ─────────────────────────────────────

    hideAllHotspotGroupsInstant();

    // ─── ScrollTrigger: hotspot group switching, no hold chapter ───────────

    const stHotspotGroups = ScrollTrigger.create({
      trigger: explorer,
      start: "top bottom",
      endTrigger: chapters.end,
      end: "bottom bottom",
      scrub: true,
      onUpdate: (self) => {
        updateHotspotGroupsByProgress(self.progress);
      },
      onLeave: () => {
        setActiveHotspotGroup("2");
      },
      onLeaveBack: () => {
        setActiveHotspotGroup(null);
      }
    });

    cleanups.push(() => stHotspotGroups.kill());

    // ─── Final init ────────────────────────────────────────────────────────

    if (modal) {
      modal.hidden = true;
      ensureModalMountedToBody();
    }

    syncColorUI();
    updateModalProgress();

    cleanups.push(() => {
      unlockExplorerScroll();

      if (modalMountedToBody && modal) {
        modal.remove();
      }
    });
  });

  window.UNCOMMON.bikeExplorerCleanup = () => {
    cleanups.forEach((fn) => fn());
    window.UNCOMMON.bikeExplorerCleanup = null;
  };
}

function initImageSequenceScroll(scope = nextPage) {
  if (window.innerWidth < 992) return;

  const page = getPageContainer(scope);
  if (!page) return;

  const wraps = Array.from(page.querySelectorAll('[data-sequence-wrap]')).filter(
    (wrap) =>
    !wrap.closest('[data-bike-explorer]') &&
    !wrap.closest('[data-home-hero]')
  );

  wraps.forEach((wrap) => {
    if (wrap.dataset.sequenceInit === 'true') return;
    wrap.dataset.sequenceInit = 'true';

    const element = wrap.querySelector('[data-sequence-element]');
    const canvas = element && element.querySelector('[data-sequence-canvas]');
    if (!element || !canvas) return;

    const frames = parseInt(canvas.dataset.frames, 10) || 1;
    const digits = parseInt(canvas.dataset.digits, 10) || 3;
    const indexStart = parseInt(canvas.dataset.indexStart, 10) || 0;
    const desktopSrc = canvas.dataset.desktopSrc || '';
    const staticSrc = canvas.dataset.staticSrc;
    const filetype = canvas.dataset.filetype || 'webp';
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    // --- Sticky alignment (new) ---
    // If `data-scroll-align-sticky="true"` is set on the wrap, the ScrollTrigger
    // is bound to the sticky's PARENT (the scrollable wrapper that defines the
    // pin range), so the scrub matches exactly the period that the sticky is pinned.
    const alignSticky = wrap.dataset.scrollAlignSticky === 'true';

    let triggerEl = wrap;
    let startTrigger = wrap.dataset.scrollStart || 'top top';
    let endTrigger = wrap.dataset.scrollEnd || 'bottom top';

    if (alignSticky) {
      let stickyAncestor = wrap.parentElement;
      while (stickyAncestor && stickyAncestor !== document.body) {
        if (window.getComputedStyle(stickyAncestor).position === 'sticky') break;
        stickyAncestor = stickyAncestor.parentElement;
      }

      if (stickyAncestor && stickyAncestor.parentElement) {
        triggerEl = stickyAncestor.parentElement;
        startTrigger = 'top top';
        endTrigger = 'bottom bottom';
      } else {
        console.warn(
          '[ImageSequence] data-scroll-align-sticky="true" is set, but no sticky ancestor was found. Falling back to default trigger.',
          wrap
        );
      }
    }
    // --- /Sticky alignment ---

    const baseUrl = desktopSrc;
    const lastIndex = indexStart + frames - 1;

    let lastProgress = 0;

    const ctx = canvas.getContext('2d');

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const width = element.clientWidth;
      const height = element.clientHeight;

      if (canvas.width !== width * dpr || canvas.height !== height * dpr) {
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
      }
    }

    resizeCanvas();

    const loaded = new Map();
    const queue = [];
    let processingQueue = false;
    let resizeTimer;

    function drawCover(img) {
      if (!img) return;

      resizeCanvas();

      const canvasWidth = canvas.width;
      const canvasHeight = canvas.height;
      const scale = Math.max(canvasWidth / img.width, canvasHeight / img.height);
      const x = (canvasWidth - img.width * scale) / 2;
      const y = (canvasHeight - img.height * scale) / 2;

      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      ctx.drawImage(img, x, y, img.width * scale, img.height * scale);
    }

    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeCanvas();
        if (loaded.size) render(lastProgress);
        ScrollTrigger.refresh();
      }, 200);
    });

    function pad(num) {
      return String(num).padStart(digits, '0');
    }

    function getUrl(i) {
      return `${baseUrl}${pad(i)}.${filetype}`;
    }

    function loadFrame(i, onDone) {
      if (loaded.has(i) || i < indexStart || i > lastIndex) return;

      const img = new Image();
      img.src = getUrl(i);

      img.onload = () => {
        loaded.set(i, img);
        if (typeof onDone === 'function') onDone();
      };

      img.onerror = () => {
        console.warn('[ImageSequence] Failed to load frame', {
          index: i,
          url: getUrl(i),
          wrap: wrap
        });
      };
    }

    function processQueue() {
      if (processingQueue) return;

      const next = queue.shift();
      if (!next) return;

      processingQueue = true;
      const [a, b] = next;

      if (b - a <= 1) {
        processingQueue = false;
        processQueue();
        return;
      }

      const m = Math.floor((a + b) / 2);

      loadFrame(m, () => {
        queue.push([a, m], [m, b]);
        processingQueue = false;
        setTimeout(processQueue, 0);
      });
    }

    function startLoading() {
      loadFrame(indexStart, () => {
        drawImageAt(indexStart);
        loadFrame(lastIndex);
        queue.push([indexStart, lastIndex]);
        processQueue();
        ScrollTrigger.refresh();
      });
    }

    function findNearestLoaded(i) {
      for (let r = 1; r <= 10; r++) {
        if (loaded.has(i - r)) return i - r;
        if (loaded.has(i + r)) return i + r;
      }

      const keys = Array.from(loaded.keys());
      if (keys.length === 0) return null;

      let nearest = keys[0];
      let minDiff = Math.abs(i - nearest);

      for (const k of keys) {
        const diff = Math.abs(i - k);
        if (diff < minDiff) {
          nearest = k;
          minDiff = diff;
        }
      }

      return nearest;
    }

    function drawImageAt(i) {
      const img = loaded.get(i);
      if (!img) return;
      drawCover(img);
    }

    function render(progress) {
      const relative = progress * (frames - 1);
      const index = indexStart + Math.round(relative);

      if (loaded.has(index)) {
        drawImageAt(index);
      } else {
        const nearest = findNearestLoaded(index);
        if (nearest !== null) drawImageAt(nearest);
      }
    }

    if (reduceMotion) {
      if (staticSrc) {
        const staticImage = new Image();
        staticImage.src = staticSrc;
        staticImage.onload = () => {
          drawCover(staticImage);
        };
        return;
      }

      loadFrame(indexStart, () => {
        drawImageAt(indexStart);
      });
      return;
    }

    startLoading();

    const st = ScrollTrigger.create({
      trigger: triggerEl,
      start: startTrigger,
      end: endTrigger,
      scrub: true,
      onUpdate: (self) => {
        lastProgress = self.progress;
        render(self.progress);
      }
    });

    lastProgress = st.progress || 0;
    render(lastProgress);
  });
}

function initBikeExplorerScrollIndicator(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.bikeExplorerScrollIndicatorCleanup) {
    window.UNCOMMON.bikeExplorerScrollIndicatorCleanup();
    window.UNCOMMON.bikeExplorerScrollIndicatorCleanup = null;
  }

  const page = getPageContainer(scope);
  const explorers = Array.from(page?.querySelectorAll("[data-bike-explorer]") || []);
  if (!explorers.length || typeof ScrollTrigger === "undefined") return;

  const cleanups = [];

  explorers.forEach((explorer) => {
    const fill = explorer.querySelector("[data-bike-scroll-fill]");
    if (!fill) return;

    gsap.set(fill, { width: "0%" });

    const st = ScrollTrigger.create({
      trigger: explorer,
      start: "top top",
      end: "bottom bottom",
      scrub: true,
      onUpdate: (self) => {
        gsap.set(fill, {
          width: `${self.progress * 100}%`
        });
      },
      onRefresh: (self) => {
        gsap.set(fill, {
          width: `${self.progress * 100}%`
        });
      }
    });

    cleanups.push(() => st.kill());
  });

  window.UNCOMMON.bikeExplorerScrollIndicatorCleanup = () => {
    cleanups.forEach((fn) => fn());
    window.UNCOMMON.bikeExplorerScrollIndicatorCleanup = null;
  };
}

