// DRAW PATH
// -----------------------------------------

function initDrawPathOnScroll(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.drawPathOnScrollCleanup) {
    window.UNCOMMON.drawPathOnScrollCleanup();
    window.UNCOMMON.drawPathOnScrollCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;

  if (typeof DrawSVGPlugin !== "undefined" && gsap.registerPlugin) {
    gsap.registerPlugin(ScrollTrigger, DrawSVGPlugin);
  } else if (gsap.registerPlugin) {
    gsap.registerPlugin(ScrollTrigger);
  }

  const page =
    typeof getPageContainer === "function" ?
    getPageContainer(scope) :
    scope || document;

  const wrappers = Array.from(page.querySelectorAll("[data-draw-scroll-wrap]"));
  if (!wrappers.length) return;

  const mm = gsap.matchMedia();

  function clamp(value, min = 0, max = 1) {
    return Math.max(min, Math.min(max, value));
  }

  function getActiveSvg(wrap, isMobile) {
    const desktopSVG = wrap.querySelector("[data-draw-scroll-desktop]");
    const mobileSVG = wrap.querySelector("[data-draw-scroll-mobile]");

    if (isMobile && mobileSVG) return mobileSVG;
    return desktopSVG || mobileSVG || null;
  }

  function getInactiveSvgs(wrap, activeSvg) {
    return Array.from(
      wrap.querySelectorAll("[data-draw-scroll-desktop], [data-draw-scroll-mobile]")
    ).filter((svg) => svg !== activeSvg);
  }

  function getViewBox(svg) {
    const vb = svg.viewBox && svg.viewBox.baseVal;

    if (vb && vb.width && vb.height) {
      return {
        x: vb.x,
        y: vb.y,
        width: vb.width,
        height: vb.height
      };
    }

    const attr = svg.getAttribute("viewBox");
    if (!attr) return null;

    const values = attr.split(/\s+/).map(Number);
    if (values.length !== 4 || values.some(Number.isNaN)) return null;

    return {
      x: values[0],
      y: values[1],
      width: values[2],
      height: values[3]
    };
  }

  function shouldCoverFit(item, wrap) {
    const mode = (wrap.getAttribute("data-draw-scroll-fit") || "auto").toLowerCase();

    if (mode === "cover") return true;
    if (mode === "none" || mode === "default" || mode === "native") return false;

    const itemRect = item.getBoundingClientRect();
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight;

    // Auto mode:
    // Only force-cover large scenic paths. Compact paths should behave like the original version.
    return itemRect.height > viewportHeight * 1.15;
  }

  function resetSvgFit(svg, wrap) {
    gsap.set(wrap, {
      clearProps: "position,left,top,right,bottom,width,height,overflow,pointerEvents"
    });

    gsap.set(svg, {
      clearProps: "position,left,top,width,height,maxWidth,overflow"
    });

    const overlay = wrap.querySelector(".draw-scroll__overlay");
    if (overlay) {
      gsap.set(overlay, {
        clearProps: "position,left,top,width,height,overflow,pointerEvents"
      });
    }
  }

  function coverFitSvgToItem(svg, wrap, item) {
    const viewBox = getViewBox(svg);
    if (!viewBox) return;

    const itemRect = item.getBoundingClientRect();
    const itemWidth = itemRect.width;
    const itemHeight = itemRect.height;

    if (!itemWidth || !itemHeight) return;

    const scale = Math.max(
      itemWidth / viewBox.width,
      itemHeight / viewBox.height
    );

    const svgWidth = viewBox.width * scale;
    const svgHeight = viewBox.height * scale;

    const left = (itemWidth - svgWidth) / 2;
    const top = (itemHeight - svgHeight) / 2;

    gsap.set(item, {
      position: "relative"
    });

    gsap.set(wrap, {
      position: "absolute",
      left: 0,
      top: 0,
      width: itemWidth,
      height: itemHeight,
      overflow: "visible",
      pointerEvents: "none"
    });

    gsap.set(svg, {
      position: "absolute",
      left,
      top,
      width: svgWidth,
      height: svgHeight,
      maxWidth: "none",
      overflow: "visible"
    });

    const overlay = wrap.querySelector(".draw-scroll__overlay");

    if (overlay) {
      gsap.set(overlay, {
        position: "absolute",
        left: 0,
        top: 0,
        width: itemWidth,
        height: itemHeight,
        overflow: "visible",
        pointerEvents: "none"
      });
    }
  }

  function getPathPoint(path, container, progress) {
    const totalLength = path.getTotalLength();
    const currentLength = totalLength * clamp(progress);
    const point = path.getPointAtLength(currentLength);

    const svg = path.ownerSVGElement;
    const svgPoint = svg.createSVGPoint();

    svgPoint.x = point.x;
    svgPoint.y = point.y;

    const ctm = path.getScreenCTM();
    if (!ctm) return { x: 0, y: 0 };

    const screenPoint = svgPoint.matrixTransform(ctm);
    const containerRect = container.getBoundingClientRect();

    return {
      x: screenPoint.x - containerRect.left,
      y: screenPoint.y - containerRect.top
    };
  }

  function setupPathForFallback(path) {
    const length = path.getTotalLength();

    gsap.set(path, {
      strokeDasharray: length,
      strokeDashoffset: length
    });

    return length;
  }

  function killWrapperTimeline(wrap) {
    if (!wrap._drawTl) return;

    if (wrap._drawTl.scrollTrigger) {
      wrap._drawTl.scrollTrigger.kill();
    }

    wrap._drawTl.kill();
    wrap._drawTl = null;
  }

  mm.add(
    {
      isDesktop: "(min-width: 768px)",
      isMobile: "(max-width: 767px)"
    },
    (context) => {
      const { isMobile } = context.conditions;

      wrappers.forEach((wrap) => {
        killWrapperTimeline(wrap);

        const item = wrap.closest("[data-draw-scroll-item]") || wrap;
        const svg = getActiveSvg(wrap, isMobile);

        if (!svg) return;

        const inactiveSvgs = getInactiveSvgs(wrap, svg);

        inactiveSvgs.forEach((inactiveSvg) => {
          gsap.set(inactiveSvg, {
            display: "none"
          });
        });

        gsap.set(svg, {
          display: "block"
        });

        const path = svg.querySelector("[data-draw-scroll-path]");
        if (!path) return;

        const marker = wrap.querySelector("[data-draw-marker]");
        const hasDrawSVG = typeof DrawSVGPlugin !== "undefined";
        const fallbackLength = hasDrawSVG ? null : setupPathForFallback(path);

        let useCoverFit = false;
        let markerContainer = wrap;
        let triggerElement = wrap;

        const setX = marker ? gsap.quickSetter(marker, "x", "px") : null;
        const setY = marker ? gsap.quickSetter(marker, "y", "px") : null;

        function updateMarker(progress) {
          if (!marker) return;

          const pos = getPathPoint(path, markerContainer, progress);

          setX(pos.x);
          setY(pos.y);
        }

        function refreshLayout(self) {
          useCoverFit = shouldCoverFit(item, wrap);

          if (useCoverFit) {
            coverFitSvgToItem(svg, wrap, item);
            markerContainer = wrap.querySelector(".draw-scroll__overlay") || wrap;
            triggerElement = item;
          } else {
            resetSvgFit(svg, wrap);
            markerContainer = wrap;
            triggerElement = item === wrap ? wrap : item;
          }

          updateMarker(self ? self.progress : 0);
        }

        refreshLayout();

        const tl = gsap.timeline({
          defaults: {
            ease: "none"
          },
          scrollTrigger: {
            trigger: triggerElement,
            start: "clamp(top center)",
            end: "clamp(bottom center)",
            scrub: true,
            invalidateOnRefresh: true,
            onRefreshInit: refreshLayout,
            onRefresh: (self) => {
              refreshLayout(self);
            },
            onUpdate: (self) => {
              updateMarker(self.progress);
            }
          }
        });

        if (hasDrawSVG) {
          tl.fromTo(
            path, { drawSVG: 0 }, { drawSVG: "100%", duration: 1 },
            0
          );
        } else {
          tl.to(
            path,
            {
              strokeDashoffset: 0,
              duration: 1
            },
            0
          );
        }

        updateMarker(0);

        wrap._drawTl = tl;
      });

      ScrollTrigger.refresh();

      return () => {
        wrappers.forEach((wrap) => {
          killWrapperTimeline(wrap);
        });
      };
    }
  );

  window.UNCOMMON.drawPathOnScrollCleanup = () => {
    mm.revert();

    wrappers.forEach((wrap) => {
      killWrapperTimeline(wrap);
    });

    window.UNCOMMON.drawPathOnScrollCleanup = null;
  };
}

function initDrawCoordsCounters() {
  const wrappers = document.querySelectorAll("[data-draw-scroll-wrap]");
  const SCALE = 10000;

  wrappers.forEach((wrap) => {
    const northEl = wrap.querySelector("[data-coords-north]");
    const westEl = wrap.querySelector("[data-coords-west]");

    if (!northEl || !westEl) {
      console.warn("North / West elements niet gevonden in:", wrap);
      return;
    }

    // Begin- en eindwaarden als integers
    const start = {
      north: 54.3439 * SCALE,
      west: 7.6321 * SCALE
    };

    const end = {
      north: 53.9843 * SCALE,
      west: 8.4629 * SCALE
    };

    const state = {
      north: start.north,
      west: start.west
    };

    function render() {
      const north = Math.round(state.north) / SCALE;
      const west = Math.round(state.west) / SCALE;

      northEl.textContent = `${north.toFixed(4)}°N`;
      westEl.textContent = `${west.toFixed(4)}°W`;
    }

    render();

    gsap.to(state, {
      north: end.north,
      west: end.west,
      ease: "none",
      scrollTrigger: {
        trigger: wrap,
        start: "clamp(top center)",
        end: "clamp(bottom center)",
        scrub: true,
        invalidateOnRefresh: true
      },
      onUpdate: render
    });
  });
}

function initDrawMarkerIntro() {
  const wrappers = document.querySelectorAll("[data-draw-scroll-wrap]");

  const introEase =
    typeof CustomEase !== "undefined" ?
    CustomEase.create("drawIntroEase", "0.625, 0.05, 0, 1") :
    "power3.out";

  function splitTextToChars(el) {
    const originalText = el.textContent;
    const chars = [...originalText];

    el.innerHTML = chars
      .map((char) => {
        const safeChar = char === " " ? "&nbsp;" : char;
        return `<span class="draw-scroll__coords-char">${safeChar}</span>`;
      })
      .join("");

    return {
      originalText,
      chars: Array.from(el.querySelectorAll(".draw-scroll__coords-char"))
    };
  }

  wrappers.forEach((wrap) => {
    const marker = wrap.querySelector("[data-draw-marker]");
    const northEl = wrap.querySelector("[data-coords-north]");
    const westEl = wrap.querySelector("[data-coords-west]");

    if (!marker || !northEl || !westEl) return;

    const northSplit = splitTextToChars(northEl);
    const westSplit = splitTextToChars(westEl);
    const allChars = [...northSplit.chars, ...westSplit.chars];

    gsap.set(marker, {
      scale: 0,
      autoAlpha: 0,
      transformOrigin: "50% 50%"
    });

    gsap.set(allChars, {
      yPercent: 110,
      autoAlpha: 0
    });

    const tl = gsap.timeline({
      defaults: {
        ease: introEase
      },
      scrollTrigger: {
        trigger: wrap,
        start: "top 50%", // begint later
        end: "top 30%", // korte scrub zone
        scrub: 0.6, // wat smoother / trager
        invalidateOnRefresh: true
      }
    });

    // eerst marker
    tl.to(marker, {
      scale: 1,
      autoAlpha: 1,
      duration: 3
    });

    // daarna coords
    tl.to(
      allChars,
      {
        yPercent: 0,
        autoAlpha: 1,
        duration: 3,
        stagger: 0.025
      },
      0.22
    );
  });
}

