    var strokeWidth = metrics.width * THICKNESS_SCALE;

    var inactiveLength = distance(metrics.inner, metrics.outer);
    var activeMaxLength = inactiveLength * ACTIVE_LENGTH_SCALE;

    var center = {
      x: (metrics.inner.x + metrics.outer.x) / 2,
      y: (metrics.inner.y + metrics.outer.y) / 2
    };

    var inactiveLine = createLine(center, center, INACTIVE_COLOR, strokeWidth);
    var activeLineA = createLine(center, center, ACTIVE_COLOR, strokeWidth);
    var activeLineB = createLine(center, center, ACTIVE_COLOR, strokeWidth);

    artGroup.appendChild(inactiveLine);
    artGroup.appendChild(activeLineA);
    artGroup.appendChild(activeLineB);

    var tickItem = {
      inactiveLine: inactiveLine,

      activeLineA: activeLineA,
      activeLineB: activeLineB,

      center: center,
      dir: metrics.dir,

      inactiveLength: inactiveLength,
      activeMaxLength: activeMaxLength,

      inactiveRevealProgress: 0,
      progress: 0,
      isActive: false,
      tween: null
    };

