function initPerformanceStickyIntro(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.performanceStickyIntroCleanup) {
    window.UNCOMMON.performanceStickyIntroCleanup();
    window.UNCOMMON.performanceStickyIntroCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;

  const page = getPageContainer(scope);
  const sticky = page?.querySelector(".performance-intro_sticky:not(.hide-desktop)");
  if (!sticky) return;

  const section = sticky.closest("section") || sticky.closest("[data-performance-mask-intro]");
  if (!section) return;

  const inner = sticky.querySelector(".performance-intro_inner");

  const namedTargets = Array.from(sticky.querySelectorAll("[data-intro-item]"));
  const grid = sticky.querySelector(".grid-col-12");
  const targets = namedTargets.length ?
    namedTargets :
    grid ?
    Array.from(grid.children) :
    Array.from(sticky.children);

  if (!targets.length) return;

  if (reducedMotion) {
    gsap.set(targets, { autoAlpha: 1, y: 0 });
    return;
  }

  gsap.set(targets, { autoAlpha: 0, y: "3em" });

  // Intro: items scrubben in
  const tl = gsap.timeline({
    scrollTrigger: {
      __performanceStickyIntro: true,
      trigger: section,
      start: "top -10%",
      end: "+=600",
      scrub: true,
      invalidateOnRefresh: true
    }
  });

  tl.to(targets, {
    autoAlpha: 1,
    y: 0,
    duration: 1,
    stagger: 0.15,
    ease: "none"
  });

  // Parallax: inner beweegt langzaam omhoog over de gehele sectie
  let stParallax = null;

  if (inner) {
    gsap.set(inner, { y: "4em" });

    stParallax = gsap.to(inner, {
      y: "-4em",
      ease: "none",
      scrollTrigger: {
        __performanceStickyIntroParallax: true,
        trigger: section,
        start: "top bottom",
        end: "bottom top",
        scrub: true,
        invalidateOnRefresh: true
      }
    });
  }

  window.UNCOMMON.performanceStickyIntroCleanup = function () {
    tl.scrollTrigger?.kill();
    tl.kill();
    if (stParallax) {
      stParallax.scrollTrigger?.kill();
      stParallax.kill();
    }
    gsap.killTweensOf(targets);
    if (inner) gsap.killTweensOf(inner);
    gsap.set(targets, { clearProps: "all" });
    if (inner) gsap.set(inner, { clearProps: "all" });
    window.UNCOMMON.performanceStickyIntroCleanup = null;
  };
}

function initWordScrubTrack(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.wordScrubTrackCleanup) {
    window.UNCOMMON.wordScrubTrackCleanup();
    window.UNCOMMON.wordScrubTrackCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;
  if (typeof SplitText === "undefined") {
    console.warn("initWordScrubTrack: GSAP SplitText is required.");
    return;
  }

  gsap.registerPlugin(ScrollTrigger, SplitText);

  const page = getPageContainer(scope);
  const texts = Array.from(page?.querySelectorAll("[data-word-scrub]") || []);
  if (!texts.length) return;

  const cleanups = [];

  function parseNumber(value, fallback) {
    const n = parseFloat(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function parseOpacity(value, fallback) {
    const n = parseFloat(value);
    if (!Number.isFinite(n)) return fallback;
    return gsap.utils.clamp(0, 1, n);
  }

  function parseScrub(value, fallback = true) {
    if (value == null || value === "") return fallback;
    if (value === "true") return true;
    if (value === "false") return false;

    const n = parseFloat(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function resolveTrigger(el) {
    const raw = el.getAttribute("data-word-scrub-trigger");
    if (!raw || raw === "self") return el;

    if (raw === "parent") return el.parentElement || el;
    if (raw === "row") return el.closest(".story-content_row") || el;

    if (raw.startsWith("closest:")) {
      const selector = raw.replace("closest:", "").trim();
      return el.closest(selector) || el;
    }

    if (raw.startsWith("selector:")) {
      const selector = raw.replace("selector:", "").trim();
      return page?.querySelector(selector) || el;
    }

    return el.closest(raw) || el;
  }

  texts.forEach((text) => {
    const start = text.getAttribute("data-word-scrub-start") || "top 82%";
    const end = text.getAttribute("data-word-scrub-end") || "top 52%";
    const scrub = parseScrub(text.getAttribute("data-word-scrub-scrub"), true);

    // More noticeable defaults
    const blurFrom = parseNumber(text.getAttribute("data-word-scrub-blur"), 16);
    const yFrom = parseNumber(text.getAttribute("data-word-scrub-y"), 0.6);
    const opacityFrom = parseOpacity(text.getAttribute("data-word-scrub-opacity"), 0);
    const staggerEach = parseNumber(text.getAttribute("data-word-scrub-stagger"), 0.04);
    const staggerFrom = text.getAttribute("data-word-scrub-from") || "start";
    const trigger = resolveTrigger(text);

    const split = new SplitText(text, {
      type: "words",
      wordsClass: "word-scrub-word"
    });

    const words = split.words || [];
    const svgs = Array.from(text.querySelectorAll("svg"));
    const revealItems = Array.from(text.querySelectorAll(".word-scrub-word, svg"));

    if (!revealItems.length) {
      split.revert();
      return;
    }

    if (reducedMotion) {
      gsap.set(revealItems, { clearProps: "all" });

      cleanups.push(() => {
        split.revert();
      });

      return;
    }

    if (words.length) {
      gsap.set(words, {
        display: "inline-block",
        willChange: "transform,filter,opacity",
        filter: `blur(${blurFrom}px)`,
        opacity: opacityFrom,
        y: `${yFrom}em`,
        transformOrigin: "50% 50%",
        force3D: true
      });
    }

    if (svgs.length) {
      gsap.set(svgs, {
        display: "inline-block",
        willChange: "transform,filter,opacity",
        filter: `blur(${blurFrom}px)`,
        opacity: opacityFrom,
        y: `${yFrom}em`,
        transformOrigin: "50% 50%",
        force3D: true
      });
    }

    const tl = gsap.timeline({
      defaults: { ease: "none" },
      scrollTrigger: {
        trigger,
        start,
        end,
        scrub,
        invalidateOnRefresh: true
      }
    });

    tl.to(revealItems, {
      filter: "blur(0px)",
      opacity: 1,
      y: "0em",
      stagger: {
        each: staggerEach,
        from: staggerFrom
      },
      duration: 1
    });

    cleanups.push(() => {
      tl.scrollTrigger?.kill();
      tl.kill();
      split.revert();
    });
  });

  window.UNCOMMON.wordScrubTrackCleanup = function () {
    cleanups.forEach((fn) => fn());
    window.UNCOMMON.wordScrubTrackCleanup = null;
  };
}

// -----------------------------------------
// STORY HERO
// -----------------------------------------

function initStoryHeroMorph(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.storyHeroMorphCleanup) {
    window.UNCOMMON.storyHeroMorphCleanup();
    window.UNCOMMON.storyHeroMorphCleanup = null;
  }

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") return;

  const page = getPageContainer(scope);
  const hero = page?.querySelector("[data-story-hero]");
  if (!hero) return;

  const wrapper = hero.querySelector(".story-hero__wrapper");
  const media = hero.querySelector("[data-story-hero-media]");
  const target = hero.querySelector("[data-story-media-target]");

  if (!wrapper || !media || !target) {
    console.warn("[StoryHeroMorph] Missing required elements", {
      wrapper,
      media,
      target
    });
    return;
  }

  const mm = gsap.matchMedia();

  mm.add("(min-width: 992px)", () => {
    if (reducedMotion) return;

    let tl = null;

    function getRelativeBounds(el, relativeTo) {
      const elRect = el.getBoundingClientRect();
      const parentRect = relativeTo.getBoundingClientRect();

      return {
        x: elRect.left - parentRect.left,
        y: elRect.top - parentRect.top,
        width: elRect.width,
        height: elRect.height
      };
    }

    function getTargetRadius() {
      const styles = window.getComputedStyle(target);
      return parseFloat(styles.borderTopLeftRadius) || 0;
    }

    function setStartState() {
      gsap.set(media, {
        position: "absolute",
        left: 0,
        top: 0,
        x: 0,
        y: 0,
        width: wrapper.offsetWidth,
        height: wrapper.offsetHeight,
        borderRadius: 0,
        overflow: "hidden",
        transformOrigin: "top left"
      });
    }

    function getEndState() {
      return getRelativeBounds(target, wrapper);
    }

    function validateTarget() {
      const end = getEndState();

      if (!end.width || !end.height) {
        console.warn("[StoryHeroMorph] Target has no measurable size.", end);
        return false;
      }

      return true;
    }

    setStartState();

    if (!validateTarget()) return;

    tl = gsap.timeline({
      scrollTrigger: {
        trigger: hero,
        start: "top top",
        end: "+=150%",
        pin: hero,
        pinSpacing: true,
        scrub: 0.7,
        anticipatePin: 1,
        invalidateOnRefresh: true,
        onRefreshInit: () => {
          setStartState();
        },
        onRefresh: () => {
          validateTarget();
        }
      }
    });

    tl.to(media, {
      x: () => getEndState().x,
      y: () => getEndState().y,
      width: () => getEndState().width,
      height: () => getEndState().height,
      borderRadius: () => getTargetRadius(),
      ease: "none"
    }, 0);

    return () => {
      tl?.scrollTrigger?.kill();
      tl?.kill();

      gsap.set(media, {
        clearProps: "position,left,top,x,y,width,height,borderRadius,overflow,transformOrigin"
      });
    };
  });

  window.UNCOMMON.storyHeroMorphCleanup = function () {
    mm.revert();
    window.UNCOMMON.storyHeroMorphCleanup = null;
  };
}

// -----------------------------------------
// FEATURE PILLS
// -----------------------------------------

function initExpandingFeaturePills(scope = nextPage) {
  window.UNCOMMON = window.UNCOMMON || {};

  if (window.UNCOMMON.featurePillsCleanup) {
    window.UNCOMMON.featurePillsCleanup();
    window.UNCOMMON.featurePillsCleanup = null;
  }

  const page = getPageContainer(scope);
  const wraps = Array.from(page?.querySelectorAll("[data-feature-pills-init]") || []);
  if (!wraps.length) return;

  const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const cleanups = [];

  wraps.forEach((wrap, wrapIdx) => {
    const items = Array.from(wrap.querySelectorAll("[data-feature-pills-item]"));
    const visuals = Array.from(wrap.querySelectorAll("[data-feature-pills-visual]"));

    if (!items.length) return;

    if (visuals.length && visuals.length !== items.length) {
      console.warn(
        `[ExpandingFeaturePills] items (${items.length}) and visuals (${visuals.length}) mismatch in module #${wrapIdx}. Visual syncing uses index order.`
      );
    }

    const uidBase = `feature-pills-${wrapIdx}`;
    const ease = "uncommon";
    const animationDuration = 0.5;

    let activeIndex = 0;
    let mediaPlayToken = 0;

    const getExpandedWidth = () =>
      getComputedStyle(wrap).getPropertyValue("--content-item-expanded").trim() || "";

    const setWrapActive = () => {
      wrap.setAttribute("data-feature-pills-active", "true");
    };

    const getVisualByIndex = (index) =>
      visuals.find((visual) => Number(visual.getAttribute("data-feature-pills-index")) ===
        index) ||
      null;

    const getMediaParts = (visual) => {
      if (!visual) return { mediaRoot: null, video: null };

      const mediaRoot = visual.querySelector("[data-media-init]") || visual;
      const video =
        mediaRoot.querySelector("[data-media-video-src]") ||
        mediaRoot.querySelector("video");

      return { mediaRoot, video };
    };

    const prepareVideo = (video, mediaRoot) => {
      if (!video) return;

      const src = video.dataset.mediaVideoSrc || video.getAttribute("data-media-video-src");
      if (!video.getAttribute("src") && src) {
        video.src = src;
        video.load();
      }

      video.muted = true;
      video.defaultMuted = true;
      video.playsInline = true;
      video.setAttribute("muted", "");
      video.setAttribute("playsinline", "");
      video.setAttribute("webkit-playsinline", "");
      video.loop = false;
      video.removeAttribute("loop");

      if (mediaRoot) {
        mediaRoot.setAttribute("data-media-status", "not-active");
      }
    };

    const pauseAndResetVisualMedia = (visual) => {
      const { mediaRoot, video } = getMediaParts(visual);
      if (!video) return;

      prepareVideo(video, mediaRoot);

      try {
        video.pause();
      } catch (_) {}

      try {
        video.currentTime = 0;
      } catch (_) {}

      if (mediaRoot) {
        mediaRoot.setAttribute("data-media-status", "not-active");
      }
    };

    const playVisualMedia = (visual, index) => {
      const { mediaRoot, video } = getMediaParts(visual);
      if (!video) return;

      prepareVideo(video, mediaRoot);

      if (prefersReducedMotion) {
        try {
          video.pause();
          video.currentTime = 0;
        } catch (_) {}
        if (mediaRoot) mediaRoot.setAttribute("data-media-status", "paused");
        return;
      }

      const token = ++mediaPlayToken;

      const attemptPlay = () => {
        if (token !== mediaPlayToken) return;
        if (activeIndex !== index) return;

        try {
          video.pause();
        } catch (_) {}

        const playNow = () => {
          if (token !== mediaPlayToken) return;
          if (activeIndex !== index) return;

          if (mediaRoot) {
            mediaRoot.setAttribute("data-media-status", "loading");
          }

          const playPromise = video.play();

          if (playPromise && typeof playPromise.then === "function") {
            playPromise
              .then(() => {
                if (token !== mediaPlayToken) return;
                if (activeIndex !== index) return;
                if (mediaRoot) mediaRoot.setAttribute("data-media-status", "playing");
              })
              .catch(() => {
                if (mediaRoot) mediaRoot.setAttribute("data-media-status", "paused");
              });
          } else if (mediaRoot) {
            mediaRoot.setAttribute("data-media-status", "playing");
          }
        };

        if (video.readyState >= 1) {
          try {
            video.currentTime = 0;
          } catch (_) {}
          playNow();
        } else {
          const onLoadedMeta = () => {
            video.removeEventListener("loadedmetadata", onLoadedMeta);
            try {
              video.currentTime = 0;
            } catch (_) {}
            playNow();
          };

          video.addEventListener("loadedmetadata", onLoadedMeta);
        }
      };

      if (video.readyState >= 2) {
        attemptPlay();
      } else {
        const onCanPlay = () => {
          video.removeEventListener("canplay", onCanPlay);
          attemptPlay();
        };

        video.addEventListener("canplay", onCanPlay);
      }
    };

    const setVisualActive = (index) => {
      visuals.forEach((visual) => {
        const visualIndex = Number(visual.getAttribute("data-feature-pills-index"));
        const isActive = visualIndex === index;

        visual.setAttribute("data-active", isActive ? "true" : "false");
        visual.setAttribute("aria-hidden", isActive ? "false" : "true");

        if (!isActive) {
          pauseAndResetVisualMedia(visual);
        }
      });

      const activeVisual = getVisualByIndex(index);
      if (activeVisual) {
        playVisualMedia(activeVisual, index);
      }
    };

    const setItemA11y = (item, isOpen) => {
      const btn = item.querySelector("[data-feature-pills-button]");
      const content = item.querySelector("[data-feature-pills-content]");
      if (!btn || !content) return;

      btn.setAttribute("aria-expanded", isOpen ? "true" : "false");
      content.setAttribute("aria-hidden", isOpen ? "false" : "true");
    };

    const measureButtonH = (item) => {
      const btn = item.querySelector("[data-feature-pills-button]");
      return btn ? Math.ceil(btn.getBoundingClientRect().height) : 0;
    };

    const measureInnerH = (item, expandedW) => {
      const inner = item.querySelector("[data-feature-pills-inner]");
      if (!inner) return 0;

      const mask = item.querySelector(".feature-pills__item-mask");

      const prevMaskOverflow = mask ? mask.style.overflow : null;
      if (mask) mask.style.overflow = "visible";

      const prevMaxW = inner.style.maxWidth;
      if (expandedW) inner.style.maxWidth = expandedW;

      const h = Math.ceil(inner.getBoundingClientRect().height);

      if (expandedW) inner.style.maxWidth = prevMaxW || "";
      if (mask) mask.style.overflow = prevMaskOverflow || "";

      return h;
    };

    const getHeights = (item, expandedW) => {
      const buttonH = measureButtonH(item);
      const innerH = measureInnerH(item, expandedW);
      const openH = Math.max(buttonH, innerH);
      return { buttonH, openH };
    };

    const collapsedWidthPx = new Map();

    const captureCollapsedWidths = () => {
      items.forEach((item) => {
        const prevWidth = item.style.width;
        item.style.width = "";
        collapsedWidthPx.set(item, Math.ceil(item.getBoundingClientRect().width));
        item.style.width = prevWidth;
      });
    };

    const animateBox = (el, vars, immediate = false) => {
      gsap.killTweensOf(el);

      if (prefersReducedMotion || immediate) {
        if (vars.height != null) el.style.height = `${vars.height}px`;
        if (vars.width != null) {
          el.style.width = typeof vars.width === "number" ? `${vars.width}px` : vars.width;
        }
        return;
      }

      gsap.to(el, {
        ...vars,
        duration: animationDuration,
        ease,
        overwrite: true
      });
    };

    const openItem = (item, immediate = false) => {
      const expandedW = getExpandedWidth();
      const { openH } = getHeights(item, expandedW);

      item.setAttribute("data-active", "true");
      setItemA11y(item, true);
      setWrapActive();

      const targetW =
        expandedW ||
        `${collapsedWidthPx.get(item) || Math.ceil(item.getBoundingClientRect().width)}px`;

      animateBox(item, { height: openH, width: targetW }, immediate);
    };

    const closeItem = (item, immediate = false) => {
      const expandedW = getExpandedWidth();
      const { buttonH } = getHeights(item, expandedW);

      item.setAttribute("data-active", "false");
      setItemA11y(item, false);

      const targetW =
        collapsedWidthPx.get(item) || Math.ceil(item.getBoundingClientRect().width);

      animateBox(item, { height: buttonH, width: targetW }, immediate);
    };

    const switchTo = (nextIndex) => {
      if (nextIndex === activeIndex) return;

      const nextItem = items[nextIndex];
      const currentItem = items[activeIndex];

      if (!nextItem || !currentItem) return;

      closeItem(currentItem);
      openItem(nextItem);

      activeIndex = nextIndex;
      setVisualActive(activeIndex);
    };

    items.forEach((item, i) => {
      item.setAttribute("data-feature-pills-index", String(i));

      const btn = item.querySelector("[data-feature-pills-button]");
      const content = item.querySelector("[data-feature-pills-content]");

      if (btn) {
        btn.setAttribute("data-feature-pills-index", String(i));
        btn.type = "button";

        const triggerId = `${uidBase}-trigger-${i}`;
        if (!btn.id) btn.id = triggerId;
      }

      if (content && btn) {
        content.setAttribute("data-feature-pills-index", String(i));

        const panelId = `${uidBase}-panel-${i}`;
        if (!content.id) content.id = panelId;

        btn.setAttribute("aria-controls", content.id);
        content.setAttribute("role", "region");
        content.setAttribute("aria-labelledby", btn.id);
      }
    });

    visuals.forEach((visual, i) => {
      visual.setAttribute("data-feature-pills-index", String(i));
      visual.setAttribute("aria-hidden", "true");

      const { mediaRoot, video } = getMediaParts(visual);
      if (video) {
        prepareVideo(video, mediaRoot);

        const handleEnded = () => {
          if (Number(visual.getAttribute("data-feature-pills-index")) !== activeIndex)
            return;
          if (mediaRoot) mediaRoot.setAttribute("data-media-status", "ended");
        };

        const handleWaiting = () => {
          if (Number(visual.getAttribute("data-feature-pills-index")) !== activeIndex)
            return;
          if (mediaRoot) mediaRoot.setAttribute("data-media-status", "loading");
        };

        const handlePause = () => {
          if (Number(visual.getAttribute("data-feature-pills-index")) !== activeIndex)
            return;
          if (mediaRoot && !video.ended) mediaRoot.setAttribute("data-media-status",
            "paused");
        };

        const handlePlaying = () => {
          if (Number(visual.getAttribute("data-feature-pills-index")) !== activeIndex)
            return;
          if (mediaRoot) mediaRoot.setAttribute("data-media-status", "playing");
        };

        video.addEventListener("ended", handleEnded);
        video.addEventListener("waiting", handleWaiting);
        video.addEventListener("pause", handlePause);
        video.addEventListener("playing", handlePlaying);

        cleanups.push(() => {
          video.removeEventListener("ended", handleEnded);
          video.removeEventListener("waiting", handleWaiting);
          video.removeEventListener("pause", handlePause);
          video.removeEventListener("playing", handlePlaying);
        });
      }
    });

    captureCollapsedWidths();

    items.forEach((item, i) => {
      if (i === 0) return;
      closeItem(item, true);
    });

    activeIndex = 0;
    openItem(items[0], true);
    setVisualActive(activeIndex);

    items.forEach((item, i) => {
      const btn = item.querySelector("[data-feature-pills-button]");
      if (!btn) return;

      const onClick = () => switchTo(i);
      btn.addEventListener("click", onClick);
      cleanups.push(() => btn.removeEventListener("click", onClick));
    });

    const onKeydown = (e) => {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        switchTo((activeIndex + 1) % items.length);
      }

      if (e.key === "ArrowLeft") {
        e.preventDefault();
        switchTo((activeIndex - 1 + items.length) % items.length);
      }
    };

    wrap.addEventListener("keydown", onKeydown);
    cleanups.push(() => wrap.removeEventListener("keydown", onKeydown));

    const debounce = (fn, wait = 150) => {
      let t;
      return (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn(...args), wait);
      };
    };

    const handleResize = () => {
      items.forEach((item, i) => {
        if (i !== activeIndex) item.style.width = "";
      });

      captureCollapsedWidths();

      items.forEach((item, i) => {
        if (i === activeIndex) {
          const expandedW = getExpandedWidth();
          const { openH } = getHeights(item, expandedW);
          const targetW = expandedW ||
            `${Math.ceil(item.getBoundingClientRect().width)}px`;

          if (prefersReducedMotion) {
            item.style.height = `${openH}px`;
            item.style.width = targetW;
          } else {
            gsap.set(item, { height: openH, width: targetW });
            item.style.width = targetW;
          }
        } else {
          const buttonH = measureButtonH(item);
          const targetW =
            collapsedWidthPx.get(item) || Math.ceil(item.getBoundingClientRect().width);

          if (prefersReducedMotion) {
            item.style.height = `${buttonH}px`;
            item.style.width = `${targetW}px`;
          } else {
            gsap.set(item, { height: buttonH, width: targetW });
          }
        }
      });

      positionActivePlaybackAfterResize();
    };

    const positionActivePlaybackAfterResize = () => {
      const activeVisual = getVisualByIndex(activeIndex);
      const { video } = getMediaParts(activeVisual);
      if (!video) return;

      if (video.paused || video.ended) return;

      try {
        const t = video.currentTime;
        video.currentTime = t;
      } catch (_) {}
    };

    const debouncedResize = debounce(handleResize, 200);
    window.addEventListener("resize", debouncedResize, { passive: true });
    cleanups.push(() => window.removeEventListener("resize", debouncedResize));
  });

  window.UNCOMMON.featurePillsCleanup = function () {
    cleanups.forEach((cleanup) => cleanup());
    window.UNCOMMON.featurePillsCleanup = null;
  };
}

// -----------------------------------------
// MARQUEE
// -----------------------------------------

function initDraggableMarquee() {
  const wrappers = document.querySelectorAll("[data-draggable-marquee-init]");

  const getNumberAttr = (el, name, fallback) => {
    const value = parseFloat(el.getAttribute(name));
    return Number.isFinite(value) ? value : fallback;
  };

  wrappers.forEach((wrapper) => {
    if (wrapper.getAttribute("data-draggable-marquee-init") === "initialized") return;

    const collection = wrapper.querySelector("[data-draggable-marquee-collection]");
    const list = wrapper.querySelector("[data-draggable-marquee-list]");
    if (!collection || !list) return;

    const duration = getNumberAttr(wrapper, "data-duration", 20);
    const multiplier = getNumberAttr(wrapper, "data-multiplier", 40);
    const sensitivity = getNumberAttr(wrapper, "data-sensitivity", 0.01);

    const wrapperWidth = wrapper.getBoundingClientRect().width;
    const listWidth = list.scrollWidth || list.getBoundingClientRect().width;
    if (!wrapperWidth || !listWidth) return;

    // Make enough duplicates to cover screen
    const minRequiredWidth = wrapperWidth + listWidth + 2;
    while (collection.scrollWidth < minRequiredWidth) {
      const listClone = list.cloneNode(true);
      listClone.setAttribute("data-draggable-marquee-clone", "");
      listClone.setAttribute("aria-hidden", "true");
      collection.appendChild(listClone);
    }

    const wrapX = gsap.utils.wrap(-listWidth, 0);

    gsap.set(collection, { x: 0 });

    const marqueeLoop = gsap.to(collection, {
      x: -listWidth,
      duration,
      ease: "none",
      repeat: -1,
      onReverseComplete: () => marqueeLoop.progress(1),
      modifiers: {
        x: (x) => wrapX(parseFloat(x)) + "px"
      },
    });

    // Direction can be used for css + set initial direction on load
    const initialDirectionAttr = (wrapper.getAttribute("data-direction") || "left")
      .toLowerCase();
    const baseDirection = initialDirectionAttr === "right" ? -1 : 1;

    const timeScale = { value: 1 };

    timeScale.value = baseDirection;
    wrapper.setAttribute("data-direction", baseDirection < 0 ? "right" : "left");

    if (baseDirection < 0) marqueeLoop.progress(1);

    function applyTimeScale() {
      marqueeLoop.timeScale(timeScale.value);
      wrapper.setAttribute("data-direction", timeScale.value < 0 ? "right" : "left");
    }

    applyTimeScale();

    // Drag observer
    const marqueeObserver = Observer.create({
      target: wrapper,
      type: "pointer,touch",
      preventDefault: true,
      debounce: false,
      onChangeX: (observerEvent) => {
        let velocityTimeScale = observerEvent.velocityX * -sensitivity;
        velocityTimeScale = gsap.utils.clamp(-multiplier, multiplier, velocityTimeScale);

        gsap.killTweensOf(timeScale);

        const restingDirection = velocityTimeScale < 0 ? -1 : 1;

        gsap.timeline({ onUpdate: applyTimeScale })
          .to(timeScale, { value: velocityTimeScale, duration: 0.1, overwrite: true })
          .to(timeScale, { value: restingDirection, duration: 1.0 });
      }
    });

    // Pause marquee when scrolled out of view
    ScrollTrigger.create({
      trigger: wrapper,
      start: "top bottom",
      end: "bottom top",
      onEnter: () => {
        marqueeLoop.resume();
        applyTimeScale();
        marqueeObserver.enable();
      },
      onEnterBack: () => {
        marqueeLoop.resume();
        applyTimeScale();
        marqueeObserver.enable();
      },
      onLeave: () => {
        marqueeLoop.pause();
        marqueeObserver.disable();
      },
      onLeaveBack: () => {
        marqueeLoop.pause();
        marqueeObserver.disable();
      }
    });

    wrapper.setAttribute("data-draggable-marquee-init", "initialized");
  });
}

// -----------------------------------------
// WORLDMAP HIGHLIGHT
// -----------------------------------------

function initWorldmapHighlight(page) {
  const scope = page || document;
  const trigger = scope.querySelector(".worldmap");
  const svg = scope.querySelector(".worldmap__core");
  const nl = scope.querySelector(".country-nl");

  if (!trigger || !svg || !nl) return;

  if (typeof gsap === "undefined" || typeof ScrollTrigger === "undefined") {
    console.warn("[worldmapHighlight] GSAP of ScrollTrigger niet geladen");
    return;
  }

  gsap.registerPlugin(ScrollTrigger);

  const COLOR_IDLE = "#212623";
  const COLOR_ACTIVE = "#FDEB07";

  // Reduced motion: direct op eindstate, geen animatie
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    gsap.set(nl, { attr: { fill: COLOR_ACTIVE } });
    return;
  }

  // SVG viewBox is "0 0 2516 1078" → NL ligt rond x≈1280, y≈220
  const ZOOM_LEVEL = 4;
  const FOCUS_X = "51%";
  const FOCUS_Y = "22%";

  // Initiele state — ingezoomd op NL + grijs
  gsap.set(svg, {
    transformOrigin: `${FOCUS_X} ${FOCUS_Y}`,
    scale: ZOOM_LEVEL
  });
  gsap.set(nl, {
    attr: { fill: COLOR_IDLE },
    filter: "drop-shadow(0 0 0px rgba(253,235,7,0))"
  });

  // NL pulse: kleur + glow flash + residu glow
  const pulse = (el) =>
    gsap.timeline()
    .to(el, {
      attr: { fill: COLOR_ACTIVE },
      duration: 0.4,
      ease: "power2.out"
    }, 0)
    .fromTo(
      el, { filter: "drop-shadow(0 0 0px rgba(253,235,7,0))" }, {
        filter: "drop-shadow(0 0 12px rgba(253,235,7,0.9))",
        duration: 0.35,
        ease: "power2.out"
      },
      0
    )
    .to(el, {
      filter: "drop-shadow(0 0 4px rgba(253,235,7,0.4))",
      duration: 0.6,
      ease: "power2.inOut"
    });

  // Master timeline met ScrollTrigger
  const master = gsap.timeline({
    scrollTrigger: {
      trigger: trigger,
      start: "top 70%",
      once: true
    },
    delay: 1
  });

  master
    .add(pulse(nl))
    .to(svg, {
      scale: 1,
      duration: 1.8,
      ease: "power3.inOut"
    }, "-=0.3");

  return () => {
    master.scrollTrigger?.kill();
    master.kill();
  };
}

function reinitWebflowAfterBarba() {
  if (!window.Webflow) return;

  try {
    // Re-init algemene Webflow modules/interactions
    window.Webflow.destroy();
    window.Webflow.ready();

    // Re-init Webflow IX2 interactions, als je die gebruikt
    if (window.Webflow.require) {
      const ix2 = window.Webflow.require("ix2");
      if (ix2 && typeof ix2.init === "function") {
        ix2.init();
      }

      const forms = window.Webflow.require("forms");
      if (forms && typeof forms.ready === "function") {
        forms.ready();
      }
    }
  } catch (error) {
    console.warn("[Webflow] Re-init after Barba failed:", error);
  }
}





