// -------------------------------------------------------------
(function() {
  function startUNCOMMON() {
    if (window.__UNCOMMON_STARTED__) return;
    window.__UNCOMMON_STARTED__ = true;

    try {
      if (typeof initOnceFunctions === "function") initOnceFunctions();

      const container = document.querySelector('[data-barba="container"]') || document.querySelector('main') || document.body;
      if (typeof syncNavStateInstant === "function") syncNavStateInstant(container, null);
      if (typeof prepareHeroBeforeEnter === "function") prepareHeroBeforeEnter(container);
      if (typeof initAfterEnterFunctions === "function") initAfterEnterFunctions(container);

      if (typeof lenis !== "undefined" && lenis && typeof lenis.start === "function") {
        lenis.start();
      }
      if (typeof ScrollTrigger !== "undefined" && ScrollTrigger.refresh) {
        ScrollTrigger.refresh();
      }
      console.log("[UNCOMMON] Radian EXR exact animations active.");
    } catch (err) {
      console.warn("[UNCOMMON] Bootstrapper note:", err);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startUNCOMMON);
  } else {
    setTimeout(startUNCOMMON, 50);
  }
})();
